        try { $record = $diagnosticText | ConvertFrom-Json } catch { }
        $knownFormat = $null -ne $record -and $record -is [pscustomobject] -and
            $null -ne $record.PSObject.Properties['schema'] -and
            $record.schema -is [string] -and
            $record.schema -ceq 'label-match-placement-child-failure-v1' -and
            $null -ne $record.PSObject.Properties['exit_code'] -and
            ($record.exit_code -is [int] -or $record.exit_code -is [long])
        if ($knownFormat) {
            if ($record.exit_code -ne $childExit) { throw 'Placement child failure evidence differs.' }
            $Script:LabelPlacementChildFailure = $record
        } else {
            if ($childExit -eq 0) { throw 'Placement child failure evidence differs.' }
            $fallback=[ordered]@{schema='label-match-placement-child-failure-v1';phase='CHILD_EXIT';placement_code='PLACEMENT_DIAGNOSTIC_UNAVAILABLE';exit_code=$childExit;exception_type='System.InvalidOperationException';hresult=0;message=[string]$Script:KmtechRedactionRules.safe_messages[0];diagnostic_format='진단 형식 모름'}
            # Retain the original record verbatim in protected evidence, including
            # its reason/first cause. Never publish an unvalidated diagnostic.
            try { $fallback.full_exception_trace=Write-KmtechProtectedFailureSidecar -Text $diagnosticText }
            catch { $fallback.trace_failure_type=$_.Exception.GetType().Name }
            $Script:LabelPlacementChildFailure = $fallback
        }
        if ($knownFormat -and $null -ne $record.PSObject.Properties['full_exception_trace']) {
            $tracePath = [string]$record.full_exception_trace.path
            if ($tracePath -cne ($failurePath + '.trace.txt')) { throw 'Placement trace path differs.' }
            $traceItem = Get-Item -Force -LiteralPath $tracePath
            if (($traceItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $traceItem.Length -gt 65536) { throw 'Placement trace is not a bounded ordinary file.' }
            $traceBytes = [IO.File]::ReadAllBytes($tracePath)
            if ((ByteSha $traceBytes) -cne [string]$record.full_exception_trace.sha256) { throw 'Placement trace bytes differ.' }
            $record | Add-Member -NotePropertyName full_exception_trace_text -NotePropertyValue ((New-Object Text.UTF8Encoding($false,$true)).GetString($traceBytes))
        }
    }
    if ($childExit -ne 0 -and $null -eq $Script:LabelPlacementChildFailure) {
        $fallback=[ordered]@{schema='label-match-placement-child-failure-v1';phase='CHILD_EXIT';placement_code='PLACEMENT_DIAGNOSTIC_UNAVAILABLE';exit_code=$childExit;exception_type='System.InvalidOperationException';hresult=0;message=[string]$Script:KmtechRedactionRules.safe_messages[0]}
        try { $fallback.full_exception_trace=Write-KmtechProtectedFailureSidecar -Text ($fallback|ConvertTo-Json -Compress) }
        catch { $fallback.trace_failure_type=$_.Exception.GetType().Name }
        $Script:LabelPlacementChildFailure=$fallback
    }
    $Script:LabelPlacementChildFailure=ConvertTo-LabelPlacementPublicFailure $Script:LabelPlacementChildFailure
    return $childExit
    }
    catch {
        $originalPlacementFailure=$_
        if ($null -eq $Script:LabelPlacementChildFailure) {
            $reference=$null
            try { $reference=Write-KmtechProtectedFailureSidecar -Text (($originalPlacementFailure.Exception.ToString()+[Environment]::NewLine+[string]$originalPlacementFailure.ScriptStackTrace)) } catch { }
            $Script:LabelPlacementChildFailure=[ordered]@{schema='label-match-placement-child-failure-v1';phase='PARENT_LAUNCH';placement_code='PLACEMENT_LAUNCH_FAILED';exit_code=1;exception_type=$originalPlacementFailure.Exception.GetType().FullName;hresult=$originalPlacementFailure.Exception.HResult;message=[string]$Script:KmtechRedactionRules.safe_messages[0];full_exception_trace=$reference}
        }
        $Script:LabelPlacementChildFailure=ConvertTo-LabelPlacementPublicFailure $Script:LabelPlacementChildFailure
        $originalPlacementFailure.Exception.Data['placement_child_failure']=$Script:LabelPlacementChildFailure
        throw $originalPlacementFailure
    }
    finally {
        foreach ($createdPath in $createdPaths) {
            if ([IO.File]::Exists($createdPath)) {
                Remove-Item -LiteralPath $createdPath -ErrorAction Stop
            }
        }
    }
}

function Relays {
    return @(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {
        [string]$_.CommandLine -like '*--label-match-user-relay*' -and
        [string]$_.ExecutablePath -match '(?i)(pythonw?\.exe|Label_Match\.exe)$'
    })
}

function Normalize-RelayExecutableQuoting([string]$CommandLine, [string]$ExecutablePath) {
    # Windows startup may quote an executable that Arg would leave unquoted.
    # Strip only that exact, case-sensitive executable prefix; preserve all
    # argument bytes and required quotes around paths containing whitespace.
    $quoted = '"' + $ExecutablePath + '"'
    if ($ExecutablePath -notmatch '[\s"]' -and
        $CommandLine.StartsWith($quoted + ' ', [StringComparison]::Ordinal)) {
        return $ExecutablePath + $CommandLine.Substring($quoted.Length)
    }
    return $CommandLine
}

function Assert-RollbackRelayPreimage([object[]]$ExpectedRelays) {
    $actualRelays = @(Relays)
    if ($actualRelays.Count -ne $ExpectedRelays.Count) {
        throw 'rollback relay process-count readback failed'
    }
    foreach ($expected in $ExpectedRelays) {
        $matching = @($actualRelays | Where-Object {
            (Same ([string]$_.ExecutablePath) ([string]$expected.ExecutablePath)) -and
            (Normalize-RelayExecutableQuoting ([string]$_.CommandLine) ([string]$expected.ExecutablePath)) -ceq
                (Normalize-RelayExecutableQuoting ([string]$expected.CommandLine) ([string]$expected.ExecutablePath))
        })
        if ($matching.Count -ne 1) {
            throw 'rollback relay executable/command readback failed'
        }
    }
    return $actualRelays
}

function Wait-LabelRollbackRelayReady([object[]]$ExpectedRelays,[string]$StatusPath,[string]$ExpectedSha,
    [DateTime]$StartedAt,[double]$TimeoutSeconds = 600) {
    if ($TimeoutSeconds -le 0 -or $TimeoutSeconds -gt 600) { throw 'Rollback readiness deadline differs.' }
    if ($ExpectedRelays.Count -eq 0) { [void](Assert-RollbackRelayPreimage $ExpectedRelays); return $true }
    if ($ExpectedRelays.Count -ne 1 -or $ExpectedSha -cnotmatch '^[0-9a-f]{40}$') { throw 'Rollback readiness identity differs.' }
    $timer=[Diagnostics.Stopwatch]::StartNew()
    while ($timer.Elapsed.TotalSeconds -lt $TimeoutSeconds) {
        try {
            $relays=@(Assert-RollbackRelayPreimage $ExpectedRelays)
            Assert-LabelShortcutCopyPath $StatusPath
            if ([IO.File]::Exists($StatusPath) -and (Get-Item -LiteralPath $StatusPath).Length -le 262144) {
                $record=Get-Content -LiteralPath $StatusPath -Raw -Encoding UTF8|ConvertFrom-Json
                $root=Split-Path -Parent (Split-Path -Parent ([string]$ExpectedRelays[0].ExecutablePath))
                $updated=if($record.updated_at -is [DateTime]){$record.updated_at.ToUniversalTime()}
                    elseif($record.updated_at -is [DateTimeOffset]){$record.updated_at.UtcDateTime}
                    else{[DateTimeOffset]::Parse([string]$record.updated_at).UtcDateTime}
                $created=([DateTime]$relays[0].CreationDate).ToUniversalTime()
                $sameOriginal=($relays[0].ProcessId -eq $ExpectedRelays[0].ProcessId -and
                    $null -ne $ExpectedRelays[0].CreationDate -and
                    $created -eq ([DateTime]$ExpectedRelays[0].CreationDate).ToUniversalTime())
                if ($record.status -ceq 'RUNNING' -and $record.source_commit -ceq $ExpectedSha -and
                    $record.ordinary_user -is [bool] -and $record.ordinary_user -and
                    ($record.process_id -is [int] -or $record.process_id -is [long]) -and
                    $record.process_id -gt 0 -and $record.process_id -eq $relays[0].ProcessId -and
                    ((Same ([string]$record.code_root) $root) -or (Same ([string]$record.code_root) (Join-Path $root 'app'))) -and
                    $updated -ge $StartedAt.AddSeconds(-1) -and ($sameOriginal -or $created -ge $StartedAt.AddSeconds(-1)) -and
                    (Test-RelayPersistentRetry $record) -and $timer.Elapsed.TotalSeconds -lt $TimeoutSeconds) { return $true }
            }
        } catch { }
        $remaining=($TimeoutSeconds-$timer.Elapsed.TotalSeconds)*1000
        if($remaining -gt 0){Start-Sleep -Milliseconds ([Math]::Min(100,[Math]::Ceiling($remaining)))}
    }
    throw 'Rollback relay readiness remains unproven.'
}

function Protect-LabelFailureText([string]$Text) {
    if ($Text.TrimStart().StartsWith('{') -or $Text.TrimStart().StartsWith('[')) {
        try {
            $value = $Text | ConvertFrom-Json -ErrorAction Stop
            return ConvertTo-KmtechRedactedSinkText -Text ((ConvertTo-KmtechRedactedSinkObject $value) | ConvertTo-Json -Depth 30)
        } catch { }
    }
    return ConvertTo-KmtechRedactedSinkText -Text $Text
}

function Initialize-LabelChildOutputReader {
    # 64 KiB per stream covers a traceback/JSON report without unbounded audit growth.
    # On overflow retain the tail, where Python puts its lowest exception and cause.
    if ('LabelChildOutputReader' -as [type]) { [LabelChildOutputReader]::Configure((Get-KmtechSinkReplacements),$Script:KmtechRedactionRules.pattern,$Script:KmtechRedactionRules.path_suffix,$Script:KmtechRedactionRules.digest_suffix,$Script:KmtechRedactionRules.short_secret_digest,$Script:KmtechRedactionRules.field,$Script:KmtechRedactionRules.structured_delimiters); return }
    Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

// Mask assignment and JSON secret values before bounded retention, including values spanning
// chunks. A truncated JSON document can no longer be parsed by the sink writer.
public sealed class LabelJsonFieldMasker {
 private readonly Regex secret, path, digest, shortSecret;
 public static string StructuredDelimiters;
 private readonly string marker, rawMarker, delimiters;
 private readonly StringBuilder token = new StringBuilder();
 private int state; private bool escaped, quoted, bareKey, malformed; private char quote, nestedQuote;
 private readonly Stack<char> closing = new Stack<char>();
 public LabelJsonFieldMasker(string pattern,string paths,string digests,string shorts,string replacement) {
  delimiters=StructuredDelimiters;
  if(String.IsNullOrEmpty(delimiters) || delimiters.Length%2!=0) throw new ArgumentException("Structured redaction grammar is invalid.");
  secret=new Regex(pattern+"|(?i)^(pin|otp|password)$");path=new Regex(paths);
  digest=new Regex(digests);shortSecret=new Regex(shorts);rawMarker=replacement;marker="\""+replacement+"\"";
 }
 private bool Sensitive(string key) {
  return secret.IsMatch(key) && !path.IsMatch(key) && !(digest.IsMatch(key) && !shortSecret.IsMatch(key));
 }
 public string Push(string text) {
  var output=new StringBuilder();
  foreach(char c in text) {
   bool again=true;
   while(again) {
    again=false;
    if(state==0) {
     if(c=='"' || c=='\'') {quote=c;token.Append(c);state=1;escaped=false;}
     else if(c=='_' || (c>='A' && c<='Z') || (c>='a' && c<='z')) {token.Append(c);state=8;}
     else output.Append(c);
    } else if(state==1) {
     token.Append(c);
     if(escaped) escaped=false;
     else if(c=='\\') escaped=true;
     else if(c==quote) state=2;
     // Long non-key strings remain ordinary text; secret values use state 4.
     if(token.Length>1024) {output.Append(token);token.Clear();state=7;}
    } else if(state==2) {
     if(Char.IsWhiteSpace(c)) {token.Append(c);}
     else if(c==':' || c=='=') {
      string raw=token.ToString().Trim();string key=raw.Substring(1,raw.Length-2);
      try {key=Regex.Unescape(key);} catch(ArgumentException) {}
      output.Append(token);output.Append(c);token.Clear();bareKey=false;state=Sensitive(key) ? 3 : 0;
     } else {output.Append(token);token.Clear();state=0;again=true;}
    } else if(state==3) {
     if(Char.IsWhiteSpace(c)) output.Append(c);
     else if(c=='"' || c=='\'') {quote=c;output.Append(quote+rawMarker+quote);state=4;escaped=false;}
     else if(c=='[') {token.Append(c);state=13;}
     else if(delimiters.IndexOf(c)>=0 && delimiters.IndexOf(c)%2==0) {output.Append(marker);state=5;closing.Clear();closing.Push(delimiters[delimiters.IndexOf(c)+1]);malformed=false;quoted=false;escaped=false;}
     else {token.Append(c);state=6;}
    } else if(state==4 || state==7) {
     if(state==7) output.Append(c);
     if(escaped) escaped=false;
     else if(c=='\\') escaped=true;
     else if(c==quote) state=0;
    } else if(state==5) {
     if(malformed) {if(c=='\r' || c=='\n') {output.Append(c);state=0;}}
     else if(quoted) {if(escaped) escaped=false;else if(c=='\\') escaped=true;else if(c==nestedQuote) quoted=false;}
     else if(c=='"' || c=='\'') {nestedQuote=c;quoted=true;}
     else if(delimiters.IndexOf(c)>=0 && delimiters.IndexOf(c)%2==0) closing.Push(delimiters[delimiters.IndexOf(c)+1]);
     else if(delimiters.IndexOf(c)>=0) {
      if(closing.Count==0 || closing.Peek()!=c) malformed=true;
      else {closing.Pop();if(closing.Count==0) state=0;}
     }
    } else if(state==6) {
     if(c==',' || c==';' || c=='}' || c==']' || Char.IsWhiteSpace(c)) {
      string value=token.ToString();output.Append(value=="true" || value=="false" || value=="null" ? value : (bareKey ? rawMarker : marker));
      token.Clear();state=0;again=true;
     } else if(token.Length<16) token.Append(c);
    } else if(state==8 || state==10) {
     bool keyChar=Char.IsLetterOrDigit(c) || c=='_' || c=='.' || c=='-';
     if(state==8 && keyChar) {
      token.Append(c);
      if(token.Length>1024) {output.Append(token);token.Clear();state=9;}
     } else if(Char.IsWhiteSpace(c)) {
      if(state==8) output.Append(token);
      output.Append(c);state=10;
     }
     else if(c==':' || c=='=') {
      string key=token.ToString().Trim();
      if(state==8) output.Append(token);
      output.Append(c);token.Clear();bareKey=true;
      bool metadata=path.IsMatch(key) || (digest.IsMatch(key) && !shortSecret.IsMatch(key));
      state=Sensitive(key) ? 3 : (metadata ? 11 : 0);
     } else {if(state==8) output.Append(token);token.Clear();state=0;again=true;}
    } else if(state==9) {
     if(Char.IsLetterOrDigit(c) || c=='_' || c=='.' || c=='-') output.Append(c);
     else {state=0;again=true;}
    } else if(state==11) {
     if(Char.IsWhiteSpace(c)) output.Append(c);
     else if(c=='"' || c=='\'') {quote=c;output.Append(c);state=7;escaped=false;}
     else {state=12;again=true;}
    } else if(state==12) {
     if(c==',' || c==';' || c=='}' || c==']' || Char.IsWhiteSpace(c)) {state=0;again=true;}
     else output.Append(c);
    } else if(state==13) {
     token.Append(c);string candidate=token.ToString();
     if("[REDACTED:".StartsWith(candidate,StringComparison.Ordinal)) {
      if(candidate=="[REDACTED:") {output.Append(token);token.Clear();state=14;}
     } else {
      output.Append(marker);token.Clear();state=5;closing.Clear();closing.Push(delimiters[delimiters.IndexOf('[')+1]);malformed=false;quoted=false;escaped=false;again=true;
     }
    } else if(state==14) {
     output.Append(c);if(c==']') state=0;
    }
   }
  }
  return output.ToString();
 }
 public string Finish() {
  string value=token.ToString();token.Clear();
  if(state==6) return value=="true" || value=="false" || value=="null" ? value : (bareKey ? rawMarker : marker);
  if(state==13) return marker;
  return state==1 || state==2 || state==8 ? value : "";
 }
}

public sealed class LabelChildOutput {
 public string Text; public long ByteCount; public bool Truncated;
 public Task Completion;
}
public static class LabelChildOutputReader {
 private static KeyValuePair<string,string>[] replacements = new KeyValuePair<string,string>[0];
 private static string pattern, paths, digests, shorts, field;
 public static void Configure(Dictionary<string,string> values,string patternValue,string pathValue,string digestValue,string shortValue,string fieldValue,string structuredValue) {
  LabelJsonFieldMasker.StructuredDelimiters=structuredValue;
  replacements = values.OrderByDescending(v => v.Key.Length).ThenBy(v => v.Key, StringComparer.Ordinal).ToArray();
  pattern=patternValue;paths=pathValue;digests=digestValue;shorts=shortValue;field=fieldValue;
 }
 public static LabelChildOutput Capture(StreamReader reader) {
  var result = new LabelChildOutput {Text = ""};
  result.Completion = Drain(reader, result, replacements); return result;
 }
 public static async Task<LabelChildOutput> Read(StreamReader reader) {
  var result = Capture(reader); await result.Completion.ConfigureAwait(false); return Snapshot(result);
 }
 public static LabelChildOutput Snapshot(LabelChildOutput result) {
  lock (result) {return new LabelChildOutput {Text=result.Text,ByteCount=result.ByteCount,Truncated=result.Truncated};}
 }
 private static string Clip(string value, int maximum, bool tail) {
  byte[] raw = Encoding.UTF8.GetBytes(value);
  if (raw.Length <= maximum) return value;
  if (tail) {
   int start=raw.Length-maximum; while ((raw[start]&0xC0)==0x80) start++;
   return Encoding.UTF8.GetString(raw,start,raw.Length-start);
  }
  int end=maximum; while ((raw[end]&0xC0)==0x80) end--;
  return Encoding.UTF8.GetString(raw,0,end);
 }
 private static async Task Drain(StreamReader reader, LabelChildOutput result, KeyValuePair<string,string>[] forms) {
  var buffer = new char[4096]; string pending="", head="", tail="";
  var masker = new LabelJsonFieldMasker(pattern,paths,digests,shorts,field);
  long rawCount=0, sanitizedCount=0; int count; bool headDone=false;
  int overlap=forms.Length==0 ? 2 : forms.Max(v=>v.Key.Length)+2;
  Action<string> emit = part => {
   int headRoom = 8192-Encoding.UTF8.GetByteCount(head);
   if (headRoom>0 && !headDone) {
    string prefix=Clip(part,headRoom,false); head+=prefix;part=part.Substring(prefix.Length);
    headDone=part.Length>0 || Encoding.UTF8.GetByteCount(head)==8192;
   }
   tail=Clip(tail+part,65536-Encoding.UTF8.GetByteCount(head),true);
   string output=head+tail;
   bool truncated=sanitizedCount>65536;
   if (truncated) {
    int tailBudget=65536-Encoding.UTF8.GetByteCount(head);
    string clipped=tail, marker;
    for(;;) {
     clipped=Clip(tail,tailBudget,true);
     long omitted=sanitizedCount-Encoding.UTF8.GetByteCount(head)-Encoding.UTF8.GetByteCount(clipped);
     marker="\n[TRUNCATED: "+omitted+" bytes omitted]\n";
     int next=65536-Encoding.UTF8.GetByteCount(head)-Encoding.UTF8.GetByteCount(marker);
     if(next>=tailBudget) break;tailBudget=next;
    }
    output=head+marker+clipped;
   }
   lock(result) {result.Text=output;result.ByteCount=rawCount;result.Truncated=truncated;}
  };
  try {
   while((count=await reader.ReadAsync(buffer,0,buffer.Length).ConfigureAwait(false))!=0) {
    rawCount+=Encoding.UTF8.GetByteCount(buffer,0,count);
    pending+=new string(buffer,0,count);
    foreach(var entry in forms) pending=pending.Replace(entry.Key,entry.Value);
    int split=Math.Max(0,pending.Length-overlap);
    if(split>0 && Char.IsHighSurrogate(pending[split-1])) split--;
    string part=masker.Push(pending.Substring(0,split));pending=pending.Substring(split);
    sanitizedCount+=Encoding.UTF8.GetByteCount(part);emit(part);
   }
  } catch(ObjectDisposedException) {} catch(IOException) {}
  foreach(var entry in forms) pending=pending.Replace(entry.Key,entry.Value);
  pending=masker.Push(pending)+masker.Finish();
  sanitizedCount+=Encoding.UTF8.GetByteCount(pending);emit(pending);
 }
}
'@
    [LabelChildOutputReader]::Configure((Get-KmtechSinkReplacements),$Script:KmtechRedactionRules.pattern,$Script:KmtechRedactionRules.path_suffix,$Script:KmtechRedactionRules.digest_suffix,$Script:KmtechRedactionRules.short_secret_digest,$Script:KmtechRedactionRules.field,$Script:KmtechRedactionRules.structured_delimiters)
}

function ConvertTo-LabelFailureOutput($Output) {
    return [ordered]@{text=(Protect-LabelFailureText ([string]$Output.Text));byte_count=$Output.ByteCount;truncated=$Output.Truncated;limit_bytes=65536}
}

function New-LabelChildFailure([string]$Mode, [int]$ExitCode, $Stdout, $Stderr) {
    $record = [ordered]@{stdout=$Stdout;stderr=$Stderr}
    $text = [string]$Stderr.text
    if ([string]::IsNullOrWhiteSpace($text)) { $text = [string]$Stdout.text }
    $types = [regex]::Matches($text, '(?m)^([A-Za-z_][A-Za-z0-9_.]*(?:Error|Exception))\s*:')
    $type = if ($types.Count) { $types[$types.Count - 1].Groups[1].Value } else { 'ChildNonzeroExit' }
    $last = [string]$Script:KmtechRedactionRules.safe_messages[0]
    $public = ConvertTo-KmtechPublicRecord ([ordered]@{status='FAILED';stage='CURRENT_USER_ONBOARDING';reason_code='CHILD_NONZERO_EXIT';exit_code=$ExitCode;exception_type=$type;guidance=$last;report_status='REPORT_UNAVAILABLE'})
    foreach ($stream in @($Stderr,$Stdout)) {
        foreach ($line in @([string]$stream.text -split '\r?\n')) {
            if ($line -cnotmatch '^LABEL_MATCH_INSTALLER_FAILURE=(\{[^\r\n]*\})$') { continue }
            try {
                $typed = $Matches[1] | ConvertFrom-Json -ErrorAction Stop
                $fields = [ordered]@{}
                foreach ($property in $typed.PSObject.Properties) { $fields[$property.Name]=$property.Value }
                $candidate = ConvertTo-KmtechPublicRecord $fields
                if ($candidate.Contains('public_record_code') -or -not $candidate.Contains('exception_type') -or -not $candidate.Contains('reason_code')) { continue }
                if ($candidate.Contains('report_path') -or $candidate.Contains('report_sha256')) {
                    if (-not $candidate.Contains('report_path') -or -not $candidate.Contains('report_sha256') -or
                        -not (Test-Path -LiteralPath $candidate.report_path -PathType Leaf) -or
                        (Get-FileHash -LiteralPath $candidate.report_path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $candidate.report_sha256) {
                        $candidate.Remove('report_path'); $candidate.Remove('report_sha256')
                        $candidate.report_status='REPORT_UNAVAILABLE'
                    }
                }
                $public=$candidate; $public.exit_code=$ExitCode
                break
            } catch { }
        }
    }
    foreach ($streamName in @('stdout','stderr')) {
        $output = $record[$streamName]
        if ([string]::IsNullOrEmpty([string]$output.text)) { continue }
        try {
        $directory = Join-Path ([IO.Path]::GetTempPath()) ('label-product-diagnostic-'+[Guid]::NewGuid().ToString('N'))
        [void](New-Item -ItemType Directory -Path $directory -ErrorAction Stop)
        $acl = [Security.AccessControl.DirectorySecurity]::new()
        $acl.SetAccessRuleProtection($true,$false)
        foreach ($sid in @([Security.Principal.WindowsIdentity]::GetCurrent().User,
            [Security.Principal.SecurityIdentifier]::new('S-1-5-18'),
            [Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'))) {
            $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
        }
        Set-Acl -LiteralPath $directory -AclObject $acl
        $path = Join-Path $directory ($streamName+'.txt')
        $bytes = [Text.Encoding]::UTF8.GetBytes((Protect-LabelFailureText ([string]$output.text)))
        $file = [IO.File]::Open($path,'CreateNew','Write','Read')
        try { $file.Write($bytes,0,$bytes.Length);$file.Flush($true) } finally { $file.Dispose() }
        $hash = [Security.Cryptography.SHA256]::Create()
        try { $digest=([BitConverter]::ToString($hash.ComputeHash([IO.File]::ReadAllBytes($path)))).Replace('-','').ToLowerInvariant() }
        finally { $hash.Dispose() }
        $output.full_output = [ordered]@{path=$path;sha256=$digest;limit_bytes=65536;truncated=$output.truncated}
        } catch { $output.evidence_failure_type=$_.Exception.GetType().FullName }
        # The audit remains valid JSON and carries a pinned reference to the full stream.
        $output.text = ''
    }
    if (-not $public.Contains('report_path')) {
        foreach ($streamName in @('stderr','stdout')) {
            $output=$record[$streamName]
            if ($output.Contains('full_output')) {
                $public.Remove('report_status')
                $public.report_path=[string]$output.full_output.path
                $public.report_sha256=[string]$output.full_output.sha256
                break
            }
        }
    }
    $exception = [InvalidOperationException]::new('LABEL_MATCH_CHILD_FAILED')
    $exception.Data['child_output'] = $public
    return $exception
}

function Product([string]$Root, [string]$Mode, [string[]]$ExtraArguments = @(), [string]$LogicalAppRoot = '') {
    if ([string]::IsNullOrEmpty($LogicalAppRoot)) { $LogicalAppRoot = $Root }
    if ($Mode -cnotin @('--label-match-user-relay','--label-match-direct-sync-relay',
                       '--onboard-current-user','--remove-current-user-setup')) {
        throw 'Headless product mode is unsupported.'
    }
    $headlessEntry = Join-Path $Root 'app\label_match_relay_entry.py'
    if (Test-Path -LiteralPath $headlessEntry -PathType Leaf) {
        $args = '-I -B {0} {1} --app-root {2}' -f (Arg $headlessEntry), $Mode, (Arg $LogicalAppRoot)
    } else {
        if (-not (Test-Path -LiteralPath (Join-Path $Root 'app\label_match_product_host.py') -PathType Leaf)) {
            throw 'Historical packet has no supported headless product host.'
        }
        $legacyHeadless = "import sys;from pathlib import Path;p=Path(sys.argv[1]);sys.path[:0]=[str(p),str(p/'site-packages')];from label_match_product_host import dispatch_product_mode;r=dispatch_product_mode(sys.argv[2:]);raise SystemExit(1 if r is None else int(r))"
        $args = '-I -B -c {0} {1} {2} --app-root {3}' -f (Arg $legacyHeadless),
            (Arg (Join-Path $Root 'app')), $Mode, (Arg $LogicalAppRoot)
    }
    foreach ($extraArgument in $ExtraArguments) { $args += ' ' + (Arg $extraArgument) }
    Initialize-LabelChildOutputReader
    $startInfo = [Diagnostics.ProcessStartInfo]::new()
    $startInfo.FileName = Join-Path $Root 'runtime\pythonw.exe'
    $startInfo.Arguments = $args
    $startInfo.UseShellExecute = $false
    $startInfo.CreateNoWindow = $true
    $startInfo.RedirectStandardOutput = $true
    $startInfo.RedirectStandardError = $true
    $process = [Diagnostics.Process]::Start($startInfo)
    try {
        $stdoutCapture = [LabelChildOutputReader]::Capture($process.StandardOutput)
        $stderrCapture = [LabelChildOutputReader]::Capture($process.StandardError)
        # The registration budget is finite. A verified stopped child permits
        # rollback; uncertain ownership/exit preserves the new code and fence.
        if ($Mode -ceq '--onboard-current-user') { Wait-LabelRegistrationChild $process }
        else { $process.WaitForExit() }
        $exitCode = [int]$process.ExitCode
        # A persistent child can inherit these pipes. Capture its host's final
        # buffered output without waiting for that child's lifetime or stopping it.
        [void]$stdoutCapture.Completion.Wait(1000)
        [void]$stderrCapture.Completion.Wait(1000)
        $stdout = ConvertTo-LabelFailureOutput ([LabelChildOutputReader]::Snapshot($stdoutCapture))
        $stderr = ConvertTo-LabelFailureOutput ([LabelChildOutputReader]::Snapshot($stderrCapture))
        if ($exitCode -ne 0) {
            throw (New-LabelChildFailure $Mode $exitCode $stdout $stderr)
        }
    }
    finally {
        $process.Dispose()
    }
}


function Write-LabelPreparationFailure($Failure, [string]$Source,
    $Inventory, [string]$AuditRoot, [string]$ExternalEvidencePath) {
    $failureId = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ') + '-' + [Guid]::NewGuid().ToString('N')
    $failurePath = Join-Path $AuditRoot ('canonical-portable-' + $failureId + '.json')
    $failureAudit = [ordered]@{
        schema='label-match-canonical-portable-install-v1'
        status='FAILED'; preparation_status='FAILED_PREPARATION_ADMISSION'; run_id=$failureId
        code_placement='NOT_STARTED'; source_root=$Source
        source_inventory_sha256=[string]$Inventory.sha256
        preparation_failure=(Get-LabelLaunchFailure $Failure 'preparation')
        rollback=[ordered]@{status='NOT_REQUIRED';available=$false;applied=$false;runtime_restored=$false}
    }
    try {
        Save $failurePath $failureAudit
        if ($ExternalEvidencePath) { Save (Full $ExternalEvidencePath 'EvidencePath') $failureAudit }
    } catch { }
    'install_status=FAILED'
    if (Test-Path -LiteralPath $failurePath -PathType Leaf) { "audit_path=$failurePath" }
}

function Invoke-LabelSourceDataAdmission([string]$ProductRoot, [string]$Source,
    $Inventory, [string]$AuditRoot, [string]$ExternalEvidencePath,
    [string[]]$OnboardingArgs = @()) {
    try {
        Product $ProductRoot '--onboard-current-user' `
            (@('--app-root', $Source, '--check-data-generation-only',
               '--installer-source-inventory-sha256', [string]$Inventory.sha256) + $OnboardingArgs)
    }
    catch {
        $admissionFailure = $_
        # A recovery hint cannot replace the first source-admission failure.
        try {
            if(@(Relays).Count -eq 0){Write-LabelInstallerRelayRecoveryGuidance}
        } catch { }
        Write-LabelPreparationFailure $admissionFailure $Source $Inventory $AuditRoot $ExternalEvidencePath
        throw $admissionFailure
    }
}

function Get-LabelPortableDataVersion([string]$Root, $Manifest) {
    $manifestVersion = if ($Manifest -is [Collections.IDictionary]) { [string]$Manifest['version'] }
        elseif ($null -ne $Manifest -and $null -ne $Manifest.PSObject.Properties['version']) { [string]$Manifest.version }
        else { '' }
    if (-not [string]::IsNullOrWhiteSpace($manifestVersion)) { return $manifestVersion }
    # Older stock portable manifests omitted version. Read the verified source
    # literal; do not execute the old application to determine its identity.
    foreach ($relative in @('app\label_data_generation.py', 'app\Label_Match.py')) {
        $path = Join-Path $Root $relative
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            if ((Get-Item -LiteralPath $path).Length -gt 10485760) { throw 'Release version source is oversized.' }
            $text = Get-Content -LiteralPath $path -Raw -Encoding UTF8
            $match = [regex]::Match($text, '(?m)^(?:CURRENT_VERSION|APP_VERSION)\s*=\s*["''](v\d+\.\d+\.\d+)["'']\s*$')
            if ($match.Success) { return $match.Groups[1].Value }
        }
    }
    return '' # The helper returns UNKNOWN; missing records remain ALLOW.
}

function Assert-LabelRollbackGeneration {
    # Before any rollback cleanup or old-code selection, retain the opened
    # generation. Code-only failures before data open still have no markers.
    if ($existingVerified) {
        $generationRollbackRoot = if ($replacementRollbackRoot) { $replacementRollbackRoot } else { $install }
        $generationRollbackManifest = Manifest $generationRollbackRoot $SkipSignatureValidationForTest
        $generationRollbackVersion = Get-LabelPortableDataVersion $generationRollbackRoot $generationRollbackManifest
        [void](Assert-LabelDataDowngrade -MarkerPaths $generationMarkerPaths -SubjectSid $generationSubjectSid `
            -TargetVersion $generationRollbackVersion -TargetBuildId ([string]$generationRollbackManifest.source_commit))
        # Both predicates are mandatory before any old-code/setup mutation.
        # A refused generation never starts the old target inventory walk.
        if ([string](PortableInventory $generationRollbackRoot).sha256 -cne [string]$installedPreimageInventory.sha256) {
            throw 'Exact rollback generation target is unproven; current code and data are preserved.'
        }
    }
    elseif (-not $existingVerified) {
        $generationAbsence = Get-KmtechDataDowngradeDecision -MarkerPaths $generationMarkerPaths `
            -TargetVersion 'v0.0.0' -TargetBuildId ('0' * 40) -AppId 'Label_Match' -SubjectSid $generationSubjectSid
        if ($generationAbsence.allowed -ne $true -or $null -ne $generationAbsence.version) {
            throw '새 판이 이 PC의 자료를 열어 설치 이전 코드 없음 상태로 되돌릴 수 없습니다. 현재 코드와 자료를 보존하고 관리자 지원 복구를 요청하세요.'
        }
    }
}

function Assert-LabelDataDowngrade(
    [string[]]$MarkerPaths, [string]$TargetVersion, [string]$SubjectSid, [string]$TargetBuildId
) {
    $decision = Get-KmtechDataDowngradeDecision -MarkerPaths $MarkerPaths `
        -TargetVersion $TargetVersion -AppId 'Label_Match' -SubjectSid $SubjectSid -TargetBuildId $TargetBuildId
    if ($decision.allowed -ne $true) { throw ([string]$decision.message) }
    return $decision
}

function Resolve-LabelGenerationInputPath([string]$Value, [string]$Root) {
    # Use the reader's resolver and the same FileSystem working directory as
    # Product's child. Do not interpret user path strings twice in two languages.
    $pathProbe = @'
import base64, sys
from pathlib import Path
sys.path.insert(0, str(Path(sys.argv[1]) / 'app'))
from label_data_generation import resolve_data_path
try:
    selected = resolve_data_path(base64.b64decode(sys.stdin.buffer.read()).decode('utf-8'))
    print(base64.b64encode(str(selected).encode('utf-8')).decode('ascii'))
except Exception:
    raise SystemExit(4)
'@
    # PS7 expands a native argv value beginning with ~ using its own HOME.
    # Byte stdin accepts the PS5 UTF-8 BOM and preserves non-ASCII paths.
    $pathInput = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($Value))
    $resolved = @($pathInput | & (Join-Path $Root 'runtime\python.exe') -I -B -c $pathProbe $Root)
    if ($LASTEXITCODE -ne 0 -or $resolved.Count -ne 1 -or [string]::IsNullOrWhiteSpace([string]$resolved[0])) {
        throw '이 PC의 자료 경로를 확인할 수 없어 자료를 열 수 없습니다. 현재 코드와 자료를 보존하고 관리자에게 지원 복구를 요청하세요.'
    }
    try { $cooked = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$resolved[0])) }
    catch { throw '이 PC의 자료 경로를 확인할 수 없습니다. 현재 코드와 자료를 보존하고 관리자에게 지원 복구를 요청하세요.' }
    return Full $cooked 'Label generation input'
}

function Get-LabelPathCompareKey([string]$Value) {
    $text = ([string]$Value).Trim().Replace('/', '\')
    if ($text.StartsWith('\\?\UNC\', [StringComparison]::OrdinalIgnoreCase)) { $text = '\\' + $text.Substring(8) }
    elseif ($text.StartsWith('\\?\', [StringComparison]::OrdinalIgnoreCase) -or $text.StartsWith('\\.\', [StringComparison]::OrdinalIgnoreCase)) { $text = $text.Substring(4) }
    return ([IO.Path]::GetFullPath($text)).TrimEnd('\')
}

function Resolve-LabelPathLinkTargets([string]$Path) {
    # Link metadata only. A path that cannot be resolved throws, and the caller treats it as legacy-shared.
    $current = Get-LabelPathCompareKey $Path
    for ($round = 0; $round -lt 16; $round++) {
        $parts = $current.Split('\')
        $walk = $parts[0] + '\'
        $replaced = $false
        for ($i = 1; $i -lt $parts.Count; $i++) {
            $walk = Join-Path $walk $parts[$i]
            try { $attributes = [IO.File]::GetAttributes($walk) }
            catch [IO.FileNotFoundException] { break }
            catch [IO.DirectoryNotFoundException] { break }
            if (($attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0) { continue }
            $target = @((Get-Item -LiteralPath $walk -Force -ErrorAction Stop).Target)[0]
            if ([string]::IsNullOrWhiteSpace([string]$target)) { throw 'Link target cannot be resolved.' }
            if (-not [IO.Path]::IsPathRooted([string]$target)) { $target = Join-Path (Split-Path -Parent $walk) ([string]$target) }
            $rest = if ($i + 1 -lt $parts.Count) { '\' + (($parts[($i + 1)..($parts.Count - 1)]) -join '\') } else { '' }
            $current = Get-LabelPathCompareKey (([string]$target) + $rest)
            $replaced = $true
            break
        }
        if (-not $replaced) { return $current }
    }
    throw 'Link chain is too deep.'
}

function Test-LabelLegacySharedProfilePath([string]$Value) {
    # The old PC-wide <ProgramData>\KMTech\Logistics profile and everything under its secrets directory.
    # Path comparison only: neither the old profile nor its secrets are opened or probed.
    if ([string]::IsNullOrWhiteSpace($Value)) { return $false }
    $trimmed = $Value.Trim()
    if (-not [IO.Path]::IsPathRooted($trimmed)) { return $false }
    $candidates = @()
    try {
        $candidates += Get-LabelPathCompareKey $trimmed
        $candidates += Resolve-LabelPathLinkTargets $trimmed
    }
    catch { return $true }
    $rootValues = @([Environment]::GetFolderPath('CommonApplicationData'), [string]$env:PROGRAMDATA)
    foreach ($rootValue in $rootValues) {
        if ([string]::IsNullOrWhiteSpace($rootValue) -or -not [IO.Path]::IsPathRooted($rootValue)) { continue }
        $rootKeys = @()
        try { $rootKeys += Get-LabelPathCompareKey $rootValue } catch { continue }
        try { $rootKeys += Resolve-LabelPathLinkTargets $rootValue } catch { }
        foreach ($rootKey in $rootKeys) {
            $shared = $rootKey + '\KMTech\Logistics'
            $profileFile = $shared + '\runtime-profile.json'
            $secretsDir = $shared + '\secrets'
            foreach ($candidate in $candidates) {
                if ($candidate.Equals($profileFile, [StringComparison]::OrdinalIgnoreCase) -or
                    $candidate.Equals($secretsDir, [StringComparison]::OrdinalIgnoreCase) -or
                    $candidate.StartsWith($secretsDir + '\', [StringComparison]::OrdinalIgnoreCase)) { return $true }
            }
        }
    }
    return $false
}

function Get-LabelAppProfileEnvValue {
    # An app-specific profile env naming the old shared profile counts as unset (G91).
    $value = [string]$env:LABEL_MATCH_LOGISTICS_PROFILE_PATH
    if ([string]::IsNullOrWhiteSpace($value)) { return '' }
    if (Test-LabelLegacySharedProfilePath $value) {
        Write-Host 'LABEL_MATCH_LOGISTICS_PROFILE_PATH ignored: points at the legacy shared profile location'
        return ''
    }
    return $value
}

$WriterDelegationEnvironmentNames = @(
    'KMTECH_LABEL_WRITER_DELEGATION_TOKEN',
    'KMTECH_LABEL_WRITER_DELEGATION_SESSION_ID',
    'KMTECH_LABEL_WRITER_DELEGATION_ATTEMPT_ID',
    'KMTECH_LABEL_WRITER_DELEGATION_TRANSACTION_ID'
)

function SetWriterDelegationEnvironment(
    [string]$Token,
    [string]$SessionId,
    [string]$AttemptId,
    [string]$TransactionId
) {
    [Environment]::SetEnvironmentVariable($WriterDelegationEnvironmentNames[0], $Token, 'Process')
    [Environment]::SetEnvironmentVariable($WriterDelegationEnvironmentNames[1], $SessionId, 'Process')
    [Environment]::SetEnvironmentVariable($WriterDelegationEnvironmentNames[2], $AttemptId, 'Process')
    [Environment]::SetEnvironmentVariable($WriterDelegationEnvironmentNames[3], $TransactionId, 'Process')
}

function RestoreWriterDelegationEnvironment($Before) {
    for ($index = 0; $index -lt $WriterDelegationEnvironmentNames.Count; $index++) {
        [Environment]::SetEnvironmentVariable(
            $WriterDelegationEnvironmentNames[$index],
            $Before[$index],
            'Process'
        )
    }
}

function Initialize-CanonicalUserProcessApi {
    if ('LabelMatchCanonicalUserProcess' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Security.Principal;
using System.Text;
public static class LabelMatchCanonicalUserProcess {
    public sealed class Security { public string sid; public int session_id; public bool elevated; public int integrity_rid; }
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
    struct Startup {
        public int cb; public string reserved, desktop, title;
        public int x,y,cx,cy,xChars,yChars,fill,flags; public short show,reservedBytes;
        public IntPtr reserved2,input,output,error;
    }
    [StructLayout(LayoutKind.Sequential)]
    struct ProcessInfo { public IntPtr process,thread; public int pid,tid; }
    [DllImport("advapi32.dll",SetLastError=true)] static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);
    [DllImport("advapi32.dll",SetLastError=true)] static extern bool GetTokenInformation(IntPtr token,int kind,IntPtr info,int length,out int needed);
    [DllImport("advapi32.dll",SetLastError=true)] static extern bool DuplicateTokenEx(IntPtr token,uint access,IntPtr attributes,int level,int type,out IntPtr copy);
    [DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]
    static extern bool CreateProcessWithTokenW(IntPtr token,uint logon,string application,StringBuilder command,uint flags,IntPtr environment,string directory,ref Startup startup,out ProcessInfo process);
    [DllImport("userenv.dll",SetLastError=true)] static extern bool CreateEnvironmentBlock(out IntPtr environment,IntPtr token,bool inherit);
    [DllImport("userenv.dll")] static extern bool DestroyEnvironmentBlock(IntPtr environment);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr handle);
    [DllImport("user32.dll")] static extern IntPtr GetShellWindow();
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr window,out int pid);
    static void Check(bool success, string call) { if (!success) { var error=new Win32Exception(Marshal.GetLastWin32Error()); error.Data["call"]=call; throw error; } }
    static int Integer(IntPtr token,int kind) {
        IntPtr data=Marshal.AllocHGlobal(4);
        try { int needed; Check(GetTokenInformation(token,kind,data,4,out needed),"GetTokenInformation"); return Marshal.ReadInt32(data); }
        finally { Marshal.FreeHGlobal(data); }
    }
    [DllImport("advapi32.dll")] static extern IntPtr GetSidSubAuthorityCount(IntPtr sid);
    [DllImport("advapi32.dll")] static extern IntPtr GetSidSubAuthority(IntPtr sid,uint index);
    static int Integrity(IntPtr token) {
        int needed; GetTokenInformation(token,25,IntPtr.Zero,0,out needed);
        if(needed<=0 || needed>65536) throw new InvalidOperationException("Token integrity sizing differs.");
        IntPtr data=Marshal.AllocHGlobal(needed);
        try { Check(GetTokenInformation(token,25,data,needed,out needed),"GetTokenInformation:integrity");
            IntPtr sid=Marshal.ReadIntPtr(data); int count=Marshal.ReadByte(GetSidSubAuthorityCount(sid));
            if(count<=0) throw new InvalidOperationException("Token integrity SID differs.");
            return Marshal.ReadInt32(GetSidSubAuthority(sid,(uint)(count-1)));
        } finally { Marshal.FreeHGlobal(data); }
    }
    static Security Inspect(IntPtr token) {
        using (WindowsIdentity identity=new WindowsIdentity(token)) {
            return new Security {sid=identity.User.Value,session_id=Integer(token,12),elevated=Integer(token,20)!=0,integrity_rid=Integrity(token)};
        }
    }
    public static Security Read(int pid) {
        using (Process process=Process.GetProcessById(pid)) {
            IntPtr token; Check(OpenProcessToken(process.Handle,8,out token),"OpenProcessToken:child");
            try { return Inspect(token); } finally { CloseHandle(token); }
        }
    }
    public static int StartLimited(string command,string sid,int session) {
        IntPtr shell=GetShellWindow(); int shellPid;
        if (shell==IntPtr.Zero || GetWindowThreadProcessId(shell,out shellPid)==0)
            throw new InvalidOperationException("Canonical interactive shell is unavailable.");
        using (Process shellProcess=Process.GetProcessById(shellPid)) {
            IntPtr token; Check(OpenProcessToken(shellProcess.Handle,10,out token),"OpenProcessToken:shell");
            IntPtr primary=IntPtr.Zero,environment=IntPtr.Zero;
            try {
                Security security=Inspect(token);
                if (security.elevated || security.integrity_rid!=8192 || security.sid!=sid || security.session_id!=session || session<=0)
                    throw new InvalidOperationException("Canonical interactive shell security differs.");
                Check(DuplicateTokenEx(token,0x18B,IntPtr.Zero,2,1,out primary),"DuplicateTokenEx:primary");
                security=Inspect(primary);
                if (security.elevated || security.integrity_rid!=8192 || security.sid!=sid || security.session_id!=session)
                    throw new InvalidOperationException("Canonical normal-user token differs.");
                Check(CreateEnvironmentBlock(out environment,primary,false),"CreateEnvironmentBlock");
                Startup startup=new Startup(); startup.cb=Marshal.SizeOf(typeof(Startup)); startup.desktop="winsta0\\default";
                ProcessInfo child;
                Check(CreateProcessWithTokenW(primary,0,null,new StringBuilder(command),0x08000400,environment,null,ref startup,out child),"CreateProcessWithTokenW");
                try { return child.pid; } finally { CloseHandle(child.thread); CloseHandle(child.process); }
            } finally {
                if (environment!=IntPtr.Zero) DestroyEnvironmentBlock(environment);
                if (primary!=IntPtr.Zero) CloseHandle(primary);
                CloseHandle(token);
            }
        }
    }
}
'@
}
function Get-CanonicalRelaySecurity([int]$ProcessId) {
    Initialize-CanonicalUserProcessApi
    return [LabelMatchCanonicalUserProcess]::Read($ProcessId)
}
function Start-CanonicalLimitedRelay([string]$Line, [string]$UserSid, [int]$SessionId) {
    Initialize-CanonicalUserProcessApi
    return [LabelMatchCanonicalUserProcess]::StartLimited($Line, $UserSid, $SessionId)
}
function StartRaw([string]$Line, [switch]$TrackRollbackCandidate, [string]$CandidateCodeRoot='') {
    $launchedAt=[DateTime]::UtcNow
    $caller = Get-CanonicalRelaySecurity $PID
    if ([int]$caller.session_id -le 0) { throw 'Canonical relay requires an interactive user session.' }
    if ([bool]$caller.elevated) {
        # Reuse the same user's existing desktop token. Never fall back to the
        # installer token, another account, credentials, or a scheduled task.
        $newPid = Start-CanonicalLimitedRelay $Line ([string]$caller.sid) ([int]$caller.session_id)
    }
    else {
        $created = Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine=$Line}
        if ([uint32]$created.ReturnValue -ne 0) { throw 'Rollback process start failed.' }
        $newPid = [int]$created.ProcessId
    }
    $security = Get-CanonicalRelaySecurity $newPid
    if ([bool]$security.elevated -or [int]$security.integrity_rid -ne 8192 -or [string]$security.sid -cne [string]$caller.sid -or
        [int]$security.session_id -le 0 -or [int]$security.session_id -ne [int]$caller.session_id) {
        throw 'Canonical relay normal-user security readback failed.'
    }
    if ($TrackRollbackCandidate) {
        $row=Get-CimInstance Win32_Process -Filter "ProcessId = $newPid" -ErrorAction Stop
        if (-not $CandidateCodeRoot -or $null -eq $row -or [int]$row.ProcessId -ne $newPid -or $null -eq $row.CreationDate -or
            -not (Same ([string]$row.ExecutablePath) (Join-Path $CandidateCodeRoot 'runtime\pythonw.exe')) -or
            ([DateTime]$row.CreationDate).ToUniversalTime() -lt $launchedAt.AddSeconds(-1) -or
            (Normalize-RelayExecutableQuoting ([string]$row.CommandLine) ([string]$row.ExecutablePath)) -cne $Line) {
            throw 'Candidate relay launch identity is unproven.'
        }
        $Script:LabelRollbackCandidateRelays=@($row)
    }
    return [int]$newPid
}

function Invoke-LabelRollbackStep([string]$Phase, [scriptblock]$Action) {
    # Dot-source this helper so successful restoration assignments remain in
    # the transaction scope. Each independent phase records its own failure.
    $phaseStack = Get-Variable -Name LabelRollbackPhaseStack -Scope Script -ErrorAction SilentlyContinue
    if ($null -eq $phaseStack -or $null -eq $phaseStack.Value) { $Script:LabelRollbackPhaseStack = [Collections.Generic.Stack[string]]::new() }
    $Script:LabelRollbackPhaseStack.Push($Phase)
    try {
        . $Action
        $Script:LabelRollbackSteps.Add([ordered]@{phase=$Script:LabelRollbackPhaseStack.Peek();status='PROVEN'})
    }
    catch {
        $Script:LabelRollbackErrors.Add($_)
        $failure = Get-LabelLaunchFailure $_ $Script:LabelRollbackPhaseStack.Peek()
        $Script:LabelRollbackFailures.Add($failure)
        $Script:LabelRollbackSteps.Add([ordered]@{phase=$Script:LabelRollbackPhaseStack.Peek();status='FAILED'})
    }
    finally { [void]$Script:LabelRollbackPhaseStack.Pop() }
}

function Get-LabelLaunchFailure($Failure, [string]$Phase) {
    $exception=$Failure.Exception; $childOutput=$null; $placementFailure=$null; $privateChain=@()
    while ($null -ne $exception) {
        if ($exception.Data.Contains('child_output')) { $childOutput=$exception.Data['child_output'] }
        if ($exception.Data.Contains('placement_child_failure')) { $placementFailure=$exception.Data['placement_child_failure'] }
        $privateData=[ordered]@{}
        foreach($key in @('call','placement_child_failure','label_legacy_native_failure','startup_restore_failures','lifecycle_channels')) {
            if($exception.Data.Contains($key)) {$privateData[$key]=$exception.Data[$key]}
        }
        # Preserve a typed native call even when the free-text redactor treats
        # the colon in a Token API name as a secret assignment separator.
        if ($privateData.Contains('call') -and [string]$privateData.call -cmatch '\A([A-Za-z_][A-Za-z0-9_]{0,127}):([A-Za-z_0-9][A-Za-z0-9_]{0,127})\z') {
            $privateData.native_call_function=$Matches[1];$privateData.native_call_variant=$Matches[2]
        }
        $privateChain += [ordered]@{exception_type=$exception.GetType().FullName;native_error=$(if($exception -is [ComponentModel.Win32Exception]){$exception.NativeErrorCode}else{$null});details=$privateData}
        $exception=$exception.InnerException
    }
    $baseException=$Failure.Exception.GetBaseException()
    $locationFunction=$Phase;$locationLine=[int]$Failure.InvocationInfo.ScriptLineNumber
    if([string]$Failure.ScriptStackTrace -match '^at ([A-Za-z_][A-Za-z0-9_-]*), [^\r\n]+: line ([0-9]+)'){
        $locationFunction=$Matches[1];$locationLine=[int]$Matches[2]
    }
    $fields=[ordered]@{status='FAILED';stage='SUPPORT';reason_code='INSTALLER_FAILED';exception_type=$baseException.GetType().FullName;guidance=[string]$Script:KmtechRedactionRules.safe_messages[0];report_status='REPORT_UNAVAILABLE'}
    $fields.location_module='INSTALL_CANONICAL_PORTABLE.ps1';$fields.location_function=$locationFunction;$fields.location_line=$locationLine
    if ($null -ne $placementFailure) {
        $fields.placement_code=[string]$placementFailure.placement_code
        $placementLocation = if ($placementFailure -is [Collections.IDictionary]) { $placementFailure['location_function'] }
            elseif ($placementFailure.PSObject.Properties['location_function']) { $placementFailure.location_function }
            else { $null }
        if (-not [string]::IsNullOrEmpty([string]$placementLocation)) {
            $fields.location_function=[string]$placementLocation
        }
        $placementTrace=$null
        if ($placementFailure -is [Collections.IDictionary] -and $placementFailure.Contains('report_path')) {
            $placementTrace=@{path=$placementFailure.report_path;sha256=$placementFailure.report_sha256}
        }
        else {
            $traceProperty=$placementFailure.PSObject.Properties['full_exception_trace']
            if ($null -ne $traceProperty) { $placementTrace=$traceProperty.Value }
        }
        if ($null -ne $placementTrace) {
            $fields.Remove('report_status');$fields.report_path=[string]$placementTrace.path;$fields.report_sha256=[string]$placementTrace.sha256
        }
    }
    if ($null -ne $childOutput) {
        foreach ($key in @('status','stage','reason_code','exception_type','exit_code','report_status','report_path','report_sha256','location_module','location_function','location_line')) {
            if($childOutput.Contains($key)){$fields[$key]=$childOutput[$key]}
        }
        if ($fields.Contains('report_path') -and $fields.Contains('report_sha256')) {$fields.Remove('report_status')}
    }
    # Native failures retain their first cause in the existing private evidence.
    if (-not $fields.Contains('report_path')) {
        try {
            $private=[ordered]@{phase=$Phase;trace=$Failure.Exception.ToString();script_stack_trace=[string]$Failure.ScriptStackTrace;exception_chain=$privateChain}
            $reference=Write-KmtechProtectedFailureSidecar -Text ((ConvertTo-KmtechRedactedSinkObject $private) | ConvertTo-Json -Depth 20)
            $fields.Remove('report_status')
            $fields.report_path=[string]$reference.path; $fields.report_sha256=[string]$reference.sha256
        } catch { $fields.report_status='REPORT_UNAVAILABLE' }
    }
    return ConvertTo-KmtechPublicRecord $fields
}

function Wait-LabelRelayPreimageExit([object[]]$Expected) {
    $elapsedWatch=[Diagnostics.Stopwatch]::StartNew();$elapsedStatus='ERROR'
    try {

    $deadline=(Get-Date).AddSeconds($Script:LabelRelayNormalStopTimeoutSeconds)
    do {
        $remaining=@(UnquiescedProductWriters)
        foreach ($row in $remaining) {
            $matches=@($Expected | Where-Object {
                (Same ([string]$_.ExecutablePath) ([string]$row.ExecutablePath)) -and
                (Normalize-RelayExecutableQuoting ([string]$_.CommandLine) ([string]$_.ExecutablePath)) -ceq
                (Normalize-RelayExecutableQuoting ([string]$row.CommandLine) ([string]$row.ExecutablePath))
            })
            if ($matches.Count -ne 1) { throw 'Unexpected writer remains after normal removal.' }
        }
        if ($remaining.Count -eq 0) { $elapsedStatus='COMPLETE'; return }
        Start-Sleep -Milliseconds 100
    } while ((Get-Date) -lt $deadline)
    throw 'Normal relay process exit remains unproven.'

        $elapsedStatus='COMPLETE'
    } finally {
        $elapsedWatch.Stop()
        try { Write-LabelWaitElapsed 'relay_process_exit' $elapsedWatch.ElapsedMilliseconds $elapsedStatus } catch {}
    }
}

function HealthyLifecycle([string]$Root, [string]$Installed, [string]$Mode = 'inspect', [string]$ExpectedStateSha256 = '') {
    # Only the attested candidate is imported. This path does not enroll, rotate
    # identities, reconcile authorities, or create conflict-resolution receipts.
    $probe = @'
import hashlib, json, pathlib, sys
root, installed = map(pathlib.Path, sys.argv[1:3])
mode = sys.argv[3]
expected = sys.argv[4] if len(sys.argv) > 4 else ''
sys.path[:0] = [str(root / 'app'), str(root / 'app/site-packages')]
import current_user_onboarding as onboarding
from label_exact_clone_resolution import client_authorities, read_bounded_json
from producer_runtime_client import _scope_values, _scope_key
from tools.register_label_match_worker_pc import _current_machine_guid, _current_user_sid, derive_path_independent_install_id
from user_relay import release_user_relay_stop_marker, user_relay_stop_path
from user_relay_stop_marker import read_stop_marker, _validated_node, canonical_marker_bytes
from writer_session_fence import writer_admission, active_fence

def inspect():
    paths = onboarding.resolve_current_user_onboarding_paths(installed)
    reference = read_bounded_json(paths.credential_path, label='producer credential reference')
    secret_ref = str(reference.get('secret_ref') or '')
    if (reference.get('secret') or not secret_ref.startswith('dpapi:') or
        pathlib.Path(reference.get('secret_data_dir') or paths.direct_sync_root).resolve() != paths.direct_sync_root):
        raise ValueError('healthy lifecycle requires canonical current-user DPAPI credentials')
    secret_name = secret_ref.split(':', 1)[1]
    if not secret_name or any(character in secret_name for character in '/\\:'):
        raise ValueError('healthy lifecycle credential reference is invalid')
    protected = [paths.identity_path, paths.producer_manifest_path, paths.credential_path,
                 paths.registration_report_path, paths.logistics_profile_path, paths.logistics_secret_path,
                 paths.direct_sync_root / 'secrets' / (secret_name + '.dpapi')]
    database = paths.direct_sync_root / 'queue/direct_sync_relay.sqlite3'
    for path in protected + [paths.direct_sync_root, paths.data_root, paths.settings_path, database]:
        for parent in (path, *path.parents):
            if parent.is_symlink() or (parent.exists() and parent.lstat().st_file_attributes & 0x400):
                raise ValueError('healthy lifecycle state contains a reparse point')
    state = onboarding.inspect_current_user_state(paths)
    if state['status'] != 'READY':
        raise ValueError('healthy lifecycle requires complete current-user identity and credential readback')
    identity = read_bounded_json(paths.identity_path, label='producer identity')
    local_install_id = derive_path_independent_install_id(machine_guid=_current_machine_guid(), user_sid=_current_user_sid())
    if identity['producer_install_id'] != local_install_id:
        raise ValueError('healthy lifecycle identity belongs to another machine or user')
    credential = onboarding.load_credentials_from_json(paths.credential_path)
    if credential.producer_id != identity['producer_id']:
        raise ValueError('healthy lifecycle credential identity differs')
    scope = _scope_values(credential, identity['producer_install_id'])
    if database.exists():
        for authority in client_authorities(database):
            if (authority['authority_scope'] != _scope_key(scope) or
                any(authority[name] != value for name, value in scope.items()) or
                authority['status'] not in {'ACTIVE', 'PENDING'} or authority['last_error_code']):
                raise ValueError('healthy lifecycle runtime authority is foreign, quarantined, or requires recovery')
    digest = hashlib.sha256()
    for path in protected:
        digest.update(str(path).encode('utf-8'))
        with path.open('rb') as stream:
            digest.update(hashlib.file_digest(stream, 'sha256').digest())
    state_hash = digest.hexdigest()
    if expected and state_hash != expected:
        raise ValueError('healthy lifecycle protected identity changed during replacement')
    result = dict(status='HEALTHY_CURRENT_USER', state_sha256=state_hash, marker_present=False)
    marker_path = user_relay_stop_path(paths.direct_sync_root)
    if marker_path.exists():
        marker, raw, marker_hash = read_stop_marker(marker_path)
        _validated_node(marker)
        if raw != canonical_marker_bytes(marker):
            raise ValueError('healthy lifecycle stop marker is not canonical')
        if mode in ('inspect_recovery', 'release_recovery') and expected:
            if marker_hash != expected:
                raise ValueError('recovery stop request differs')
            result.update(marker_present=True, request_id=marker['request_id'], marker_sha256=marker_hash)
            return paths, result
        removal = read_bounded_json(paths.removal_report_path, label='normal removal report')
        relay = removal.get('relay_process', {})
        if (removal.get('status') != 'PASS_DATA_PRESERVED' or removal.get('data_preserved') is not True or
            pathlib.Path(removal.get('machine_code_root', '')).resolve() != installed.resolve() or
            relay.get('status') != 'ABSENT' or relay.get('request_id') != marker['request_id'] or
            relay.get('stop_request_sha256') != marker_hash):
            raise ValueError('healthy lifecycle stop marker is not the exact normal removal marker')
        result.update(marker_present=True, request_id=marker['request_id'], marker_sha256=marker_hash)
    return paths, result

if mode in ('inspect', 'inspect_recovery'):
    _, result = inspect()
elif mode in ('release', 'release_recovery') and expected:
    # The canonical transaction still holds its active writer fence. Admission
    # validates the candidate identity and exact session delegation before the
    # marker is inspected or removed; ordinary onboarding retains its own guard.
    with writer_admission('user_relay_stop_release'):
        if active_fence() is None:
            raise ValueError('healthy lifecycle release requires an active replacement fence')
        paths, result = inspect()
        if not result['marker_present']:
            raise ValueError('normal removal marker disappeared before release')
        result['release'] = release_user_relay_stop_marker(paths.direct_sync_root,
            expected_request_id=result['request_id'], expected_sha256=result['marker_sha256'])
else:
    raise ValueError('unsupported healthy lifecycle operation')
print(json.dumps(result, sort_keys=True))
'@
    # LF-normalized UTF-8 is the fixed probe identity on PS5.1 and PS7.
    $probeBytes = [Text.Encoding]::UTF8.GetBytes($probe.Replace("`r`n", "`n"))
    $stdout = Invoke-LabelPinnedProbe -Python (Join-Path $Root 'runtime\python.exe') `
        -ProbeBytes $probeBytes -ExpectedSha256 '0b515260a4cf6dec9fdf8aaa935cfaaad2a0a5d92b0f4716c0e03c1ae96e8ff4' `
        -ProbeArguments @($Root, $Installed, $Mode, $ExpectedStateSha256) -FailureMessage 'Pinned conflict-resolution receipt source validation is required; healthy lifecycle validation failed: '
    return $stdout | ConvertFrom-Json
}

function ConvertTo-LabelTaskSid([string]$Identity) {
    if ([string]::IsNullOrWhiteSpace($Identity)) { throw 'TASK_USER_ID_UNRESOLVED' }
    if ($Identity -match '^S-1-') {
        return [Security.Principal.SecurityIdentifier]::new($Identity).Value
    }
    return [Security.Principal.NTAccount]::new($Identity).Translate([Security.Principal.SecurityIdentifier]).Value
}

function Assert-HealthyLifecycleOwnership($Run, $RelayValues, $Tasks, [string]$Installed) {
    if ($Run.exists -and ([string]$Run.kind -cne 'String' -or [string]$Run.data -cne (Command $Installed))) {
        throw 'Healthy lifecycle autostart belongs to another command.'
    }
    $relayRoot=RelayCodeRoot $Installed
    $userSid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    if (@($RelayValues).Count -gt 1) { throw 'Healthy lifecycle relay ownership is ambiguous.' }
    foreach ($relay in $RelayValues) {
        $owner = Invoke-CimMethod -InputObject $relay -MethodName GetOwnerSid -ErrorAction Stop
        if ($owner.ReturnValue -ne 0 -or [string]$owner.Sid -cne $userSid -or
            -not (Same ([string]$relay.ExecutablePath) (Join-Path $relayRoot 'runtime\pythonw.exe')) -or
            (Normalize-RelayExecutableQuoting ([string]$relay.CommandLine) (Join-Path $relayRoot 'runtime\pythonw.exe')) -cne (Command $relayRoot)) {
            throw 'Healthy lifecycle relay belongs to another owner or command.'
        }
    }
    foreach ($task in $Tasks) {
        $taskSid = ConvertTo-LabelTaskSid ([string]$task.Principal.UserId)
        if ($taskSid -cne $userSid -or [string]$task.Principal.RunLevel -cne 'Limited' -or
            [string]$task.Principal.LogonType -cne 'Interactive') {
            throw 'Healthy lifecycle task belongs to another principal.'
        }
        $actions = @($task.Actions)
        $expectedArguments = '-I -B ' + (Arg (Join-Path $Installed 'app\main.py')) +
            ' --label-match-scheduled-relay --app-root ' + (Arg $Installed) +
            ' --log-path ' + (Arg (Join-Path $defaultDirectSyncRoot 'logs\scheduled_direct_sync_relay.jsonl'))
        if ($actions.Count -ne 1 -or
            -not (Same ([string]$actions[0].Execute) (Join-Path $Installed 'runtime\python.exe')) -or
            [string]$actions[0].Arguments -cne $expectedArguments -or
            -not (Same ([string]$actions[0].WorkingDirectory) (Join-Path $Installed 'app'))) {
            throw 'Healthy lifecycle task belongs to another command.'
        }
    }
}

function Test-PretransactionInstallAudit([string]$AuditRoot, [string]$FenceActivePath) {
    # Read-only admission: unknown or unprovable state remains installation residue.
    $Script:LabelIgnoredPretransactionRunIds = @()
    try {
        if (Test-Path -LiteralPath $FenceActivePath -ErrorAction Stop) { return $false }
        $ancestor = [IO.Path]::GetFullPath($AuditRoot)
        while ($ancestor) {
            try { $item = Get-Item -LiteralPath $ancestor -Force -ErrorAction Stop }
            catch [Management.Automation.ItemNotFoundException] { $item = $null }
            if ($null -ne $item -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { return $false }
            $ancestor = [IO.Path]::GetDirectoryName($ancestor)
        }
        if (-not (Test-Path -LiteralPath $AuditRoot -ErrorAction Stop)) { return $true }
        if (-not (Test-Path -LiteralPath $AuditRoot -PathType Container -ErrorAction Stop)) { return $false }
        $entries = @(Get-ChildItem -LiteralPath $AuditRoot -Force -ErrorAction Stop)
        $runs = @{}
        foreach ($entry in $entries) {
            if ($entry.Name -cnotmatch '^canonical-portable-([a-zA-Z0-9-]+?)(-helper|-task-preimage\.xml|-stop-preimage\.json|-removal-preimage\.json|\.json(?:\.tmp\..*)?)$') { return $false }
            $id = $Matches[1]
            $suffix = $Matches[2]
            if ($id.EndsWith('-first-registration-attempt', [StringComparison]::Ordinal)) { return $false }
            if ($entry.PSIsContainer -ne ($suffix -ceq '-helper')) { return $false }
            if (-not $runs.ContainsKey($id)) { $runs[$id] = @() }
            $runs[$id] += $suffix
            # Inspect helpers without following a reparse directory, including hidden files.
            $pending = @($entry)
            while ($pending.Count -ne 0) {
                $current = $pending[0]
                $pending = @($pending | Select-Object -Skip 1)
                if ($current.Attributes -band [IO.FileAttributes]::ReparsePoint) { return $false }
                if ($current.PSIsContainer) {
                    $pending += @(Get-ChildItem -LiteralPath $current.FullName -Force -ErrorAction Stop)
                }
                else {
                    $stream = [IO.File]::OpenRead($current.FullName)
                    try { [void]$stream.ReadByte() } finally { $stream.Dispose() }
                    if ($current.Name -cmatch '\.json(?:\.tmp\..*)?$') {
                        $jsonText = Get-Content -LiteralPath $current.FullName -Raw -Encoding UTF8 -ErrorAction Stop
                        if ([string]::IsNullOrWhiteSpace($jsonText)) { return $false }
                        $json = $jsonText | ConvertFrom-Json -ErrorAction Stop
                    }
                }
            }
        }
        foreach ($id in $runs.Keys) {
            if ($runs[$id] -cnotcontains '.json') {
                if (@($runs[$id] | Where-Object { $_.StartsWith('.json', [StringComparison]::Ordinal) }).Count -ne 0) { return $false }
                continue
            }
            $record = Get-Content -LiteralPath (Join-Path $AuditRoot ('canonical-portable-' + $id + '.json')) -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            if ([string]$record.schema -cne 'label-match-canonical-portable-install-v1') { return $false }
            $admissionFailure = [string]$record.status -ceq 'FAILED' -and
                [string]$record.preparation_status -ceq 'FAILED_PREPARATION_ADMISSION' -and
                [string]$record.code_placement -ceq 'NOT_STARTED' -and
                $record.rollback.applied -is [bool] -and -not $record.rollback.applied -and
                ($record.PSObject.Properties.Name -cnotcontains 'current_user_setup_started' -or
                    -not $record.current_user_setup_started) -and
                ($record.PSObject.Properties.Name -cnotcontains 'writer_fence')
            $preimageOnly = [string]$record.status -cin @('PREIMAGE_SAVED', 'FAILED_PREPARATION_ADMISSION', 'FAILED_PRETRANSACTION') -and
                [string]$record.code_placement -ceq 'PENDING' -and
                $record.current_user_setup_started -is [bool] -and -not $record.current_user_setup_started -and
                [string]$record.current_user_registration_mode -ceq 'FIRST_INSTALL'
            if (-not ($admissionFailure -or $preimageOnly)) { return $false }
        }
        $Script:LabelIgnoredPretransactionRunIds = [string[]]@($runs.Keys | Sort-Object)
        return $true
    }
    catch { return $false }
}

function Test-PristineInstallState(
    [string]$InstallRootValue,
    $RunSnapshotValue,
    [object[]]$RelaySnapshotValue,
    [object[]]$ScheduledTaskValues,
    [string[]]$ResiduePaths,
    [string]$BootstrapCaPath = "",
    [string]$PythonPath = "",
    [string]$AppRoot = ""
) {
    if (Test-Path -LiteralPath $InstallRootValue) { return $false }
    if ([bool]$RunSnapshotValue.exists) { return $false }
    if (@($RelaySnapshotValue).Count -ne 0) { return $false }
    if (@($ScheduledTaskValues).Count -ne 0) { return $false }
    # A public trust bundle is not producer registration. Admit only the
    # expected leaf in its otherwise empty directory, using the existing
    # bounded, certificate-only profile validator. Nothing is removed.
    $publicCaOnly = $false
    $caParent = ''
    if (-not [string]::IsNullOrWhiteSpace($BootstrapCaPath)) {
        $BootstrapCaPath = [IO.Path]::GetFullPath($BootstrapCaPath)
        $caParent = [IO.Path]::GetDirectoryName($BootstrapCaPath)
        $ancestor = $BootstrapCaPath
        while ($ancestor) {
            try { $item = Get-Item -LiteralPath $ancestor -Force -ErrorAction Stop }
            catch [Management.Automation.ItemNotFoundException] { $item = $null }
            if ($null -ne $item -and
                (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                return $false
            }
            $ancestor = [IO.Path]::GetDirectoryName($ancestor)
        }
        if (Test-Path -LiteralPath $caParent) {
            if (-not (Test-Path -LiteralPath $caParent -PathType Container)) { return $false }
            $entries = @(Get-ChildItem -LiteralPath $caParent -Force -ErrorAction Stop)
            if ($entries.Count -ne 1 -or $entries[0].PSIsContainer -or
                -not [StringComparer]::OrdinalIgnoreCase.Equals($entries[0].FullName, $BootstrapCaPath) -or
                [string]::IsNullOrWhiteSpace($PythonPath) -or [string]::IsNullOrWhiteSpace($AppRoot)) {
                return $false
            }
            $certificateProbe = @'
import sys
sys.path.insert(0, sys.argv[1])
try:
    from tools.install_logistics_runtime_profile import _resolve_tls_ca_bundle
    _resolve_tls_ca_bundle(sys.argv[2], sys.argv[2])
except Exception:
    sys.exit(1)
'@
            $output = @(& $PythonPath -I -B -c $certificateProbe $AppRoot $BootstrapCaPath)
            if ($LASTEXITCODE -ne 0 -or $output.Count -ne 0) { return $false }
            $publicCaOnly = $true
        }
    }
    foreach ($path in $ResiduePaths) {
        if ([string]::IsNullOrWhiteSpace($path)) {
            throw 'Pristine-install residue path is empty.'
        }
        if ($publicCaOnly -and
            ([StringComparer]::OrdinalIgnoreCase.Equals([IO.Path]::GetFullPath($path), $BootstrapCaPath) -or
             [StringComparer]::OrdinalIgnoreCase.Equals([IO.Path]::GetFullPath($path), $caParent))) {
            continue
        }
        if (Test-Path -LiteralPath $path) { return $false }
    }
    return $true
}

function Test-LegacyFirstRegistrationState(
    [bool]$ExistingVerified,
    $WriterTransition,
    $RunSnapshotValue,
    [object[]]$RelaySnapshotValue,
    [object[]]$ScheduledTaskValues,
    [string[]]$ResiduePaths
) {
    # Only directions already admitted by Assert-WriterTransition qualify.
    # AST-equivalent/unknown code is not a pinned legacy release preimage.
    $pinnedDirections = @(
        'PINNED_DATA_GENERATION_G',
        'SIGNED_COMPATIBLE_DATA_GENERATION_REVERSE',
        'X13B_PINNED_SHARED_LEAF_ADOPTION',
        'PINNED_BOOTSTRAP_INTEGRITY_ORDER_FIX',
        'PINNED_LEGACY_LABEL_TRANSITION_MODE',
        'PINNED_SCAN_INPUT_FIX',
        'PINNED_W9NEXTFIX_LABEL_RECOVERY',
        'PINNED_CURRENT_USER_PROFILE_SELECTION',
        'PINNED_STARTUP_UPDATE_BOOTSTRAP'
    )
    if (-not $ExistingVerified -or
        [string]$WriterTransition.compatibility -cnotin $pinnedDirections -or
        [bool]$RunSnapshotValue.exists -or
        @($RelaySnapshotValue).Count -ne 0 -or @($ScheduledTaskValues).Count -ne 0) {
        return $false
    }
    foreach ($path in $ResiduePaths) {
        if ([string]::IsNullOrWhiteSpace($path)) { throw 'First-registration residue path is empty.' }
        # A directory at a credential filename, orphan secret/queue, or dangling
        # reparse point is partial state, never an absent credential.
        $ancestor = [IO.Path]::GetFullPath($path)
        while ($ancestor) {
            try { $item = Get-Item -LiteralPath $ancestor -Force -ErrorAction Stop }
            catch [Management.Automation.ItemNotFoundException] { $item = $null }
            if ($null -ne $item -and
                (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                return $false
            }
            if ($ancestor -ceq [IO.Path]::GetFullPath($path) -and $null -ne $item) { return $false }
            $ancestor = [IO.Path]::GetDirectoryName($ancestor)
        }
    }
    return $true
}

function FirstRegistrationAbsence([string[]]$Paths) {
    foreach ($path in $Paths) {
        try {
            $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
            [ordered]@{path=$path; state='PRESENT'; kind=$(if ($item.PSIsContainer) { 'DIRECTORY' } else { 'FILE' })}
        }
        catch [Management.Automation.ItemNotFoundException] { [ordered]@{path=$path; state='ABSENT'} }
        catch { [ordered]@{path=$path; state='UNKNOWN'; failure_type=$_.Exception.GetType().Name} }
    }
}

function FirstRegistrationAbsentAncestors([string[]]$Paths) {
    $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($path in $Paths) {
        $parent = [IO.Path]::GetDirectoryName((Full $path 'first-registration path'))
        while ($parent) {
            try { [void](Get-Item -LiteralPath $parent -Force -ErrorAction Stop); break }
            catch [Management.Automation.ItemNotFoundException] {
                if ($seen.Add($parent)) { $parent }
            }
            $parent = [IO.Path]::GetDirectoryName($parent)
        }
    }
}

function Move-LegacyFirstRegistrationState(
    [string[]]$AbsentPaths, [string]$QuarantineRoot, [bool]$ServerRegistrationMayExist,
    [string[]]$DeferredPaths = @(), [string[]]$AbsentAncestors = @(), [string]$AuditRoot = ''
) {
    $quarantine = Full $QuarantineRoot 'first-registration quarantine'
    $resolved = @($AbsentPaths | ForEach-Object { Full $_ 'first-registration state preimage' } | Select-Object -Unique)
    foreach ($path in $resolved) {
        if ((Same $path $quarantine) -or
            $quarantine.StartsWith($path.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase) -or
            $path.StartsWith($quarantine.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
            throw 'First-registration quarantine overlaps live state.'
        }
    }
    foreach ($path in @($resolved) + @($quarantine)) {
        $ancestor = $path
        while ($ancestor) {
            try { $item = Get-Item -LiteralPath $ancestor -Force -ErrorAction Stop }
            catch [Management.Automation.ItemNotFoundException] { $item = $null }
            if ($null -ne $item -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                throw 'First-registration rollback state contains a reparse point.'
            }
            $ancestor = [IO.Path]::GetDirectoryName($ancestor)
        }
    }
    $progressPath = Join-Path $quarantine 'state-moves.json'
    $initializeProgress = -not (Test-Path -LiteralPath $quarantine)
    if (Test-Path -LiteralPath $quarantine) {
        if (-not (Test-Path -LiteralPath $progressPath -PathType Leaf) -and
            @(Get-ChildItem -LiteralPath $quarantine -Force).Count -eq 0) {
            $initializeProgress = $true
        }
        elseif (-not (Test-Path -LiteralPath $progressPath -PathType Leaf) -or
            (Get-Item -LiteralPath $progressPath).Length -gt 65536) {
            throw 'First-registration quarantine progress is absent or oversized.'
        }
        if (-not $initializeProgress) {
            $previous = Get-Content -LiteralPath $progressPath -Raw -Encoding UTF8 | ConvertFrom-Json
            if ([string]$previous.schema -cne 'label-match-first-registration-quarantine-v1' -or
                -not (Same ([string]$previous.root) $quarantine) -or
                (@($previous.state_paths | ForEach-Object { $_.original_path }) -join "`n") -cne ($resolved -join "`n")) {
                throw 'First-registration quarantine belongs to another attempt.'
            }
        }
    }
    if ($initializeProgress) {
        if (-not (Test-Path -LiteralPath $quarantine)) { [void](New-Item -ItemType Directory -Path $quarantine -ErrorAction Stop) }
        $initialMap = @()
        for ($index = 0; $index -lt $resolved.Count; $index++) {
            $initialMap += [ordered]@{original_path=$resolved[$index]; quarantined_path=(Join-Path $quarantine ('state-' + $index)); preimage='ABSENT'; status='PENDING'; attempts=0; failure_type=''}
        }
        Save-LabelMachineMetadata $progressPath ([ordered]@{schema='label-match-first-registration-quarantine-v1'; root=$quarantine; state_paths=$initialMap; restored_absent=$false})
    }
    $moves = @()
    for ($index = 0; $index -lt $resolved.Count; $index++) {
        $path = $resolved[$index]
        $destination = Join-Path $quarantine ('state-' + $index)
        $present = Test-Path -LiteralPath $path
        $history = @(Get-ChildItem -LiteralPath $quarantine -Force | Where-Object {
            $_.Name -cmatch ('^state-' + $index + '(-[0-9a-f]{32})?$')
        } | ForEach-Object { $_.FullName })
        if ($present -and (Test-Path -LiteralPath $destination) -and $DeferredPaths -notcontains $path) {
            # A resumed removal can create its own new status/fence directories.
            # Append a new preserved copy; never overwrite an earlier identity.
            $destination += '-' + [Guid]::NewGuid().ToString('N')
        }
        elseif (-not $present -and $history.Count -ne 0) { $destination = $history[-1] }
        $entry = [ordered]@{original_path=$path; quarantined_path=$destination; quarantined_paths=$history; preimage='ABSENT'; status='ABSENT'; attempts=0; failure_type=''}
        if ($DeferredPaths -contains $path) { $entry.status = 'DEFERRED' }
        elseif ($present) {
            $entry.status = 'FAILED'
            for ($attempt = 1; $attempt -le 3; $attempt++) {
                $entry.attempts = $attempt
                try {
                    if (Test-Path -LiteralPath $destination) { throw 'Quarantine destination is occupied; originals preserved.' }
                    if ([IO.Directory]::Exists($path)) { Move-Item -LiteralPath $path -Destination $destination -ErrorAction Stop }
                    else { Invoke-LabelPinnedAtomicReplace -Source $path -Destination $destination -Mode Move }
                    $entry.status = 'QUARANTINED'
                    $entry.quarantined_paths += $destination
                    $entry.failure_type = ''
                    break
                }
                catch { $entry.failure_type = $_.Exception.GetType().Name }
                if ($attempt -lt 3) { Start-Sleep -Milliseconds 100 }
            }
        }
        elseif (Test-Path -LiteralPath $destination) { $entry.status = 'QUARANTINED' }
        $moves += $entry
        # Keep the complete path map on every save so a stopped/failed move can
        # be resumed by the same command without renumbering destinations.
        $map = @($moves)
        for ($pending = $index + 1; $pending -lt $resolved.Count; $pending++) {
            $map += [ordered]@{original_path=$resolved[$pending]; quarantined_path=(Join-Path $quarantine ('state-' + $pending)); preimage='ABSENT'; status='PENDING'; attempts=0; failure_type=''}
        }
        Save-LabelMachineMetadata $progressPath ([ordered]@{schema='label-match-first-registration-quarantine-v1'; root=$quarantine; state_paths=$map; restored_absent=$false})
    }
    $ancestorMoves = @()
    if ($DeferredPaths.Count -eq 0) {
        foreach ($parent in @($AbsentAncestors | Sort-Object Length -Descending)) {
            $entry = [ordered]@{path=$parent; state='ABSENT'}
            if (Test-Path -LiteralPath $parent) {
                if ($AuditRoot -and ((Same $parent $AuditRoot) -or
                    $AuditRoot.StartsWith($parent.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase))) {
                    $entry.state = 'RETAINED_FOR_ATTEMPT_AUDIT'
                }
                elseif (@(Get-ChildItem -LiteralPath $parent -Force -ErrorAction Stop).Count -eq 0) {
                    $destination = Join-Path $quarantine ('ancestor-' + $ancestorMoves.Count)
                    $entry.state = 'PRESENT'
                    for ($attempt = 1; $attempt -le 3; $attempt++) {
                        try { Move-Item -LiteralPath $parent -Destination $destination -ErrorAction Stop; $entry.state='ABSENT'; break }
                        catch { $entry.failure_type=$_.Exception.GetType().Name }
                        if ($attempt -lt 3) { Start-Sleep -Milliseconds 100 }
                    }
                }
                else { $entry.state = 'PRESENT_UNOWNED_CONTENT_PRESERVED' }
            }
            $ancestorMoves += $entry
        }
    }
    $readback = @(FirstRegistrationAbsence @($resolved | Where-Object { $DeferredPaths -notcontains $_ }))
    $remaining = @($readback | Where-Object { $_.state -cne 'ABSENT' })
    $remaining += @($ancestorMoves | Where-Object { $_.state -cnotin @('ABSENT', 'RETAINED_FOR_ATTEMPT_AUDIT') })
    $result = [ordered]@{schema='label-match-first-registration-quarantine-v1'; root=$quarantine; state_paths=$moves; ancestors=$ancestorMoves; absence_readback=$readback; remaining_paths=$remaining; restored_absent=($remaining.Count -eq 0); server_registration_may_exist=$ServerRegistrationMayExist; server_rollback_performed=$false}
    Save-LabelMachineMetadata $progressPath $result
    return $result
}

function Read-FirstRegistrationAttempt(
    [string]$AuditRoot, [string]$Install, [string]$SourceCommit, [string]$InstallerSha256,
    [string[]]$ExpectedPaths
) {
    if (-not (Test-Path -LiteralPath $AuditRoot)) { return $null }
    $pending = @()
    foreach ($file in @(Get-ChildItem -Force -LiteralPath $AuditRoot -Filter 'canonical-portable-*-first-registration-attempt.json' -File)) {
        if (($file.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or $file.Length -gt 65536) {
            throw 'First-registration attempt record is unsafe or oversized.'
        }
        $record = Get-Content -LiteralPath $file.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
        if ([string]$record.status -cin @('PASS', 'FAILED_ROLLED_BACK')) { continue }
        [void](Get-RequiredExternalBoolean $record 'state_verified')
        [void](Get-RequiredExternalBoolean $record 'registration_started')
        if ([string]$record.schema -cne 'label-match-first-registration-attempt-v1' -or
            [string]$record.status -cnotin @('PREFLIGHT_RECORDED', 'RUNNING', 'FAILED_ROLLBACK_INCOMPLETE') -or
            [string]$record.run_id -cnotmatch '^\d{8}T\d{9}Z-[0-9a-f]{32}$' -or
            $file.Name -cne ('canonical-portable-' + [string]$record.run_id + '-first-registration-attempt.json') -or
            -not (Same ([string]$record.install_root) $Install) -or
            [string]$record.source_commit -cne $SourceCommit -or
            [string]$record.orchestrator_sha256 -cne $InstallerSha256 -or
            -not (Same ([string]$record.quarantine_root) (Join-Path $AuditRoot ('canonical-portable-' + [string]$record.run_id + '-first-registration-quarantine'))) -or
            [string]$record.writer_session_id -cnotmatch '^[0-9a-f]{32}$' -or
            [string]$record.writer_attempt_id -cnotmatch '^[0-9a-f]{32}$' -or
            [string]$record.writer_transaction_id -cnotmatch '^[0-9a-f]{32}$' -or
            (@($record.absent_paths) -join "`n") -cne ($ExpectedPaths -join "`n")) {
            throw 'Pending first-registration cleanup requires the exact original installer and paths.'
        }
        foreach ($parent in @($record.absent_ancestors)) {
            $matches = @($ExpectedPaths | Where-Object {
                $_.StartsWith(([string]$parent).TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)
            })
            $userRoot = Full ([string]$env:LOCALAPPDATA) 'current-user state boundary'
            if ($matches.Count -eq 0 -or -not [IO.Path]::IsPathRooted([string]$parent) -or
                -not ([string]$parent).StartsWith($userRoot.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
                throw 'First-registration absent ancestor is outside its state paths.'
            }
        }
        foreach ($path in @($ExpectedPaths) + @($AuditRoot, [string]$record.quarantine_root)) {
            $ancestor = Full $path 'first-registration recovery path'
            while ($ancestor) {
                try { $item = Get-Item -LiteralPath $ancestor -Force -ErrorAction Stop }
                catch [Management.Automation.ItemNotFoundException] { $item = $null }
                if ($null -ne $item -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) {
                    throw 'First-registration recovery path contains a reparse point.'
                }
                $ancestor = [IO.Path]::GetDirectoryName($ancestor)
            }
        }
        $record.PSObject.Properties.Remove('record_path')
        $record | Add-Member -NotePropertyName record_path -NotePropertyValue $file.FullName
        $pending += $record
    }
    if ($pending.Count -gt 1) { throw 'Multiple pending first-registration attempts require supported recovery.' }
    if ($pending.Count -eq 1) { return $pending[0] }
    return $null
}

function Save-FirstRegistrationAttempt($Record, [string]$Path) {
    if ($null -ne $Record) { Save-LabelMachineMetadata $Path $Record }
}

function Save-LabelPlacementRecoveryPreimages {
    # Dot-source in the transaction scope. A rejected result can follow real
    # protected mutations, so capture actual verified recovery inputs on errors
    # as well as on a returned native exit code.
    $startupPreimage = Join-Path (Split-Path -Parent $install) ('.startup-update-install.' + $writerAttemptId)
    if (Test-Path -LiteralPath (Join-Path $startupPreimage 'preimage.json')) {
        $audit.startup_update_preimage = [ordered]@{path=$startupPreimage;sha256=(Sha (Join-Path $startupPreimage 'preimage.json'))}
    }
    if ($existingVerified -and $null -eq $startupLifecycle -and [string]::IsNullOrEmpty($replacementRollbackRoot)) {
        $replacementRollbackRoot = ReplacementPreimage $install $installedPreimageInventory $replacementBackupsBefore
        if ($legacyFirstRegistration) {
            $firstRegistrationAttempt.code_backup_root = $replacementRollbackRoot
            Save-FirstRegistrationAttempt $firstRegistrationAttempt $firstRegistrationAttemptPath
        }
    }
}

function Save-LabelRollbackContext {
    # Only restoration inputs are persisted; delegation is regenerated on resume.
    $values = [ordered]@{}
    foreach ($name in @('before','old','taskBefore','stopBefore','healthyRemovalReportBefore',
        'removalReportExisted','existingVerified','installedPreimageInventory','replacementRollbackRoot',
        'receiptSource','writerTransition','legacyFirstRegistration','healthyRemovedInstall',
        'firstRegistrationStateVerified','firstRegistrationStarted','firstRegistrationAttempt',
        'firstRegistrationAttemptPath','firstRegistrationStatePaths','firstRegistrationAbsentAncestors',
        'rollbackSources','restoreSources','replacementBackupsBefore')) {
        $variable = Get-Variable -Name $name -Scope 1 -ErrorAction SilentlyContinue
        $values[$name] = if ($null -ne $variable) { $variable.Value } else { $null }
    }
    $previous = if ($audit.Contains('recovery_context')) { $audit.recovery_context } else { $null }
    $audit.recovery_context = [ordered]@{operator_sid=$generationSubjectSid;source_root=$source;
        orchestrator_sha256=$writerOrchestratorSha256;writer_contract_sha256=$writerContractSha256;
        generation_marker_paths=@($generationMarkerPaths);values=$values}
    if ($null -ne $previous) {
        # The context saved before the first change is overwritten by the failure
        # path. Identity and the validated preimages must be the same values; only
        # the inputs learned later (such as the code preimage folder) may refine.
        # A comparison problem is recorded; it never blocks the rollback itself.
        $drift = @()
        try {
            foreach ($name in @('operator_sid','source_root','orchestrator_sha256','writer_contract_sha256')) {
                if ([string]$previous[$name] -cne [string]$audit.recovery_context[$name]) { $drift += $name }
            }
            foreach ($name in @('before','taskBefore','stopBefore','existingVerified','installedPreimageInventory',
                'receiptSource','writerTransition','rollbackSources','restoreSources')) {
                $was = [string](ConvertTo-Json -InputObject $previous.values[$name] -Depth 30 -Compress)
                $now = [string](ConvertTo-Json -InputObject $values[$name] -Depth 30 -Compress)
                if ($was -cne $now) { $drift += $name }
            }
        } catch { $drift += 'comparison_failed' }
        if ($drift.Count -ne 0) { $audit.rollback.recovery_context_drift = @($drift) }
    }
}

function Save-LabelPreChangeRecoveryContext {
    # Dot-source in the transaction scope before the first change. The failure
    # path saves the same context again; a run that dies before it can still be
    # rolled back by the supported resume.
    if ($existingVerified) {
        $replacementBackupsBefore = @(Get-ChildItem -LiteralPath (Split-Path -Parent $install) -Directory -Force |
            Where-Object { $_.Name -like '.current.rollback.*' } | ForEach-Object { $_.FullName })
    }
    Save-LabelRollbackContext
    Save $auditPath $audit
    $readback = Get-Content -LiteralPath $auditPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $saved = $readback.recovery_context
    $context = $audit.recovery_context
    # Same shape on disk: identity, hashes and the exact set of saved input names.
    if ($null -eq $saved -or [string]$saved.operator_sid -cne [string]$context.operator_sid -or
        [string]$saved.source_root -cne [string]$context.source_root -or
        [string]$saved.orchestrator_sha256 -cne [string]$context.orchestrator_sha256 -or
        [string]$saved.writer_contract_sha256 -cne [string]$context.writer_contract_sha256 -or
        (@($saved.values.PSObject.Properties.Name | Sort-Object) -join ',') -cne (@($context.values.Keys | Sort-Object) -join ',') -or
        (ConvertTo-Json -InputObject $saved.values.before -Depth 30 -Compress) -cne (ConvertTo-Json -InputObject $context.values.before -Depth 30 -Compress) -or
        (ConvertTo-Json -InputObject $saved.values.replacementBackupsBefore -Depth 30 -Compress) -cne (ConvertTo-Json -InputObject $context.values.replacementBackupsBefore -Depth 30 -Compress)) {
        throw 'Recovery context readback differs.'
    }
}

function Save-LabelPreFenceWriterTuple {
    # Dot-source in the transaction scope BEFORE Start-LabelWriterFence (G99c).
    # The fence tuple (the same values the protected owner record later carries)
    # is saved in the audit and read back first, so an installer killed right
    # after it made the fence never leaves a fence whose audit has no tuple.
    $audit.writer_fence = [ordered]@{
        status = 'PENDING_FENCE'
        owner_process_id = [int]$PID
        owner_process_started_at_filetime = $writerOwnerStartedAtFileTime
        orchestrator_sha256 = $writerOrchestratorSha256
        writer_contract_sha256 = $writerContractSha256
        session_started_at_utc = $writerStartedAt
        session_id = $writerSessionId
        attempt_id = $writerAttemptId
        replacement_transaction_id = $writerTransactionId
        writer_inventory_sha256 = $Script:LabelWriterFenceInventorySha256
        token_recorded = $false
    }
    Save $auditPath $audit
    $readback = (Get-Content -LiteralPath $auditPath -Raw -Encoding UTF8 | ConvertFrom-Json).writer_fence
    foreach ($name in @('session_id','attempt_id','replacement_transaction_id','session_started_at_utc',
        'orchestrator_sha256','writer_contract_sha256','writer_inventory_sha256',
        'owner_process_id','owner_process_started_at_filetime')) {
        if ($null -eq $readback -or [string]$readback.$name -cne [string]$audit.writer_fence[$name]) {
            throw 'Writer fence tuple readback differs.'
        }
    }
}

function Invoke-LabelPreFenceOwnerRecord($Frozen, [hashtable]$HelperParameters, [hashtable]$Tuple) {
    # 118 review: the protected owner record (written by the elevated helper) is
    # published BEFORE the fence exists, from the caller's tuple, and read back.
    # An installer killed at any later point then always leaves a fence together
    # with its owner record; a kill before the fence leaves only an inert record.
    if ($testMode) { return }
    $parameters = $HelperParameters.Clone()
    $parameters.WriteInstallerOwnerRecordOnly = $true
    $parameters.InstallerOwnerWriterInventorySha256 = [string]$Tuple.writer_inventory_sha256
    $parameters.InstallerOwnerOrchestratorSha256 = [string]$Tuple.orchestrator_sha256
    $parameters.InstallerOwnerWriterContractSha256 = [string]$Tuple.writer_contract_sha256
    $parameters.InstallerOwnerSessionStartedAtUtc = [string]$Tuple.session_started_at_utc
    if ((InvokeFrozenPlacementHelper $Frozen $parameters) -ne 0) { throw 'INSTALLER_OWNER_RECORD_PREFENCE_FAILED' }
    $path = Join-Path (Split-Path -Parent ([string]$parameters.InstallRoot)) ('.installer-owner-' + [string]$Tuple.session_id + '-' + ([string]$parameters.InstallerRunId -split '-')[-1] + '.json')
    $recordText = Get-Content -LiteralPath $path -Raw -Encoding UTF8
    $record = $recordText | ConvertFrom-Json
    foreach ($name in @('session_id','attempt_id','replacement_transaction_id',
        'orchestrator_sha256','writer_contract_sha256','writer_inventory_sha256')) {
        if ([string]$record.$name -cne [string]$Tuple[$name]) { throw 'Installer owner record readback differs.' }
    }
    # Compare the start time as text: a JSON parser may turn it into a date object.
    if ($recordText -cnotmatch ('"session_started_at_utc":"' + [regex]::Escape([string]$Tuple.session_started_at_utc) + '"')) {
        throw 'Installer owner record readback differs.'
    }
    if ([string]$record.run_id -cne [string]$parameters.InstallerRunId -or
        [string]$record.owner_process_id -cne [string]$parameters.InstallerOwnerProcessId -or
        [string]$record.owner_process_started_at_filetime -cne [string]$parameters.InstallerOwnerProcessStartedAtFileTime) {
        throw 'Installer owner record readback differs.'
    }
}

function Save-LabelMachinePreFenceRecord {
    # Dot-source in the machine transaction scope BEFORE Start-LabelWriterFence.
    # Same idea as Save-LabelPreFenceWriterTuple (tuple saved and read back before
    # the fence) plus a kind-only context marker: the machine path has no user
    # rollback inputs and the marker carries no secret (only the worker SID that
    # the audit already holds). A dead run is settled by removal/reinstall.
    $audit.writer_fence = [ordered]@{
        status = 'PENDING_FENCE'
        owner_process_id = [int]$PID
        owner_process_started_at_filetime = $ownerStartedAtFileTime
        orchestrator_sha256 = $orchestrator
        writer_contract_sha256 = $contract
        session_started_at_utc = $sessionStartedAt
        session_id = $session
        attempt_id = $attempt
        replacement_transaction_id = $transaction
        writer_inventory_sha256 = $Script:LabelWriterFenceInventorySha256
        token_recorded = $false
    }
    $audit.recovery_context = [ordered]@{kind = 'MACHINE_WORKER_DEFERRED'; worker_sid = [string]$Worker.sid}
    Save $auditFile $audit
    $readback = Get-Content -LiteralPath $auditFile -Raw -Encoding UTF8 | ConvertFrom-Json
    foreach ($name in @('session_id','attempt_id','replacement_transaction_id','session_started_at_utc',
        'orchestrator_sha256','writer_contract_sha256','writer_inventory_sha256',
        'owner_process_id','owner_process_started_at_filetime')) {
        if ($null -eq $readback.writer_fence -or [string]$readback.writer_fence.$name -cne [string]$audit.writer_fence[$name]) {
            throw 'Machine writer fence tuple readback differs.'
        }
    }
    if ([string]$readback.recovery_context.kind -cne 'MACHINE_WORKER_DEFERRED') { throw 'Machine recovery context readback differs.' }
}

function Assert-LabelDeadUnfinishedInstaller([string]$AuditPath) {
    # Death proof of the unfinished run: protected owner record equals the fence
    # tuple, the owner process ended with the same start time, no product writer
    # process or relay remains. The same code that serves the supported user
    # removal answers; nothing is changed.
    $python = Join-Path $source 'runtime\python.exe'
    $appRoot = Join-Path $source 'app'
    if (-not (Test-Path -LiteralPath $python -PathType Leaf) -or -not (Test-Path -LiteralPath $appRoot -PathType Container)) {
        throw 'Dead installer proof needs the packaged runtime.'
    }
    $code = "import sys;from pathlib import Path;p=Path(sys.argv[1]);sys.path[:0]=[str(p),str(p/'site-packages')];from writer_session_fence import prove_dead_unfinished_installer as f;sys.exit(0 if f(sys.argv[2]) else 3)"
    $startInfo = [Diagnostics.ProcessStartInfo]::new()
    $startInfo.FileName = $python
    $startInfo.Arguments = '-I -B -c {0} {1} {2}' -f (Arg $code), (Arg $appRoot), (Arg $AuditPath)
    $startInfo.UseShellExecute = $false
    $startInfo.CreateNoWindow = $true
    $process = [Diagnostics.Process]::Start($startInfo)
    if (-not $process.WaitForExit(120000)) { try { $process.Kill() } catch { }; throw 'Dead installer proof timed out.' }
    if ($process.ExitCode -ne 0) { throw 'Dead installer proof failed: the installation may still be running or its owner is unproven.' }
}

function Invoke-LabelGenerationRefusalRecovery {
    $audit.rollback.generation_refused = $true
    $audit.rollback.guidance = '새 판이 이 PC 자료를 열어 옛 판으로 되돌릴 수 없습니다. 새 판과 자료를 보존합니다. 같은 새 판을 다시 시작하거나 호환 수정판을 설치하세요. 관리자 지원 재개: INSTALL_CANONICAL_PORTABLE.ps1 -ResumeRollbackAuditPath <감사 파일> -ExpectedRollbackAuditSha256 <감사 SHA256>.'
    $newVersionProven = $false
    . Invoke-LabelRollbackStep 'retained_candidate_readback' {
        if (-not $rollbackCustodyReady -or -not $rollbackProtectionReady) { throw 'Retained candidate protection is unproven.' }
        if ($audit.Contains('legacy_relay_task_preimage')) {
            $legacy=Get-LabelOfficialLegacyTaskSnapshot
            if ($null -eq $legacy -or $legacy.enabled) { throw 'Legacy relay stop is unproven.' }
        }
        $manifest = Manifest $install $SkipSignatureValidationForTest
        [void](Assert-LabelDataDowngrade -MarkerPaths $generationMarkerPaths -SubjectSid $generationSubjectSid `
            -TargetVersion (Get-LabelPortableDataVersion $install $manifest) -TargetBuildId ([string]$manifest.source_commit))
        InvokeFrozenIntegrityProbe $frozenPlacement $install
        if ([string](PortableInventory $install).sha256 -cne [string]$receiptSource.sha256) { throw 'Retained candidate code differs.' }
        $stopProof = $audit.rollback['new_relay_stop']
        $mode = if ($null -ne $stopProof) { 'inspect_recovery' } else { 'inspect' }
        $stopDigest = if ($null -ne $stopProof) { [string]$stopProof.stop_request_sha256 } else { '' }
        $state = HealthyLifecycle $source $install $mode $stopDigest
        if ([string]$state.status -cne 'HEALTHY_CURRENT_USER' -or ($state.marker_present -and $null -eq $stopProof)) { throw 'Retained candidate identity/stop state is unproven.' }
        $relay = Get-Content -LiteralPath $relayPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ([string]$relay.status -cne 'READY' -or -not (Test-RelayPersistentRetry $relay)) { throw 'Retained candidate relay readiness is unproven.' }
        $run = Snapshot
        if (-not $run.exists -or [string]$run.data -cne $wanted) { throw 'Retained candidate autostart differs.' }
        $newVersionProven = $true
    }
    if ($newVersionProven) {
        . Invoke-LabelRollbackStep 'retained_candidate_fence_release' {
            $stopProof = $audit.rollback['new_relay_stop']
            if ($null -ne $stopProof) {
                [void](Set-LabelWriterFenceDelegation -ControlRoot $writerFenceControlRoot -Status 'RESTORING' -SessionId $writerSessionId -AttemptId $writerAttemptId -ReplacementTransactionId $writerTransactionId -DelegationToken $writerDelegationToken -DelegatedSources @('user_relay_stop_release') -LifetimeSeconds 600)
                [void](HealthyLifecycle $source $install 'release_recovery' ([string]$stopProof.stop_request_sha256))
            }
            if ($writerFenceStarted) {
                [void](Invoke-LabelTimedWait 'placement_admission' { Stop-LabelWriterFence -ControlRoot $writerFenceControlRoot -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId -ReplacementTransactionId $writerTransactionId -TimeoutMilliseconds 120000 })
                $writerFenceStarted = $false
                $audit.writer_fence.status = 'RELEASED_FOR_RETAINED_CANDIDATE'
            }
            $audit.rollback.retained_candidate_ready = $true
        }
    } else {
        # Never reinstate an old launcher after G refuses. Remove only the exact
        # candidate Run command; a foreign persistence entry is retained/reported.
        . Invoke-LabelRollbackStep 'retained_candidate_autostart_stop' {
            $run = Snapshot
            if ($run.exists -and [string]$run.data -cne $wanted) { throw 'Autostart ownership is unproven; administrator recovery required.' }
            if ($run.exists) { Restore ([pscustomobject]@{exists=$false;kind='';data=''}) }
            if ((Snapshot).exists) { throw 'Candidate autostart absence is unproven.' }
            $audit.rollback.retained_candidate_ready = $false
        }
    }
}

function Get-LabelOrphanValue($Value,[string]$Name) {
    if($null -eq $Value){return $null}
    if($Value -is [Collections.IDictionary]){return $Value[$Name]}
    $property=$Value.PSObject.Properties[$Name]
    if($null -ne $property){return $property.Value}
    return $null
}

function Initialize-LabelOrphanNative {
    if('LabelOrphanNative' -as [type]){return}
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class LabelOrphanNative {
 [StructLayout(LayoutKind.Sequential)] struct FileInfo {
  public uint Attributes, CreatedLow, CreatedHigh, AccessedLow, AccessedHigh, WrittenLow, WrittenHigh;
  public uint Volume, SizeHigh, SizeLow, Links, IndexHigh, IndexLow;
 }
 [DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr OpenProcess(uint access,bool inherit,uint pid);
 [DllImport("kernel32.dll", SetLastError=true)] static extern bool GetProcessTimes(IntPtr process,out long created,out long exited,out long kernel,out long user);
 [DllImport("kernel32.dll")] static extern uint WaitForSingleObject(IntPtr handle,uint timeout);
 [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr handle);
 [DllImport("kernel32.dll", SetLastError=true)] static extern bool GetFileInformationByHandle(IntPtr file,out FileInfo info);
 public static bool Exited(uint pid,ulong birth) {
  if(pid==0 || birth==0) return false;
  IntPtr h=OpenProcess(0x00101000,false,pid);
  if(h==IntPtr.Zero) return Marshal.GetLastWin32Error()==87;
  try { long c,e,k,u; return GetProcessTimes(h,out c,out e,out k,out u) &&
    unchecked((ulong)c)==birth && WaitForSingleObject(h,0)==0; }
  finally { CloseHandle(h); }
 }
 public static bool SingleLink(IntPtr file) {
  FileInfo info; return GetFileInformationByHandle(file,out info) && info.Links==1;
 }
 public static ulong Created(uint pid) {
  IntPtr h=OpenProcess(0x001000,false,pid); if(h==IntPtr.Zero) return 0;
  try { long c,e,k,u; return GetProcessTimes(h,out c,out e,out k,out u) ? unchecked((ulong)c) : 0; }
  finally { CloseHandle(h); }
 }
}
'@
}

function Assert-LabelOrphanProtectedPath([string]$Path,[string]$MachineRoot='') {
    $programData=[IO.Path]::GetFullPath([Environment]::GetFolderPath('CommonApplicationData')).TrimEnd('\')
    $leaf=$true
    for($part=$Path;$part;$part=[IO.Path]::GetDirectoryName($part)){
        $item=Get-Item -LiteralPath $part -Force -ErrorAction Stop
        if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'ORPHAN_PROTECTED_REPARSE'}
        $acl=Get-Acl -LiteralPath $part -ErrorAction Stop
        $owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
        if($owner -cnotin @('S-1-5-18','S-1-5-32-544','S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')){throw 'ORPHAN_PROTECTED_OWNER'}
        $mask=if($leaf){0x500D0156}else{0x500D0150}
        if($MachineRoot){
            if([StringComparer]::OrdinalIgnoreCase.Equals($part.TrimEnd('\'),$programData) -or $programData.StartsWith($part.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){$mask=0}
            elseif([StringComparer]::OrdinalIgnoreCase.Equals($part,$MachineRoot) -or $part.StartsWith($MachineRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){
                if([StringComparer]::OrdinalIgnoreCase.Equals($part,$MachineRoot) -and -not $acl.AreAccessRulesProtected){throw 'ORPHAN_MACHINE_DACL'}
            }else{$mask=0x500D0040}
        }
        $descriptor=[Security.AccessControl.RawSecurityDescriptor]::new($acl.GetSecurityDescriptorBinaryForm(),0)
        if($mask -and $null -eq $descriptor.DiscretionaryAcl){throw 'ORPHAN_PROTECTED_NULL_DACL'}
        foreach($rule in $acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){
            if($rule.AccessControlType -eq 'Allow' -and
                ($leaf -or -not ($rule.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly)) -and
                $rule.IdentityReference.Value -cnotin @('S-1-5-18','S-1-5-32-544') -and
                ([long]$rule.FileSystemRights -band $mask)){throw 'ORPHAN_PROTECTED_MUTABLE'}
        }
        $leaf=$false
    }
}

function Read-LabelOrphanJson([string]$Path) {
    for($part=$Path;$part;$part=[IO.Path]::GetDirectoryName($part)){
        if([IO.File]::GetAttributes($part) -band [IO.FileAttributes]::ReparsePoint){throw 'ORPHAN_RECORD_REPARSE'}
    }
    $stream=[IO.File]::Open($Path,'Open','Read','Read')
    try {
        Initialize-LabelOrphanNative
        if($stream.Length -lt 1 -or $stream.Length -gt 1048576 -or
            -not [LabelOrphanNative]::SingleLink($stream.SafeFileHandle.DangerousGetHandle())){throw 'ORPHAN_RECORD_INVALID'}
        [byte[]]$bytes=([IO.BinaryReader]::new($stream)).ReadBytes([int]$stream.Length)
        $options=@{}
        if((Get-Command ConvertFrom-Json).Parameters.ContainsKey('DateKind')){$options.DateKind='String'}
        return ([Text.UTF8Encoding]::new($false,$true)).GetString($bytes).TrimStart([char]0xFEFF)|ConvertFrom-Json @options
    }finally{$stream.Dispose()}
}

function Get-LabelOrphanTuple($Record) {
    $tuple=[ordered]@{}
    foreach($name in @('session_id','attempt_id','replacement_transaction_id','writer_inventory_sha256','orchestrator_sha256','writer_contract_sha256','session_started_at_utc')){
        $value=Get-LabelOrphanValue $Record $name
        if($value -isnot [string]){throw 'ORPHAN_TUPLE_INVALID'}
        if($name -ceq 'session_started_at_utc'){
            [void][DateTimeOffset]::Parse($value,[Globalization.CultureInfo]::InvariantCulture)
        }elseif($value -cnotmatch $(if($name -cin @('session_id','attempt_id','replacement_transaction_id')){'^[0-9a-f]{32}$'}else{'^[0-9a-f]{64}$'})){
            throw 'ORPHAN_TUPLE_INVALID'
        }
        $tuple[$name]=$value
    }
    return $tuple
}

function Get-LabelOrphanProcessRows {
    return @(Get-CimInstance -ClassName Win32_Process -ErrorAction Stop)
}

function Expand-LabelOrphanCommand([string]$Command) {
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $texts=[Collections.Generic.List[string]]::new()
    [void]$seen.Add($Command);$texts.Add($Command)
    $encodings=@([Text.UTF8Encoding]::new($false,$true),[Text.UnicodeEncoding]::new($false,$false,$true))
    # Windows PowerShell 5.1 and pwsh both take '-', '/', an en dash, an em dash or a horizontal bar,
    # then EC or any case-insensitive prefix of EncodedCommand, then the Base64 payload (bare or quoted).
    $switch='(?:^|[\s"''(])[-/\u2013\u2014\u2015]([A-Za-z]+)(?=\s)'
    for($index=0;$index -lt $texts.Count;$index++){
        foreach($found in [regex]::Matches($texts[$index],$switch)){
            $name=$found.Groups[1].Value.ToLowerInvariant()
            if($name -cne 'ec' -and -not 'encodedcommand'.StartsWith($name,[StringComparison]::Ordinal)){continue}
            # Scan switch names separately so an unrelated flag cannot consume the next switch.
            $argumentMatch=[regex]::Match($texts[$index].Substring($found.Index+$found.Length),'^\s+("[^"]*"|''[^'']*''|[^\s]+)')
            if(-not $argumentMatch.Success){continue} # No argument retains the existing behavior.
            $argument=$argumentMatch.Groups[1].Value
            if($argument.Length -ge 2 -and ($argument[0] -eq [char]34 -or $argument[0] -eq [char]39) -and $argument[-1] -eq $argument[0]){
                $argument=$argument.Substring(1,$argument.Length-2)
            }
            if($argument -cnotmatch '\A[A-Za-z0-9+/]*={0,2}\z'){throw 'ORPHAN_CENSUS_UNREADABLE'}
            try{
                [byte[]]$bytes=[Convert]::FromBase64String($argument)
                $decoded=$encodings[1].GetString($bytes)
            }catch{throw 'ORPHAN_CENSUS_UNREADABLE'}
            if($decoded -and $seen.Add($decoded)){$texts.Add($decoded)}
        }
        foreach($literal in [regex]::Matches($texts[$index],'[''"]([A-Za-z0-9+/]+={0,2})[''"]')){
            try{[byte[]]$bytes=[Convert]::FromBase64String($literal.Groups[1].Value)}catch{continue}
            foreach($encoding in $encodings){
                try{$decoded=$encoding.GetString($bytes)}catch{continue}
                if($decoded -and $seen.Add($decoded)){$texts.Add($decoded)}
            }
        }
    }
    return [string]::Join(' ',$texts.ToArray())
}

function Get-LabelOrphanCensus($Owner,$Audit,[string]$AuditPath) {
    $needles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($value in @($install,(Split-Path -Parent $install),$source,(Split-Path -Parent $AuditPath),$Owner.attempt_id,$Owner.replacement_transaction_id)){
        if($value){[void]$needles.Add([string]$value)}
    }
    $pending=[Collections.Generic.Queue[object]]::new();$pending.Enqueue($Audit)
    $children=@()
    while($pending.Count){
        $value=$pending.Dequeue()
        if($null -eq $value -or $value -is [string] -or $value -is [ValueType]){continue}
        if($value -is [Array]){foreach($element in $value){if($null -ne $element){$pending.Enqueue($element)}};continue}
        foreach($property in $value.PSObject.Properties){
            if($property.Value -is [string] -and $property.Name -match '(?i)(source|staging|helper|guardian).*(root|path)$' -and [IO.Path]::IsPathRooted($property.Value)){
                [void]$needles.Add($property.Value)
            }elseif($null -ne $property.Value -and $property.Value -isnot [string] -and $property.Value -isnot [ValueType]){$pending.Enqueue($property.Value)}
        }
        foreach($prefix in @('child','helper')){
            $childId=Get-LabelOrphanValue $value ($prefix+'_process_id')
            $childBirth=Get-LabelOrphanValue $value ($prefix+'_process_started_at_filetime')
            if($null -ne $childId -or $null -ne $childBirth){
                if($childId -notmatch '^[1-9][0-9]*$' -or $childBirth -notmatch '^[1-9][0-9]*$'){throw 'ORPHAN_CHILD_IDENTITY_UNREADABLE'}
                $children+=@{id=[long]$childId;birth=[long]$childBirth}
            }
        }
    }
    # Placement result files retain the child's native identity after a dead
    # guardian. Do not execute a guardian or decode any record as commands.
    $auditRoot=Split-Path -Parent $AuditPath
    $resultLocations=@(@{root=$auditRoot;prefix=('canonical-portable-'+$Owner.run_id)})
    $elevation=[string](Get-LabelOrphanValue $Audit 'elevation_log_path')
    if($elevation){
        $elevation=Full $elevation 'orphan elevation evidence'
        $resultLocations+=@{root=(Split-Path -Parent $elevation);prefix=([IO.Path]::GetFileName($elevation))}
    }
    $resultFiles=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach($location in $resultLocations){
        foreach($file in @(Get-ChildItem -LiteralPath $location.root -File -Filter ($location.prefix+'*') -ErrorAction Stop)){
            if($file.Name -match '-guardian-[0-9a-f]{32}\.[0-9]+\.json$'){[void]$resultFiles.Add($file.FullName)}
        }
    }
    foreach($file in $resultFiles){
        $result=Read-LabelOrphanJson $file
        if((Get-LabelOrphanValue $result 'schema') -cne 'label-placement-session-result-v1' -or
            (Get-LabelOrphanValue $result 'transaction_id') -cne $Owner.replacement_transaction_id){throw 'ORPHAN_CHILD_RESULT_DIFFERS'}
        $childId=Get-LabelOrphanValue $result 'child_process_id'
        $childBirth=Get-LabelOrphanValue $result 'child_process_started_at_filetime'
        if($childId -notmatch '^[1-9][0-9]*$' -or $childBirth -notmatch '^[1-9][0-9]*$'){throw 'ORPHAN_CHILD_IDENTITY_UNREADABLE'}
        $children+=@{id=[long]$childId;birth=[long]$childBirth}
    }
    foreach($child in $children){
        if($child.id -gt [uint32]::MaxValue -or -not [LabelOrphanNative]::Exited([uint32]$child.id,[uint64]$child.birth)){throw 'ORPHAN_CHILD_NOT_DEAD'}
    }
    $rows=@(Get-LabelOrphanProcessRows)
    $related=[Collections.Generic.HashSet[long]]::new()
    $births=@{}
    foreach($row in $rows){
        $processId=[long]$row.ProcessId
        $imageName=[string]$row.Name
        $possible=$imageName -match '^(?i:powershell|pwsh|pythonw?|Label_Match|.*relay.*|.*bootstrap.*)(?:\.exe)?$'
        $image=[string]$row.ExecutablePath;$command=[string]$row.CommandLine
        $created=0L
        try {if($null -ne $row.CreationDate){$created=([DateTime]$row.CreationDate).ToUniversalTime().ToFileTimeUtc()}}catch{}
        if($processId -eq $PID){
            if($created -le 0 -or [LabelOrphanNative]::Created([uint32]$processId) -ne [uint64][Diagnostics.Process]::GetCurrentProcess().StartTime.ToUniversalTime().ToFileTimeUtc()){throw 'ORPHAN_CENSUS_SELF_UNREADABLE'}
            continue
        }
        if($processId -le 0){
            if($possible -or $image -or $command){throw 'ORPHAN_CENSUS_UNREADABLE'}
            continue
        }
        if($possible -and (-not $image -or -not $command -or $created -le 0)){throw 'ORPHAN_CENSUS_UNREADABLE'}
        $command=Expand-LabelOrphanCommand $command
        $births[$processId]=$created
        foreach($needle in $needles){
            if($image.IndexOf($needle,[StringComparison]::OrdinalIgnoreCase) -ge 0 -or $command.IndexOf($needle,[StringComparison]::OrdinalIgnoreCase) -ge 0){[void]$related.Add($processId);break}
        }
        if($processId -eq [long]$Owner.owner_process_id){
            if([LabelOrphanNative]::Created([uint32]$processId) -ne [uint64]$Owner.owner_process_started_at_filetime){throw 'ORPHAN_OWNER_PID_REUSED'}
            [void]$related.Add($processId)
        }
        foreach($child in $children){
            if($processId -eq $child.id){
                if([LabelOrphanNative]::Created([uint32]$processId) -ne [uint64]$child.birth){throw 'ORPHAN_CHILD_PID_REUSED'}
                [void]$related.Add($processId)
            }
        }
        if([long]$row.ParentProcessId -eq [long]$Owner.owner_process_id -and
            ($created -le 0 -or $created -ge [long]$Owner.owner_process_started_at_filetime)){[void]$related.Add($processId)}
        foreach($child in $children){
            if([long]$row.ParentProcessId -eq $child.id -and ($created -le 0 -or $created -ge $child.birth)){[void]$related.Add($processId)}
        }
    }
    do {
        $changed=$false
        foreach($row in $rows){
            $id=[long]$row.ProcessId;$parent=[long]$row.ParentProcessId
            if($id -ne $PID -and $related.Contains($parent) -and $births.ContainsKey($parent) -and $births.ContainsKey($id) -and
                ($births[$id] -le 0 -or $births[$parent] -le 0 -or $births[$id] -ge $births[$parent])){
                if($related.Add($id)){$changed=$true}
            }
        }
    }while($changed)
    if($related.Count){throw 'ORPHAN_CENSUS_RELATED_ALIVE'}
    return [ordered]@{method='CIM Win32_Process/native FILETIME';related_alive=0;unreadable_related=0}
}

function Get-LabelOrphanCode($Audit) {
    $transition=Get-LabelOrphanValue $Audit 'writer_transition'
    $candidate=[string](Get-LabelOrphanValue $transition 'candidate_portable_inventory_sha256')
    $installed=[string](Get-LabelOrphanValue $transition 'installed_portable_inventory_sha256')
    foreach($hash in @($candidate,$installed)){if($hash -and $hash -cnotmatch '^[0-9a-f]{64}$'){throw 'ORPHAN_INVENTORY_PIN_INVALID'}}
    $preimage=[string](Get-LabelOrphanValue $Audit 'code_preimage')
    if(($preimage -ceq 'PRESENT' -and -not $installed) -or ($preimage -ceq 'ABSENT' -and $installed)){throw 'ORPHAN_PREIMAGE_DIFFERS'}
    $values=Get-LabelOrphanValue (Get-LabelOrphanValue $Audit 'recovery_context') 'values'
    foreach($pair in @(@('installedPreimageInventory',$installed),@('receiptSource',$candidate))){
        $known=[string](Get-LabelOrphanValue (Get-LabelOrphanValue $values $pair[0]) 'sha256')
        if($known -and $known -cne $pair[1]){throw 'ORPHAN_PREIMAGE_DIFFERS'}
    }
    $state=[string](Get-LabelOrphanValue $Audit 'code_state')
    if($state -cnotin @('','UNKNOWN','PRESENT','ABSENT')){throw 'ORPHAN_CODE_STATE_INVALID'}
    $rollback=Get-LabelOrphanValue $Audit 'rollback'
    $applied=Get-LabelOrphanValue $rollback 'applied'
    if($null -ne $applied -and $applied -isnot [bool]){throw 'ORPHAN_ROLLBACK_STATE_INVALID'}
    $inventory='';$class='ABSENT'
    if(Test-Path -LiteralPath $install){
        $directories=[Collections.Generic.Stack[string]]::new();$directories.Push($install)
        while($directories.Count){
            $directory=$directories.Pop()
            $entry=Get-Item -LiteralPath $directory -Force -ErrorAction Stop
            if(-not $entry.PSIsContainer -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'ORPHAN_CODE_REPARSE'}
            foreach($entry in @(Get-ChildItem -LiteralPath $directory -Force -ErrorAction Stop)){
                if($entry.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'ORPHAN_CODE_REPARSE'}
                if($entry.PSIsContainer){$directories.Push($entry.FullName)}
            }
        }
        $inventory=[string](PortableInventory $install).sha256
        $classes=@()
        if($candidate -and $candidate -ceq $inventory -and -not($applied -eq $true -and (Get-LabelOrphanValue $rollback 'code_restored') -eq $true)){$classes+='CANDIDATE'}
        if($installed -and $installed -ceq $inventory -and -not($state -ceq 'PRESENT' -and $applied -eq $false)){$classes+='INSTALLED'}
        if($classes.Count -ne 1){throw 'ORPHAN_CURRENT_INVENTORY_DIFFERS'}
        $class=[string]$classes[0]
        if($state -ceq 'ABSENT'){throw 'ORPHAN_CODE_STATE_DIFFERS'}
        if($class -ceq 'CANDIDATE' -and $applied -eq $true -and (Get-LabelOrphanValue $rollback 'code_restored') -eq $true){throw 'ORPHAN_RESTORED_CODE_DIFFERS'}
        if($class -ceq 'INSTALLED' -and $state -ceq 'PRESENT' -and $applied -eq $false){throw 'ORPHAN_RETAINED_CODE_DIFFERS'}
    }elseif($preimage -cne 'ABSENT' -or $state -ceq 'PRESENT'){throw 'ORPHAN_CODE_ABSENCE_DIFFERS'}
    return [ordered]@{class=$class;inventory_sha256=$inventory}
}

function Get-LabelOrphanFile([string]$Path) {
    try {
        $path=Full $Path 'orphan observation path'
        for($part=$path;$part;$part=[IO.Path]::GetDirectoryName($part)){
            if((Test-Path -LiteralPath $part) -and ([IO.File]::GetAttributes($part) -band [IO.FileAttributes]::ReparsePoint)){throw 'ORPHAN_ARTIFACT_REPARSE'}
        }
        if(-not(Test-Path -LiteralPath $path)){return [ordered]@{path=$path;exists=$false;kind='ABSENT';sha256=''}}
        $item=Get-Item -LiteralPath $path -Force -ErrorAction Stop
        if($item.PSIsContainer){return [ordered]@{path=$path;exists=$true;kind='DIRECTORY';sha256=''}}
        return [ordered]@{path=$path;exists=$true;kind='FILE';sha256=(Sha $path)}
    }catch{return [ordered]@{path=$Path;exists=$null;kind='UNREADABLE';sha256='';failure_type=$_.Exception.GetType().Name}}
}

function Assert-LabelOrphanFileSnapshot($Actual,$Expected) {
    $exists=Get-LabelOrphanValue $Expected 'exists'
    if($null -ne $exists -and ($exists -isnot [bool] -or $exists -ne $Actual.exists)){throw 'ORPHAN_ARTIFACT_DIFFERS'}
    $hash=[string](Get-LabelOrphanValue $Expected 'sha256')
    if($hash -and ($Actual.kind -cne 'FILE' -or $Actual.sha256 -cne $hash)){throw 'ORPHAN_ARTIFACT_DIFFERS'}
}

function Get-LabelOrphanArtifacts($Audit,[string]$CodeClass) {
    $expected=Get-LabelOrphanValue $Audit $(if($CodeClass -ceq 'CANDIDATE'){'after'}else{'preimage'})
    $knownRun=@('exists','kind','data'|Where-Object {$null -ne (Get-LabelOrphanValue $expected $_)})
    try {
        $run=Snapshot
        foreach($name in $knownRun){
            if((Get-LabelOrphanValue $expected $name) -cne (Get-LabelOrphanValue $run $name)){throw 'ORPHAN_RUN_DIFFERS'}
        }
        $runState=[ordered]@{exists=$run.exists;kind=$run.kind;data_sha256=(ByteSha ([Text.Encoding]::UTF8.GetBytes([string]$run.data)))}
    }catch{
        if($knownRun.Count){throw 'ORPHAN_RUN_DIFFERS'}
        $runState=[ordered]@{exists=$null;kind='UNREADABLE';failure_type=$_.Exception.GetType().Name}
    }
    $observations=[ordered]@{run=$runState}
    $stopPath=[string](Get-LabelOrphanValue $Audit 'stop_marker_path')
    if(-not $stopPath){$stopPath=$stop}
    $observations.stop=Get-LabelOrphanFile $stopPath
    $stopAbsent=Get-LabelOrphanValue $Audit 'stop_marker_absent'
    if($null -ne $stopAbsent -and ($stopAbsent -isnot [bool] -or $null -eq $observations.stop.exists -or $stopAbsent -ne (-not $observations.stop.exists))){throw 'ORPHAN_STOP_DIFFERS'}
    if($CodeClass -cne 'CANDIDATE'){Assert-LabelOrphanFileSnapshot $observations.stop (Get-LabelOrphanValue $Audit 'stop_marker_preimage')}
    $expectedTask=if($CodeClass -cne 'CANDIDATE'){Get-LabelOrphanValue $Audit 'scheduled_task_preimage'}else{$null}
    $knownTask=@('exists','enabled','xml_sha256'|Where-Object {$null -ne (Get-LabelOrphanValue $expectedTask $_)})
    try {
        $task=Get-LabelCurrentUserScheduledTasks
        $taskState=[ordered]@{exists=($null -ne $task);enabled=$false;xml_sha256=''}
        if($null -ne $task){$taskState.enabled=[bool]$task.Settings.Enabled;$taskState.xml_sha256=ByteSha ([Text.Encoding]::UTF8.GetBytes([string](Export-ScheduledTask -TaskName $CanonicalTaskName -TaskPath '\' -ErrorAction Stop)))}
        foreach($name in $knownTask){if((Get-LabelOrphanValue $expectedTask $name) -cne $taskState[$name]){throw 'ORPHAN_TASK_DIFFERS'}}
    }catch{
        if($knownTask.Count){throw 'ORPHAN_TASK_DIFFERS'}
        $taskState=[ordered]@{exists=$null;failure_type=$_.Exception.GetType().Name}
    }
    $observations.task=$taskState
    $pendingPath=Join-Path (Split-Path -Parent $install) 'update-control/worker-pending.json'
    $observations.worker_pending=Get-LabelOrphanFile $pendingPath
    $pending=Get-LabelOrphanValue $Audit 'worker_pending'
    if($null -ne $pending){
        $knownPath=[string](Get-LabelOrphanValue $pending 'path')
        if($observations.worker_pending.kind -cne 'FILE' -or ($knownPath -and -not(Same $knownPath $pendingPath))){throw 'ORPHAN_PENDING_DIFFERS'}
        $currentPending=Read-LabelOrphanJson $pendingPath
        foreach($name in @('install_id','inventory_sha256')){
            $known=Get-LabelOrphanValue $pending $name
            if($null -ne $known -and $known -cne (Get-LabelOrphanValue $currentPending $name)){throw 'ORPHAN_PENDING_DIFFERS'}
        }
    }
    $observations.shortcuts=@()
    $shortcut=Get-LabelOrphanValue $Audit 'machine_shortcut'
    $published=Get-LabelOrphanValue (Get-LabelOrphanValue $Audit 'shortcuts') 'published'
    foreach($entry in @($shortcut)+@($published)){
        if($null -eq $entry){continue}
        $path=[string](Get-LabelOrphanValue $entry 'path')
        if(-not $path){continue}
        $actual=Get-LabelOrphanFile $path
        if($actual.kind -cne 'FILE'){throw 'ORPHAN_SHORTCUT_DIFFERS'}
        $hash=[string](Get-LabelOrphanValue $entry 'sha256')
        if($hash -and $hash -cne $actual.sha256){throw 'ORPHAN_SHORTCUT_DIFFERS'}
        $observations.shortcuts+=,$actual
    }
    return $observations
}

function Save-LabelOrphanRelease([string]$Path,$Record) {
    for($part=(Split-Path -Parent $Path);$part;$part=[IO.Path]::GetDirectoryName($part)){
        if([IO.File]::GetAttributes($part) -band [IO.FileAttributes]::ReparsePoint){throw 'ORPHAN_RELEASE_REPARSE'}
    }
    $temporary=$Path+'.tmp.'+[Guid]::NewGuid().ToString('N')
    $stream=$null
    try {
        $stream=[IO.File]::Open($temporary,'CreateNew','Write','None')
        [byte[]]$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($Record|ConvertTo-Json -Depth 20)+[Environment]::NewLine)
        $stream.Write($bytes,0,$bytes.Length);$stream.Flush($true);$stream.Dispose();$stream=$null
        if(Test-Path -LiteralPath $Path){[void](Read-LabelOrphanJson $Path);Invoke-LabelPinnedAtomicReplace $temporary $Path -Mode Replace}
        else{Invoke-LabelPinnedAtomicReplace $temporary $Path -Mode Move}
        if((Sha $Path) -cne (ByteSha $bytes)){throw 'ORPHAN_RELEASE_READBACK_DIFFERS'}
    }finally{if($null -ne $stream){$stream.Dispose()};if(Test-Path -LiteralPath $temporary){Remove-Item -LiteralPath $temporary -ErrorAction Stop}}
}

function Get-LabelOrphanMachineAuditRoot {
    # Same fixed rule as the machine installer that writes its original audit there.
    $programData = if ($testMode) { $env:PROGRAMDATA } else { [Environment]::GetFolderPath('CommonApplicationData') }
    return Join-Path (Full $programData 'machine ProgramData') 'KMTech\Label_Match\install-audit'
}

function Test-LabelOrphanReleaseCandidate($Saved,[string]$AuditPath) {
    if(Test-Path -LiteralPath (Join-Path $writerFenceControlRoot 'active.json')){return $true}
    $run=[string](Get-LabelOrphanValue $Saved 'run_id')
    if($run -cmatch '^[0-9]{8}T[0-9]{9}Z-[0-9a-f]{32}$'){
        $machine=Join-Path (Get-LabelOrphanMachineAuditRoot) ('machine-writer-'+$run+'\active.json')
        if(Test-Path -LiteralPath $machine){return $true}
    }
    $attempt=[string](Get-LabelOrphanValue (Get-LabelOrphanValue $Saved 'writer_fence') 'attempt_id')
    if($attempt -cmatch '^[0-9a-f]{32}$' -and
        (Test-Path -LiteralPath (Join-Path (Split-Path -Parent $AuditPath) ('orphan-fence-release-'+$attempt+'.json')))){return $true}
    return $false
}

function Assert-LabelOrphanReleaseFormat($Record) {
    $strings=@('schema','attempt_id','session_id','replacement_transaction_id','audit_path','audit_sha256','audit_status',
        'observed_code_class','observed_inventory_sha256','owner_created_at','owner_dead_proven_at_utc','fence_tuple_sha256','entry','state','released_at_utc')
    foreach($name in $strings){if((Get-LabelOrphanValue $Record $name) -isnot [string]){throw 'ORPHAN_RELEASE_RECORD_INVALID'}}
    $pidValue=Get-LabelOrphanValue $Record 'owner_pid'
    if(($pidValue -isnot [int] -and $pidValue -isnot [long]) -or $pidValue -le 0){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
    $census=Get-LabelOrphanValue $Record 'census'
    if((Get-LabelOrphanValue $census 'method') -isnot [string] -or [string]::IsNullOrWhiteSpace($census.method)){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
    foreach($name in @('related_alive','unreadable_related')){
        $count=Get-LabelOrphanValue $census $name
        if(($count -isnot [int] -and $count -isnot [long]) -or $count -ne 0){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
    }
    $hash=Get-LabelOrphanValue $Record 'observed_fence_sha256'
    if($null -ne $hash -and ($hash -isnot [string] -or $hash -cnotmatch '^[0-9a-f]{64}$')){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
    $observations=Get-LabelOrphanValue $Record 'observations'
    if($null -ne $observations -and $observations -isnot [Collections.IDictionary] -and $observations -isnot [pscustomobject]){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
}

function Invoke-LabelOrphanFenceRelease($Saved,[string]$AuditPath,[string]$AuditSha256) {
    # Only the two fixed original audit roots (operator LocalAppData, machine ProgramData) are evidence.
    $auditParent=Split-Path -Parent $AuditPath
    if(-not(Same $auditParent (Join-Path $lad 'KMTech\Label_Match\install-audit')) -and -not(Same $auditParent (Get-LabelOrphanMachineAuditRoot))){throw 'ORPHAN_AUDIT_ROOT_DIFFERS'}
    $ownerTuple=Get-LabelOrphanTuple (Get-LabelOrphanValue $Saved 'writer_fence')
    $run=[string](Get-LabelOrphanValue $Saved 'run_id')
    if($run -cnotmatch '^[0-9]{8}T[0-9]{9}Z-[0-9a-f]{32}$' -or
        [IO.Path]::GetFileName($AuditPath) -cne ('canonical-portable-'+$run+'.json')){throw 'ORPHAN_AUDIT_IDENTITY'}
    $ownerPath=Join-Path (Split-Path -Parent $install) ('.installer-owner-'+$ownerTuple.session_id+'-'+($run -split '-')[-1]+'.json')
    Assert-LabelOrphanProtectedPath $ownerPath
    $ownerHandle=[IO.File]::Open($ownerPath,'Open','Read','Read')
    $authority=$null;$admission=$null
    $oldProduction=$Script:LabelWriterFenceAdmissionProductionRoot
    $oldIdentity=$Script:LabelWriterFenceInstalledIdentity
    try {
        $owner=Read-LabelOrphanJson $ownerPath
        $tupleJson=$ownerTuple|ConvertTo-Json -Compress
        if($owner.schema -cne 'label-match-installer-owner-v1' -or $owner.run_id -cne $run -or
            -not(Same $owner.install_root $install) -or ((Get-LabelOrphanTuple $owner)|ConvertTo-Json -Compress) -cne $tupleJson){throw 'ORPHAN_OWNER_BINDING_DIFFERS'}
        foreach($name in @('owner_process_id','owner_process_started_at_filetime')){
            if((Get-LabelOrphanValue $Saved.writer_fence $name) -cne (Get-LabelOrphanValue $owner $name)){throw 'ORPHAN_OWNER_IDENTITY_DIFFERS'}
        }
        $control=Full ([string]$owner.control_root) 'orphan fence root'
        $machine=Join-Path (Get-LabelOrphanMachineAuditRoot) ('machine-writer-'+$run)
        if(-not(Same $control $writerFenceControlRoot) -and -not(Same $control $machine)){throw 'ORPHAN_CONTROL_ROOT_DIFFERS'}
        # Each original audit root admits only its own control root, including testMode.
        $expectedControl=if(Same $auditParent (Get-LabelOrphanMachineAuditRoot)){$machine}else{$writerFenceControlRoot}
        if(-not(Same $control $expectedControl)){throw 'ORPHAN_AUDIT_ROOT_DIFFERS'}
        $Script:LabelWriterFenceAdmissionProductionRoot=$control
        $Script:LabelWriterFenceInstalledIdentity=[pscustomobject]@{session_id=$ownerTuple.session_id;attempt_id=$ownerTuple.attempt_id;
            replacement_transaction_id=$ownerTuple.replacement_transaction_id;orchestrator_sha256=$ownerTuple.orchestrator_sha256;
            writer_contract_sha256=$ownerTuple.writer_contract_sha256;inventory_sha256=$ownerTuple.writer_inventory_sha256}
        $authority=Enter-LabelWriterSessionAuthority $ownerTuple.session_id $ownerTuple.attempt_id $ownerTuple.orchestrator_sha256 $ownerTuple.replacement_transaction_id $ownerTuple.writer_contract_sha256
        foreach($candidateOwner in @(Get-ChildItem -LiteralPath (Split-Path -Parent $ownerPath) -File -Filter ('.installer-owner-'+$ownerTuple.session_id+'-*.json') -ErrorAction Stop)){
            if(Same $candidateOwner.FullName $ownerPath){continue}
            Assert-LabelOrphanProtectedPath $candidateOwner.FullName
            $otherOwner=Read-LabelOrphanJson $candidateOwner.FullName
            if(((Get-LabelOrphanTuple $otherOwner)|ConvertTo-Json -Compress) -ceq $tupleJson){throw 'ORPHAN_OWNER_AMBIGUOUS'}
        }
        $active=Read-LabelWriterFence $control -AllowAbsent
        $path=Join-Path $control 'active.json'
        if((Same $control $machine) -and $null -ne $active){Assert-LabelOrphanProtectedPath $path $control}
        $releasePath=Join-Path (Split-Path -Parent $AuditPath) ('orphan-fence-release-'+$ownerTuple.attempt_id+'.json')
        $tupleHash=ByteSha ([Text.Encoding]::UTF8.GetBytes($tupleJson))
        $release=$null
        if(Test-Path -LiteralPath $releasePath){
            $release=Read-LabelOrphanJson $releasePath
            Assert-LabelOrphanReleaseFormat $release
            if($release.schema -cne 'label-orphan-fence-release-v1' -or $release.attempt_id -cne $ownerTuple.attempt_id -or
                $release.session_id -cne $ownerTuple.session_id -or $release.replacement_transaction_id -cne $ownerTuple.replacement_transaction_id -or
                $release.audit_sha256 -cne $AuditSha256 -or $release.audit_status -cne $Saved.status -or -not(Same $release.audit_path $AuditPath) -or
                $release.fence_tuple_sha256 -cne $tupleHash -or $release.entry -cne '-ResumeRollbackAuditPath' -or
                $release.state -cnotin @('RELEASING','RELEASED')){throw 'ORPHAN_RELEASE_BINDING_DIFFERS'}
            if($release.owner_pid -ne $owner.owner_process_id -or $release.owner_created_at -cne [string]$owner.owner_process_started_at_filetime -or
                $release.observed_code_class -cnotin @('CANDIDATE','INSTALLED','ABSENT') -or
                ($release.observed_code_class -cne 'ABSENT' -and $release.observed_inventory_sha256 -cnotmatch '^[0-9a-f]{64}$') -or
                ($release.observed_code_class -ceq 'ABSENT' -and $release.observed_inventory_sha256 -cne '') -or
                [string]::IsNullOrWhiteSpace($release.owner_dead_proven_at_utc) -or
                [string]::IsNullOrWhiteSpace($release.census.method) -or $release.census.related_alive -ne 0 -or $release.census.unreadable_related -ne 0){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
            [void][DateTimeOffset]::Parse([string]$release.owner_dead_proven_at_utc,[Globalization.CultureInfo]::InvariantCulture)
            if($release.state -ceq 'RELEASED'){
                if($null -ne $active){throw 'ORPHAN_RELEASE_FENCE_RETURNED'}
                if([string]::IsNullOrWhiteSpace($release.released_at_utc)){throw 'ORPHAN_RELEASE_RECORD_INVALID'}
                [void][DateTimeOffset]::Parse([string]$release.released_at_utc,[Globalization.CultureInfo]::InvariantCulture)
                return
            }
        }
        if($null -eq $active -and $null -eq $release){throw 'ORPHAN_SELF_FENCE_ABSENT'}
        $original=''
        if($null -ne $active){
            if((Get-LabelOrphanTuple $active|ConvertTo-Json -Compress) -cne $tupleJson){throw 'ORPHAN_FENCE_BINDING_DIFFERS'}
            $original=Sha $path
            if($null -ne $release -and $null -ne (Get-LabelOrphanValue $release 'observed_fence_sha256') -and $release.observed_fence_sha256 -cne $original){throw 'ORPHAN_RELEASING_FENCE_DIFFERS'}
        }
        Initialize-LabelOrphanNative
        $ownerId=Get-LabelOrphanValue $owner 'owner_process_id';$birth=[string](Get-LabelOrphanValue $owner 'owner_process_started_at_filetime')
        if(($ownerId -isnot [int] -and $ownerId -isnot [long]) -or $ownerId -le 0 -or $ownerId -gt [uint32]::MaxValue -or
            $birth -cnotmatch '^[1-9][0-9]{0,18}$' -or -not [LabelOrphanNative]::Exited([uint32]$ownerId,[uint64]$birth)){throw 'ORPHAN_OWNER_NOT_DEAD'}
        $census=Get-LabelOrphanCensus $owner $Saved $AuditPath
        $code=Get-LabelOrphanCode $Saved
        $artifacts=Get-LabelOrphanArtifacts $Saved $code.class
        if($null -eq $release){
            $release=[ordered]@{schema='label-orphan-fence-release-v1';attempt_id=$ownerTuple.attempt_id;session_id=$ownerTuple.session_id;
                replacement_transaction_id=$ownerTuple.replacement_transaction_id;audit_path=$AuditPath;audit_sha256=$AuditSha256;audit_status=$Saved.status;
                observed_code_class=$code.class;observed_inventory_sha256=$code.inventory_sha256;owner_pid=$ownerId;owner_created_at=$birth;
                owner_dead_proven_at_utc=[DateTime]::UtcNow.ToString('o');census=$census;fence_tuple_sha256=$tupleHash;
                observed_fence_sha256=$original;entry='-ResumeRollbackAuditPath';state='RELEASING';released_at_utc='';observations=$artifacts}
            # K11: census, inventory and artifact observation stay outside writer admission.
            $admission=Enter-LabelWriterAdmission $control
            try {
                if((Sha $AuditPath) -cne $AuditSha256 -or
                    (Sha $path) -cne $original -or (Get-LabelOrphanTuple (Read-LabelWriterFence $control)|ConvertTo-Json -Compress) -cne $tupleJson){throw 'ORPHAN_RELEASE_PROOF_CHANGED'}
                Save-LabelOrphanRelease $releasePath $release
            }finally{Exit-LabelWriterAdmission $admission;$admission=$null}
        }else{
            if($release.observed_code_class -cne $code.class -or $release.observed_inventory_sha256 -cne $code.inventory_sha256 -or
                $release.owner_pid -ne $ownerId -or $release.owner_created_at -cne $birth){throw 'ORPHAN_RELEASING_RESULT_DIFFERS'}
        }
        [void](Get-LabelOrphanCensus $owner $Saved $AuditPath)
        $current=Get-LabelOrphanCode $Saved
        if($current.class -cne $code.class -or $current.inventory_sha256 -cne $code.inventory_sha256 -or
            (Sha $AuditPath) -cne $AuditSha256){throw 'ORPHAN_RELEASE_PROOF_CHANGED'}
        $artifacts=Get-LabelOrphanArtifacts $Saved $code.class
        if($release -is [Collections.IDictionary]){$release.observations=$artifacts}
        else{$release|Add-Member -NotePropertyName observations -NotePropertyValue $artifacts -Force}
        $admission=Enter-LabelWriterAdmission $control
        if((Sha $AuditPath) -cne $AuditSha256){throw 'ORPHAN_RELEASE_PROOF_CHANGED'}
        if($null -ne $active){
            if((Sha $path) -cne $original -or (Get-LabelOrphanTuple (Read-LabelWriterFence $control)|ConvertTo-Json -Compress) -cne $tupleJson){throw 'ORPHAN_FENCE_CHANGED'}
            Remove-Item -LiteralPath $path -ErrorAction Stop
        }
        if(Test-Path -LiteralPath $path){throw 'ORPHAN_FENCE_ABSENCE_UNPROVEN'}
        if($release -is [Collections.IDictionary]){$release.state='RELEASED';$release.released_at_utc=[DateTime]::UtcNow.ToString('o')}
        else{$release.state='RELEASED';$release.released_at_utc=[DateTime]::UtcNow.ToString('o')}
        Save-LabelOrphanRelease $releasePath $release
    }finally{
        try{if($null -ne $admission){Exit-LabelWriterAdmission $admission}}
        finally{
            try{if($null -ne $authority){Exit-LabelWriterSessionAuthority $authority}}
            finally{
                $Script:LabelWriterFenceAdmissionProductionRoot=$oldProduction
                $Script:LabelWriterFenceInstalledIdentity=$oldIdentity
                $ownerHandle.Dispose()
            }
        }
    }
}

function Invoke-LabelResumeRollback {
    if ($PlanOnly -or [string]::IsNullOrWhiteSpace($ExpectedRollbackAuditSha256)) { throw 'Supported rollback resume requires the exact audit SHA256.' }
    if (-not $testMode -and -not ([Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw '지원 복구는 같은 작업 사용자의 관리자 PowerShell에서 실행하세요.'
    }
    $localAuditRoot = Join-Path $lad 'KMTech\Label_Match\install-audit'
    $auditPath = Full $ResumeRollbackAuditPath 'rollback audit'
    # A machine install keeps its only original audit under the fixed machine ProgramData audit root.
    # That root is accepted below only as evidence for the terminal-audit fence exit; no other root is.
    $machineAudit = $false
    if (-not (Same (Split-Path -Parent $auditPath) $localAuditRoot)) {
        if (-not (Same (Split-Path -Parent $auditPath) (Get-LabelOrphanMachineAuditRoot))) { throw 'Rollback audit is outside the original operator audit root.' }
        $machineAudit = $true
    }
    $item = Get-Item -Force -LiteralPath $auditPath
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $item.Length -gt 1048576 -or
        $ExpectedRollbackAuditSha256 -cnotmatch '^[0-9a-f]{64}$' -or (Sha $auditPath) -cne $ExpectedRollbackAuditSha256) { throw 'Rollback audit pin/ordinary-file check failed.' }
    $resumeJsonOptions = @{}
    if ((Get-Command ConvertFrom-Json).Parameters.ContainsKey('DateKind')) { $resumeJsonOptions.DateKind = 'String' }
    $saved = Get-Content -LiteralPath $auditPath -Raw -Encoding UTF8 | ConvertFrom-Json @resumeJsonOptions
    # Terminal evidence has a separate, administrator-only fence exit. A
    # failure without a residual fence retains the existing rollback-resume path.
    if ([string]$saved.schema -ceq 'label-match-canonical-portable-install-v1' -and
        [string]$saved.status -cin @('RECOVERY_REQUIRED','ROLLBACK_FAILED','FAILED_ROLLBACK_INCOMPLETE') -and
        (Test-LabelOrphanReleaseCandidate $saved $auditPath)) {
        if (-not (Same ([string]$saved.install_root) $install)) { throw 'ORPHAN_INSTALL_ROOT_DIFFERS' }
        $releaseReceipt = ReceiptSource $source $sourceManifest
        $releaseHelper = Join-Path $source 'tools/label_writer_fence.ps1'
        [byte[]]$releaseHelperBytes = PinnedFileBytes $releaseHelper ([string]$releaseReceipt.critical_file_sha256.writer_fence_helper)
        . ([scriptblock]::Create(([Text.Encoding]::UTF8.GetString($releaseHelperBytes)).TrimStart([char]0xFEFF)))
        $saved = Read-LabelOrphanJson $auditPath
        Invoke-LabelOrphanFenceRelease $saved $auditPath $ExpectedRollbackAuditSha256
        $Script:LabelOrphanFenceReleased = $true
        return
    }
    if ($machineAudit) { throw 'Rollback audit is outside the original operator audit root.' }
    if ([string]$saved.schema -cne 'label-match-canonical-portable-install-v1' -or
        [string]$saved.status -cnotin @('ROLLBACK_FAILED','FAILED_ROLLBACK_INCOMPLETE','FAILED_ROLLED_BACK','RUNNING','PREIMAGE_SAVED') -or
        -not (Same ([string]$saved.install_root) $install) -or [string]$saved.source_commit -cne [string]$sourceManifest.source_commit) { throw 'Rollback audit identity/status differs.' }
    $context = $saved.recovery_context
    if ($null -eq $context -or [string]$context.operator_sid -cne $generationSubjectSid -or
        [string]$context.orchestrator_sha256 -cne (Sha (Join-Path $source 'INSTALL_CANONICAL_PORTABLE.ps1'))) { throw 'Rollback context belongs to a different user or installer.' }
    $unfinishedRun = [string]$saved.status -cin @('RUNNING','PREIMAGE_SAVED')
    if ($unfinishedRun) { Assert-LabelDeadUnfinishedInstaller $auditPath }
    $audit = [ordered]@{}
    foreach ($property in $saved.PSObject.Properties) { $audit[$property.Name] = $property.Value }
    foreach ($name in @('rollback','writer_fence')) {
        $map = [ordered]@{}
        foreach ($property in $audit[$name].PSObject.Properties) { $map[$property.Name] = $property.Value }
        $audit[$name] = $map
    }
    foreach ($name in @('before','old','taskBefore','stopBefore','healthyRemovalReportBefore',
        'removalReportExisted','existingVerified','installedPreimageInventory','replacementRollbackRoot',
        'writerTransition','legacyFirstRegistration','healthyRemovedInstall','firstRegistrationStateVerified',
        'firstRegistrationStarted','firstRegistrationAttempt','firstRegistrationAttemptPath',
        'firstRegistrationStatePaths','firstRegistrationAbsentAncestors','rollbackSources','restoreSources')) {
        if ($null -eq $context.values.PSObject.Properties[$name]) { throw 'Rollback context input is absent.' }
        Set-Variable -Name $name -Value $context.values.$name
    }
    $old = @($old)
    # The relay readiness step expects the commit of the code the rollback restores.
    # The main flow sets it after this resume would have run, so derive it from the audit.
    $candidate = $sourceManifest
    $savedTransition = $saved.PSObject.Properties['writer_transition']
    if ($existingVerified -and $null -ne $savedTransition -and $null -ne $savedTransition.Value -and
        $null -ne $savedTransition.Value.PSObject.Properties['installed_source_commit'] -and
        [string]$savedTransition.Value.installed_source_commit -cmatch '^[0-9a-f]{40}$') {
        $candidate = [pscustomobject]@{source_commit=[string]$savedTransition.Value.installed_source_commit}
    }
    if ($unfinishedRun) {
        # The code preimage folder is created by placement, after the context was saved.
        $replacementBackupsBefore = if ($null -ne $context.values.PSObject.Properties['replacementBackupsBefore']) { @($context.values.replacementBackupsBefore) } else { @() }
        if ($existingVerified -and [string]::IsNullOrEmpty([string]$replacementRollbackRoot)) {
            $replacementRollbackRoot = ReplacementPreimage $install $installedPreimageInventory $replacementBackupsBefore
        }
        $audit.rollback.resumed_unfinished_run = 'DEAD_INSTALLER_PROVEN'
    }
    $generationMarkerPaths = @(@($generationMarkerPaths) + @($context.generation_marker_paths) | Select-Object -Unique)
    $receiptSource = ReceiptSource $source $sourceManifest
    $runId = [string]$audit.run_id
    $elevationLogPath = [string]$audit.elevation_log_path
    $recoveryRunId = $runId + '-resume-' + [Guid]::NewGuid().ToString('N')
    $frozenPlacement = FreezePlacementHelper $source $localAuditRoot $recoveryRunId $receiptSource.critical_file_sha256 $source
    . ([string]$frozenPlacement.writer_fence_path)
    $writerOrchestratorSha256 = [string]$context.orchestrator_sha256
    $writerContractSha256 = [string]$context.writer_contract_sha256
    if ($writerContractSha256 -cne [string]$frozenPlacement.writer_fence_sha256) { throw 'Recovery writer contract differs.' }
    $writerSessionId = [string]$audit.writer_fence.session_id
    $writerAttemptId = [string]$audit.writer_fence.attempt_id
    $writerTransactionId = [string]$audit.writer_fence.replacement_transaction_id
    $writerStartedAt = [string]$audit.writer_fence.session_started_at_utc
    $writerDelegationToken = [Guid]::NewGuid().ToString('N') + [Guid]::NewGuid().ToString('N')
    $Script:LabelWriterFenceInstalledIdentity = [pscustomobject]@{session_id=$writerSessionId;attempt_id=$writerAttemptId;
        replacement_transaction_id=$writerTransactionId;orchestrator_sha256=$writerOrchestratorSha256;
        writer_contract_sha256=$writerContractSha256;inventory_sha256=[string]$writerTransition.installed_inventory_sha256}
    $writerEnvironmentBefore = @($WriterDelegationEnvironmentNames | ForEach-Object { [Environment]::GetEnvironmentVariable($_, 'Process') })
    $writerAuthority = Enter-LabelWriterSessionAuthority -SessionId $writerSessionId -AttemptId $writerAttemptId `
        -OrchestratorSha256 $writerOrchestratorSha256 -ReplacementTransactionId $writerTransactionId -WriterContractSha256 $writerContractSha256
    try {
        $active = Read-LabelWriterFence $writerFenceControlRoot -AllowAbsent
        $writerFenceStarted = $null -ne $active
        if ($writerFenceStarted -and ([string]$active.session_id -cne $writerSessionId -or [string]$active.attempt_id -cne $writerAttemptId -or
            [string]$active.replacement_transaction_id -cne $writerTransactionId -or [string]$active.orchestrator_sha256 -cne $writerOrchestratorSha256 -or
            [string]$active.writer_contract_sha256 -cne $writerContractSha256)) { throw 'Held fence is not this recorded transaction.' }
        $helperParameters = @{InstallerRunId=$runId;InstallerOwnerProcessId=[int]$PID;
            InstallerOwnerProcessStartedAtFileTime=[Diagnostics.Process]::GetCurrentProcess().StartTime.ToUniversalTime().ToFileTimeUtc().ToString();
            SourceRoot=$source;InstallRoot=$install;ElevationLogPath=$elevationLogPath;
            ExpectedBootstrapScriptSha256=[string]$frozenPlacement.helper_sha256;VerifiedBootstrapScriptPath=[string]$frozenPlacement.helper_path;
            BootstrapIntegrityPreloaded=$true;WriterFenceFunctionsPreloaded=$true;WriterFenceControlRoot=$writerFenceControlRoot;
            DataGenerationSubjectSid=$generationSubjectSid;DataGenerationMarkerPaths=@($generationMarkerPaths);
            WriterFenceSessionId=$writerSessionId;WriterFenceAttemptId=$writerAttemptId;WriterFenceReplacementTransactionId=$writerTransactionId;
            WriterFenceDelegationToken=$writerDelegationToken;AllowNoncanonicalLayoutForTest=[bool]$testMode;ReplaceExistingVerifiedPortable=[bool]$existingVerified;DryRun=$false;
            ExpectedSourceAggregateSha256=[string]$receiptSource.bootstrap_aggregate_sha256;
            ExpectedSourceFileCount=[int]$receiptSource.file_count;ExpectedSourceByteCount=[uint64]$receiptSource.byte_count}
        . Invoke-LabelCanonicalRollback
        $audit.status = 'FAILED_ROLLED_BACK'
        $audit.rollback.supported_resume = 'PROVEN'
    } catch {
        $audit.status = 'ROLLBACK_FAILED'
        $audit.rollback.resume_failure = Get-LabelLaunchFailure $_ 'supported_resume'
        throw
    } finally {
        try {
            Save $auditPath $audit
            if ($EvidencePath) { Save (Full $EvidencePath 'EvidencePath') $audit }
        } finally {
            RestoreWriterDelegationEnvironment $writerEnvironmentBefore
            if ($null -ne $writerAuthority) { Exit-LabelWriterSessionAuthority $writerAuthority }
            $Script:LabelWriterFenceInstalledIdentity = $null
        }
    }
}

function Write-LabelInstallerRelayRecoveryGuidance([switch]$MachineWorker,[bool]$Existing=$true) {
    if ($MachineWorker -and -not $Existing) {
        'worker_setup_guidance=처음 설치: 지정 작업자 계정의 첫 일반 실행에서 준비를 마치세요.'
    } else {
        'relay_recovery_guidance=relay 되살림: 같은 작업자 일반 세션에서 --remove-current-user-setup → --onboard-current-user 순서로 실행하세요.'
    }
}

function Assert-LabelInstallerRelayPreimageSession([object[]]$Expected,[string]$SubjectSid) {
    $live=@(Assert-RollbackRelayPreimage $Expected)
    if($Expected.Count -eq 0){return @()}
    if($Expected.Count -ne 1){throw 'Installer relay preimage count differs.'}
    $caller=Get-CanonicalRelaySecurity $PID
    if([string]$caller.sid -cne $SubjectSid -or [int]$caller.session_id -le 0){throw 'Installer relay caller differs.'}
    $security=Get-CanonicalRelaySecurity ([int]$live[0].ProcessId)
    if($live[0].ProcessId -ne $Expected[0].ProcessId -or
        ([DateTime]$live[0].CreationDate).ToUniversalTime() -ne ([DateTime]$Expected[0].CreationDate).ToUniversalTime() -or
        [string]$security.sid -cne $SubjectSid -or [bool]$security.elevated -or
        [int]$security.integrity_rid -ne 8192 -or [int]$security.session_id -ne [int]$caller.session_id){
        throw 'Installer relay native preimage differs.'
    }
    return @($live)
}

function Test-LabelInstallerRelayChild($Writer,[object[]]$Expected,[string]$CodeRoot,[string]$SubjectSid) {
    # A command-line match alone cannot authorize an unrelated writer.
    try {
        if($Expected.Count -ne 1){return $false}
        $parent=@(Assert-LabelInstallerRelayPreimageSession $Expected $SubjectSid)
        if($parent.Count -ne 1 -or [int]$Writer.ProcessId -le 0 -or
            [int]$Writer.ProcessId -eq [int]$parent[0].ProcessId -or
            [int]$Writer.ParentProcessId -ne [int]$parent[0].ProcessId -or
            $null -eq $Writer.CreationDate -or
            ([DateTime]$Writer.CreationDate).ToUniversalTime() -le ([DateTime]$parent[0].CreationDate).ToUniversalTime()){
            return $false
        }
        $python=Join-Path $CodeRoot 'runtime/python.exe'
        $pythonw=Join-Path $CodeRoot 'runtime/pythonw.exe'
        $frozen=Join-Path $CodeRoot 'Label_Match.exe'
        $executable=[string]$Writer.ExecutablePath
        if((Same ([string]$parent[0].ExecutablePath) $pythonw) -and (Same $executable $python)){
            $prefix='{0} -I -B {1} --label-match-direct-sync-relay ' -f
                (Arg $python),(Arg (Join-Path $CodeRoot 'app/label_match_relay_entry.py'))
        }elseif((Same ([string]$parent[0].ExecutablePath) $frozen) -and (Same $executable $frozen)){
            $prefix='{0} --label-match-direct-sync-relay ' -f (Arg $frozen)
        }else{return $false}
        $command=Normalize-RelayExecutableQuoting ([string]$Writer.CommandLine) $executable
        if(-not $command.StartsWith($prefix,[StringComparison]::Ordinal)){return $false}
        $security=Get-CanonicalRelaySecurity ([int]$Writer.ProcessId)
        $caller=Get-CanonicalRelaySecurity $PID
        if([string]$security.sid -cne $SubjectSid -or [bool]$security.elevated -or
            [int]$security.integrity_rid -ne 8192 -or [int]$security.session_id -le 0 -or
            [int]$security.session_id -ne [int]$caller.session_id){return $false}
        return $true
    }catch{return $false}
}

function Stop-LabelInstallerRelayPreimage([object[]]$Expected,[string]$StateRoot,[string]$CodeRoot,[string]$SubjectSid) {
    [void](Assert-LabelInstallerRelayPreimageSession $Expected $SubjectSid)
    if($Expected.Count -eq 0){return}
    $probe=@'
import json, pathlib, sys
root, state = map(pathlib.Path, sys.argv[1:3])
sys.path[:0] = [str(root / 'app'), str(root / 'app/site-packages')]
from user_relay import RELAY_DIRECT_SYNC_PROCESS_TIMEOUT_SECONDS, request_user_relay_stop
proof = request_user_relay_stop(state, timeout_seconds=RELAY_DIRECT_SYNC_PROCESS_TIMEOUT_SECONDS + 30)
if proof['status'] != 'ABSENT':
    raise RuntimeError('candidate relay did not stop normally')
print(json.dumps(proof, sort_keys=True))
'@
    $bytes=[Text.Encoding]::UTF8.GetBytes($probe.Replace("`r`n","`n"))
    Write-Host '작업 앱이 서버 보내기를 마치기를 기다리는 중'
    $output=Invoke-LabelPinnedProbe -Python (Join-Path $CodeRoot 'runtime/python.exe') -ProbeBytes $bytes `
        -ExpectedSha256 '027301c5dfff852ac414805a9eb67fc361d0b8a0960ebb8e5aa613759b9110f8' `
        -ProbeArguments @($CodeRoot,$StateRoot) -FailureMessage 'Installer normal relay stop failed: '
    $proof=($output -join "`n")|ConvertFrom-Json
    if([string]$proof.status -cne 'ABSENT'){throw 'Installer normal relay stop is unproven.'}
    Wait-LabelRelayPreimageExit $Expected
}

function Stop-LabelRollbackCandidateRelay {
    $audit.rollback.new_relay_stop = $null
    $live = @(Relays)
    if ($live.Count -eq 0) { return }
    if (@($Script:LabelRollbackCandidateRelays).Count -ne 1) { throw 'Candidate relay launch is unproven.' }
    [void](Assert-LabelInstallerRelayPreimageSession @($Script:LabelRollbackCandidateRelays) $generationSubjectSid)
    $probe = @'
import json, pathlib, sys
root, state = map(pathlib.Path, sys.argv[1:3])
sys.path[:0] = [str(root / 'app'), str(root / 'app/site-packages')]
from user_relay import RELAY_DIRECT_SYNC_PROCESS_TIMEOUT_SECONDS, request_user_relay_stop
proof = request_user_relay_stop(state, timeout_seconds=RELAY_DIRECT_SYNC_PROCESS_TIMEOUT_SECONDS + 30)
if proof['status'] != 'ABSENT':
    raise RuntimeError('candidate relay did not stop normally')
print(json.dumps(proof, sort_keys=True))
'@
    $bytes = [Text.Encoding]::UTF8.GetBytes($probe.Replace("`r`n","`n"))
    Write-Host '작업 앱이 서버 보내기를 마치기를 기다리는 중'
    $output = Invoke-LabelPinnedProbe -Python (Join-Path $source 'runtime/python.exe') -ProbeBytes $bytes `
        -ExpectedSha256 '027301c5dfff852ac414805a9eb67fc361d0b8a0960ebb8e5aa613759b9110f8' -ProbeArguments @($source,$defaultDirectSyncRoot) -FailureMessage 'Candidate relay protection failed: '
    $audit.rollback.new_relay_stop = $output | ConvertFrom-Json
    if (@(Relays).Count -ne 0) { throw 'Candidate relay process absence is unproven.' }
}

function Invoke-LabelCanonicalRollback {
        $audit.rollback.relay_readiness = 'UNPROVEN'
        $audit.rollback.runtime_restored = $false
        $Script:LabelRollbackPhaseStack = [Collections.Generic.Stack[string]]::new()
        $Script:LabelRollbackErrors = [Collections.Generic.List[object]]::new()
        $Script:LabelRollbackFailures = [Collections.Generic.List[object]]::new()
        $Script:LabelRollbackSteps = [Collections.Generic.List[object]]::new()
        $rollbackCustodyReady = $false
        $rollbackQuiescent = $false
        $rollbackAuthenticationReady = -not $legacyFirstRegistration
        $rollbackUsesInstalled = $false
        $rollbackGenerationReady = $false
        $rollbackPreimageProven = $false
        $rollbackStartupProven = $false
        $rollbackRuntimeProven = $false
        $rollbackRelayProof=@{ready=$false}
        $rollbackProtectionReady = $false
        . Invoke-LabelRollbackStep 'deployment_custody' {
            if (-not $writerFenceStarted) {
                # Final audit persistence can fail after the success path released
                # its fence. Reacquire the same session before stopping/restoring
                # any runtime or code; all existing phase checks still apply.
                if ($null -eq $writerAuthority) {
                    $writerAuthority = Enter-LabelWriterSessionAuthority `
                        -SessionId $writerSessionId `
                        -AttemptId $writerAttemptId `
                        -OrchestratorSha256 $writerOrchestratorSha256 `
                        -ReplacementTransactionId $writerTransactionId `
                        -WriterContractSha256 $writerContractSha256
                }
                [void](Start-LabelWriterFence `
                    -ControlRoot $writerFenceControlRoot `
                    -Status 'RESTORING' `
                    -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId `
                    -ReplacementTransactionId $writerTransactionId `
                    -SessionStartedAtUtc $writerStartedAt `
                    -OrchestratorSha256 $writerOrchestratorSha256 `
                    -WriterContractSha256 $writerContractSha256 `
                    -AuthorityOwnedByCaller)
                $writerFenceStarted = $true
            }
            if ($writerFenceStarted) {
                [void](Set-LabelWriterFenceDelegation `
                    -ControlRoot $writerFenceControlRoot `
                    -Status 'RESTORING' `
                    -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId `
                    -ReplacementTransactionId $writerTransactionId `
                    -DelegationToken $writerDelegationToken `
                    -DelegatedSources $rollbackSources `
                    -LifetimeSeconds 600)
                SetWriterDelegationEnvironment `
                    $writerDelegationToken `
                    $writerSessionId `
                    $writerAttemptId `
                    $writerTransactionId
            }
            $rollbackCustodyReady = $true
        }
        if ($rollbackCustodyReady) {
            . Invoke-LabelRollbackStep 'candidate_relay_stop' {
                Stop-LabelRollbackCandidateRelay
                $rollbackProtectionReady = $true
            }
        }
        . Invoke-LabelRollbackStep 'generation_before' {
            Assert-LabelRollbackGeneration
            $rollbackGenerationReady = $true
        }
        if ($rollbackGenerationReady -and $rollbackCustodyReady) {
            $rollbackGenerationReady = $false
            . Invoke-LabelRollbackStep 'generation_after' {
                Assert-LabelRollbackGeneration
                $rollbackGenerationReady = $true
            }
        }
        if ($rollbackGenerationReady -and $rollbackCustodyReady) {
            $noCurrentUserSetupCreated = $false
            if ([string]$audit['code_preimage'] -ceq 'ABSENT' -and
                [string]$audit['code_placement'] -cin @('NOT_STARTED', 'PENDING') -and
                $audit['current_user_setup_started'] -is [bool] -and
                -not $audit['current_user_setup_started']) {
                try { $noCurrentUserSetupCreated = -not (Test-Path -LiteralPath $install -ErrorAction Stop) }
                catch { $noCurrentUserSetupCreated = $false }
            }
            if ($noCurrentUserSetupCreated) {
                $Script:LabelRollbackSteps.Add([ordered]@{
                    phase='current_user_removal'; status='NOT_REQUIRED'; reason_code='NO_CURRENT_USER_SETUP_CREATED'
                })
            }
            else {
            . Invoke-LabelRollbackStep 'current_user_removal' {
            $rollbackProductRoot = if (Test-Path (Join-Path $install 'runtime\pythonw.exe')) {
                $install
            }
            else { $source }
            $rollbackUsesInstalled = $false
            if (Same $rollbackProductRoot $install) {
                InvokeFrozenIntegrityProbe $frozenPlacement $install
                $rollbackInventory = PortableInventory $install
                if ($existingVerified -and [string]$rollbackInventory.sha256 -ceq [string]$installedPreimageInventory.sha256) {
                    $rollbackUsesInstalled = $true
                }
                elseif ([string]$rollbackInventory.sha256 -cne [string]$receiptSource.sha256) {
                    throw 'Rollback tree differs from both validated identities.'
                }
            }
            if ($writerFenceStarted) {
                [void](Set-LabelWriterFenceInstalledTree $writerFenceControlRoot $writerSessionId $writerAttemptId $writerTransactionId $rollbackUsesInstalled)
            }
            if (-not ($healthyRemovedInstall -and -not (Test-Path -LiteralPath $install))) {
                # No new setup has run while the exact legacy preimage remains
                # installed. Do not ask that old code to create removal state.
                if (-not ($legacyFirstRegistration -and $rollbackUsesInstalled)) {
                    Product $rollbackProductRoot '--remove-current-user-setup' -LogicalAppRoot $install
                }
            }
            }
            }
            . Invoke-LabelRollbackStep 'writer_absence' {
                [void](Assert-RollbackRelayPreimage -ExpectedRelays @())
                $rollbackQuiescent = $true
            }
            if ($rollbackQuiescent) {
                . Invoke-LabelRollbackStep 'registration_preimage' {
            if ($legacyFirstRegistration) {
                # Detach authentication before restoring legacy code. Keep its
                # own active fence until the guarded placement helper completes.
                $firstRegistrationAttempt.status = 'FAILED_ROLLBACK_INCOMPLETE'
                Save-FirstRegistrationAttempt $firstRegistrationAttempt $firstRegistrationAttemptPath
                $stateMutationLease = Invoke-LabelTimedWait 'placement_admission' { Enter-LabelWriterAdmission -ControlRoot $writerFenceControlRoot -TimeoutMilliseconds 120000 }
                try {
                    $authPaths = @($firstRegistrationStatePaths | Where-Object { -not (Same $_ $defaultDirectSyncRoot) })
                    if (-not $firstRegistrationStateVerified -and
                        @(FirstRegistrationAbsence $authPaths | Where-Object { $_.state -cne 'ABSENT' }).Count -ne 0) {
                        throw 'Unowned state appeared before the first-registration recheck; preserved.'
                    }
                    $audit.rollback.first_registration_state = Move-LegacyFirstRegistrationState `
                        $firstRegistrationStatePaths ([string]$firstRegistrationAttempt.quarantine_root) `
                        $firstRegistrationStarted @($defaultDirectSyncRoot) $firstRegistrationAbsentAncestors $localAuditRoot
                    if (-not $audit.rollback.first_registration_state.restored_absent) {
                        throw 'First-registration authentication cleanup is incomplete; legacy code remains fenced.'
                    }
                }
                finally { Exit-LabelWriterAdmission $stateMutationLease }
            }
                    $rollbackAuthenticationReady = $true
                }
                if ($rollbackAuthenticationReady) {
                    . Invoke-LabelRollbackStep 'code_restore' {
            if ($existingVerified -and -not $rollbackUsesInstalled) {
                if ([string]::IsNullOrEmpty($replacementRollbackRoot)) {
                    throw 'Exact installed code preimage is unavailable for rollback.'
                }
                # Reuse the same pinned placement helper and its verified-tree
                # replacement contract, now with the already validated preimage.
                [void](Set-LabelWriterFenceInstalledTree $writerFenceControlRoot $writerSessionId $writerAttemptId $writerTransactionId $false)
                [void](Set-LabelWriterFenceDelegation `
                    -ControlRoot $writerFenceControlRoot `
                    -Status 'RESTORING' `
                    -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId `
                    -ReplacementTransactionId $writerTransactionId `
                    -DelegationToken $writerDelegationToken `
                    -DelegatedSources @('canonical_placement','auto_update_task_mutation','auto_update_restore_preimage') `
                    -LifetimeSeconds 600)
                # INSTALL_THIS_PC consumes a release tree: its manifest metrics
                # exclude the installed bootstrap record. Reconstruct that exact
                # release view without changing or deleting the retained backup.
                $rollbackSource = Join-Path (Split-Path -Parent $auditPath) ($writerTransactionId + '-rollback-source')
                if ($legacyFirstRegistration) {
                    # A failed placement keeps its source as recovery evidence.
                    # A resumed rollback stages a new copy instead of colliding.
                    $rollbackSource += '-' + [Guid]::NewGuid().ToString('N')
                }
                if (Test-Path -LiteralPath $rollbackSource) { throw 'Rollback source staging already exists.' }
                [void](New-Item -ItemType Directory -Path $rollbackSource)
                $robocopy = Join-Path ([Environment]::SystemDirectory) 'robocopy.exe'
                & $robocopy $replacementRollbackRoot $rollbackSource /E /XJ /MT:16 /R:0 /W:0 /NFL /NDL /NJH /NJS /NP /XF (Join-Path $replacementRollbackRoot 'bootstrap-integrity.json') | Out-Null
                if ($LASTEXITCODE -lt 0 -or $LASTEXITCODE -ge 8) { throw "Rollback source copy failed: $LASTEXITCODE" }
                $restoreParameters = $helperParameters.Clone()
                $restoreParameters.SourceRoot = $rollbackSource
                $restoreParameters.ExpectedSourceAggregateSha256 = [string]$installedPreimageInventory.bootstrap_aggregate_sha256
                $restoreParameters.ExpectedSourceFileCount = [int]$installedPreimageInventory.file_count
                $restoreParameters.ExpectedSourceByteCount = [uint64]$installedPreimageInventory.byte_count
                $restoreExitCode = InvokeFrozenPlacementHelper $frozenPlacement $restoreParameters
                if ($restoreExitCode -ne 0) { throw "Exact code rollback failed: $restoreExitCode" }
                InvokeFrozenIntegrityProbe $frozenPlacement $install
                $restoredInventory = PortableInventory $install
                if ([string]$restoredInventory.sha256 -cne [string]$installedPreimageInventory.sha256) {
                    throw 'Restored code differs from the validated installed preimage.'
                }
                $audit.rollback.code_placement = 'RESTORED_PREIMAGE'
                [void](Set-LabelWriterFenceInstalledTree $writerFenceControlRoot $writerSessionId $writerAttemptId $writerTransactionId $true)
            }
            if (-not $existingVerified -and (Test-Path -LiteralPath $install)) {
                InvokeFrozenIntegrityProbe $frozenPlacement $install
                $rollbackInventory = PortableInventory $install
                if ([string]$rollbackInventory.sha256 -cne [string]$receiptSource.sha256) {
                    throw 'Absent-code rollback tree differs from the validated candidate.'
                }
                [void](Set-LabelWriterFenceDelegation `
                    -ControlRoot $writerFenceControlRoot `
                    -Status 'RESTORING' `
                    -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId `
                    -ReplacementTransactionId $writerTransactionId `
                    -DelegationToken $writerDelegationToken `
                    -DelegatedSources @('canonical_placement','auto_update_task_mutation','auto_update_restore_preimage') `
                    -LifetimeSeconds 600)
                $removeParameters = $helperParameters.Clone()
                $removeParameters.ReplaceExistingVerifiedPortable = $false
                $removeParameters.Uninstall = $true
                $removeExit = Invoke-LabelDelegatedPlacementHelper $frozenPlacement $removeParameters $writerAuthority
                if ($removeExit -ne 0 -or (Test-Path -LiteralPath $install)) {
                    throw 'Absent-code rollback failed to restore code absence.'
                }
            }
            if (-not $existingVerified -and -not (Test-Path -LiteralPath $install)) {
                $audit.rollback.code_placement = 'RESTORED_ABSENCE'
            }
            $audit.rollback.code_restored = $existingVerified -or -not (Test-Path -LiteralPath $install)
            $audit.code_state = if (Test-Path -LiteralPath $install) { 'PRESENT' } else { 'ABSENT' }
                    }
                }
            }
        }
        if ($rollbackGenerationReady) {
            $rollbackGenerationReady = $false
            . Invoke-LabelRollbackStep 'generation_preimage' {
                Assert-LabelRollbackGeneration
                $rollbackGenerationReady = $true
            }
        }
        if ($rollbackGenerationReady) {
            . Invoke-LabelRollbackStep 'user_preimage_admission' {
        $ownerMutationLease = $null
        try {
            if ($writerFenceStarted) {
                $ownerMutationLease = Invoke-LabelTimedWait 'placement_admission' { Enter-LabelWriterAdmission `
                    -ControlRoot $writerFenceControlRoot `
                    -TimeoutMilliseconds 120000 }
            }
            . Invoke-LabelRollbackStep 'run_restore' { Restore $before }
            . Invoke-LabelRollbackStep 'task_restore' { RestoreScheduledTask $taskBefore }
            . Invoke-LabelRollbackStep 'stop_marker_restore' {
            if ([bool]$stopBefore.exists) {
                Copy-LabelAtomicFile ([string]$stopBefore.backup_path) $stop
                if ((Sha $stop) -cne [string]$stopBefore.sha256) {
                    throw 'stop marker restore failed'
                }
            }
            elseif (Test-Path $stop) {
                Remove-Item -LiteralPath $stop
            }
            }
            . Invoke-LabelRollbackStep 'removal_report_restore' {
            if (Test-Path -LiteralPath $removalPath) {
                $removalProof=Join-Path $localAuditRoot ('canonical-portable-'+$runId+'-failed-removal-proof.json')
                if (-not (Test-Path -LiteralPath $removalProof)) { Copy-Item -LiteralPath $removalPath -Destination $removalProof }
                $audit.rollback.removal_failure_proof=[ordered]@{path=$removalProof;sha256=(Sha $removalProof)}
            }
            if ($null -ne $healthyRemovalReportBefore) {
                Copy-LabelAtomicFile $healthyRemovalReportBefore.backup_path $removalPath
                if ((Sha $removalPath) -cne [string]$healthyRemovalReportBefore.sha256) {
                    throw 'Normal removal report preimage restoration failed.'
                }
                $audit.rollback.removal_report_restored = $true
            }
            elseif (-not $removalReportExisted -and (Test-Path -LiteralPath $removalPath)) {
                Remove-Item -LiteralPath $removalPath -Force
                if (Test-Path -LiteralPath $removalPath) { throw 'Removal report absence restoration failed.' }
                $audit.rollback.removal_report_restored = $true
            }
            }
        }
        finally {
            if ($null -ne $ownerMutationLease) {
                Exit-LabelWriterAdmission $ownerMutationLease
            }
        }
            }
            . Invoke-LabelRollbackStep 'worker_shortcuts_restore' {
                if ($audit.Contains('worker_shortcuts')) {
                    if (-not $audit.rollback.code_restored) { throw 'Shortcut restoration requires restored code.' }
                    $shortcuts = $audit.worker_shortcuts
                    Invoke-LabelUserShortcutOperation $install 'Restore' $shortcuts.user_record_path `
                        $shortcuts.helper_path $shortcuts.helper_sha256
                    $parameters = $helperParameters.Clone()
                    $parameters.WorkerShortcutOperation = 'Restore'
                    $parameters.WorkerShortcutRecordPath = [string]$shortcuts.common_record_path
                    $parameters.VerifiedWorkerShortcutHelperPath = [string]$shortcuts.helper_path
                    $parameters.ExpectedWorkerShortcutHelperSha256 = [string]$shortcuts.helper_sha256
                    $parameters.ReplaceExistingVerifiedPortable = $false
                    if ((Invoke-LabelDelegatedPlacementHelper $frozenPlacement $parameters $writerAuthority -RefreshDelegation) -ne 0) {
                        throw 'Common worker shortcut restoration failed.'
                    }
                    $audit.rollback.worker_shortcuts = 'RESTORED'
                }
            }
            . Invoke-LabelRollbackStep 'official_legacy_task_restore' {
                if ($audit.Contains('legacy_relay_task_preimage')) {
                    $parameters=$helperParameters.Clone()
                    $parameters.LegacyRelayTransition='Restore'
                    $parameters.LegacyRelayPreimageSha256=[string]$audit.legacy_relay_task_preimage.sha256
                    $parameters.ReplaceExistingVerifiedPortable=$false
                    if ((Invoke-LabelDelegatedPlacementHelper $frozenPlacement $parameters $writerAuthority -RefreshDelegation) -ne 0) {
                        $failure=[InvalidOperationException]::new('LEGACY_RELAY_RESTORE_FAILED')
                        $failure.Data['placement_child_failure']=$Script:LabelPlacementChildFailure
                        throw $failure
                    }
                    $readback=Get-LabelOfficialLegacyTaskSnapshot
                    if ($null -eq $readback -or $readback.fingerprint.sha256 -cne [string]$audit.legacy_relay_task_preimage.fingerprint.sha256 -or
                        $readback.enabled -ne [bool]$audit.legacy_relay_task_preimage.enabled) { throw 'LEGACY_RELAY_RESTORE_READBACK_FAILED' }
                }
            }
            . Invoke-LabelRollbackStep 'protected_startup_restore' {
        if ($audit.Contains('startup_update_preimage')) {
            $restoreParameters=$helperParameters.Clone()
            $restoreParameters.StartupUpdateRestorePreimage=[string]$audit.startup_update_preimage.path
            $restoreParameters.StartupUpdateRestoreSha256=[string]$audit.startup_update_preimage.sha256
            $restoreParameters.ReplaceExistingVerifiedPortable=$false
            if ((Invoke-LabelDelegatedPlacementHelper $frozenPlacement $restoreParameters $writerAuthority -RefreshDelegation) -ne 0) {
                $failure=[InvalidOperationException]::new('Startup update preimage restoration failed.')
                $failure.Data['placement_child_failure']=$Script:LabelPlacementChildFailure
                throw $failure
            }
        }
        $rollbackStartupProven = $true
            }
            . Invoke-LabelRollbackStep 'preimage_readback' {
        $check = Snapshot
        if (
            [bool]$check.exists -ne [bool]$before.exists -or
            [string]$check.kind -cne [string]$before.kind -or
            [string]$check.data -cne [string]$before.data
        ) { throw 'registry restore failed' }
                if ($existingVerified) {
                    InvokeFrozenIntegrityProbe $frozenPlacement $install
                    if ([string](PortableInventory $install).sha256 -cne [string]$installedPreimageInventory.sha256) {
                        throw 'Rollback final code preimage differs.'
                    }
                } elseif (Test-Path -LiteralPath $install) { throw 'Rollback final code absence differs.' }
                Assert-LabelRollbackTaskPreimage $taskBefore
                if ($audit.Contains('legacy_relay_task_preimage')) {
                    $legacy=Get-LabelOfficialLegacyTaskSnapshot
                    if ($null -eq $legacy -or $legacy.fingerprint.sha256 -cne [string]$audit.legacy_relay_task_preimage.fingerprint.sha256 -or
                        $legacy.enabled -ne [bool]$audit.legacy_relay_task_preimage.enabled) { throw 'Legacy task final preimage differs.' }
                }
                if ([bool]$stopBefore.exists) {
                    if (-not (Test-Path -LiteralPath $stop -PathType Leaf) -or (Sha $stop) -cne [string]$stopBefore.sha256) { throw 'Rollback stop preimage differs.' }
                } elseif (Test-Path -LiteralPath $stop) { throw 'Rollback stop absence differs.' }
                if ($null -ne $healthyRemovalReportBefore) {
                    if ((Sha $removalPath) -cne [string]$healthyRemovalReportBefore.sha256) { throw 'Rollback removal preimage differs.' }
                } elseif (-not $removalReportExisted -and (Test-Path -LiteralPath $removalPath)) { throw 'Rollback removal absence differs.' }
                [void](Assert-RollbackRelayPreimage -ExpectedRelays @())
                $rollbackPreimageProven = $true
                $audit.rollback.code_restored = $true
            }
            # Keep protection when any prerequisite failed. Starting the old
            # relay before exact restoration and fence release is forbidden.
            $rollbackRuntimeProven = $rollbackCustodyReady -and $rollbackPreimageProven -and $rollbackStartupProven
            $rollbackReleaseGenerationProven = $false
            . Invoke-LabelRollbackStep 'generation_release' {
                Assert-LabelRollbackGeneration
                $rollbackReleaseGenerationProven = $true
            }
            $rollbackRuntimeProven = $rollbackRuntimeProven -and $rollbackReleaseGenerationProven
            if ($rollbackRuntimeProven) {
                . Invoke-LabelRollbackStep 'fence_release' {
        $firstRegistrationRollbackLease = $null
        try {
            if ($legacyFirstRegistration) {
                # Keep ordinary writers excluded while releasing the fence and
                # moving its own root. Session authority alone is a different mutex.
                $firstRegistrationRollbackLease = Invoke-LabelTimedWait 'placement_admission' { Enter-LabelWriterAdmission `
                    -ControlRoot $writerFenceControlRoot -TimeoutMilliseconds 120000 }
            }
            if ($writerFenceStarted) {
                $releasedFence = Invoke-LabelTimedWait 'placement_admission' { Stop-LabelWriterFence `
                    -ControlRoot $writerFenceControlRoot `
                    -SessionId $writerSessionId `
                    -AttemptId $writerAttemptId `
                    -ReplacementTransactionId $writerTransactionId `
                    -TimeoutMilliseconds 120000 }
                $writerFenceStarted = $false
                $audit.writer_fence.status = 'RELEASED_AFTER_ROLLBACK'
                $audit.writer_fence.writer_inventory_sha256 = [string]$releasedFence.writer_inventory_sha256
            }
            if ($legacyFirstRegistration) {
                $audit.rollback.first_registration_state = Move-LegacyFirstRegistrationState `
                    $firstRegistrationStatePaths ([string]$firstRegistrationAttempt.quarantine_root) `
                    $firstRegistrationStarted @() $firstRegistrationAbsentAncestors $localAuditRoot
                $audit.rollback.first_registration_state.retry_conflict_action = 'USE_SUPPORTED_ADMIN_RECOVERY'
                if (-not $audit.rollback.first_registration_state.restored_absent) {
                    # Retain custody across a final directory/ancestor move
                    # failure as well; a retry adopts only this exact session.
                    [void](Start-LabelWriterFence -ControlRoot $writerFenceControlRoot -Status 'RESTORING' `
                        -SessionId $writerSessionId -AttemptId $writerAttemptId `
                        -ReplacementTransactionId $writerTransactionId -SessionStartedAtUtc $writerStartedAt `
                        -OrchestratorSha256 $writerOrchestratorSha256 -WriterContractSha256 $writerContractSha256 `
                        -AuthorityOwnedByCaller)
                    $writerFenceStarted = $true
                    [void](Set-LabelWriterFenceInstalledTree $writerFenceControlRoot $writerSessionId $writerAttemptId $writerTransactionId $true)
                    throw 'First-registration final absence restoration is incomplete.'
                }
            }
        }
        finally {
            if ($null -ne $firstRegistrationRollbackLease) {
                Exit-LabelWriterAdmission $firstRegistrationRollbackLease
            }
        }
                }
                if (-not $writerFenceStarted) {
        $rollbackRelayStartedAt=[DateTime]::UtcNow
        foreach ($item in $old) {
            . Invoke-LabelRollbackStep 'relay_restart' {
            $present=@(Relays)
            $sameOriginal=@($present|Where-Object{
                $_.ProcessId -eq $item.ProcessId -and $null -ne $item.CreationDate -and
                $_.CreationDate -eq $item.CreationDate -and
                (Same ([string]$_.ExecutablePath) ([string]$item.ExecutablePath)) -and
                (Normalize-RelayExecutableQuoting ([string]$_.CommandLine) ([string]$item.ExecutablePath)) -ceq
                    (Normalize-RelayExecutableQuoting ([string]$item.CommandLine) ([string]$item.ExecutablePath))
            })
            if($present.Count -eq 1 -and $sameOriginal.Count -eq 1){$newPid=$sameOriginal[0].ProcessId}
            elseif($present.Count -eq 0){$newPid = StartRaw ([string]$item.CommandLine)}
            else{throw 'Rollback relay prestate differs.'}
            Start-Sleep -Seconds 3
            $restored = Get-CimInstance `
                Win32_Process `
                -Filter "ProcessId = $newPid" `
                -ErrorAction SilentlyContinue
            if (
                $null -eq $restored -or
                -not (Same ([string]$restored.ExecutablePath) ([string]$item.ExecutablePath))
            ) { throw 'runtime restore failed' }
            }
        }
            . Invoke-LabelRollbackStep 'relay_ready' {
                $rollbackRelayProof.ready=Wait-LabelRollbackRelayReady $old $relayPath ([string]$candidate.source_commit) $rollbackRelayStartedAt
                $audit.rollback.relay_readiness=$(if($old.Count -eq 0){'NO_RELAY_PREIMAGE'}elseif($rollbackRelayProof.ready){'PROVEN'}else{'UNPROVEN'})
            }
                }
            }
        }
        if (-not $rollbackGenerationReady) {
            . Invoke-LabelGenerationRefusalRecovery
        }
        if ($rollbackGenerationReady) {
        . Invoke-LabelRollbackStep 'final_readback' {
        [void](Assert-RollbackRelayPreimage -ExpectedRelays $old)
        $check = Snapshot
        if (
            [bool]$check.exists -ne [bool]$before.exists -or
            [string]$check.kind -cne [string]$before.kind -or
            [string]$check.data -cne [string]$before.data
        ) { throw 'registry restore failed' }
        }
        }
        $audit.rollback.autostart_restored = [bool]$rollbackStartupProven
        $audit.rollback.runtime_restored = $rollbackRuntimeProven -and -not $writerFenceStarted -and ($audit.rollback.relay_readiness -cin @('PROVEN','NO_RELAY_PREIMAGE'))
        if ($writerFenceStarted) {
            $audit.rollback.guidance = '복원 정합을 확인하지 못해 전송을 멈췄습니다. 자료와 복구 기록을 보존하세요. 같은 새 판을 다시 시작하거나 호환 수정판을 설치하려면 관리자 PowerShell에서 INSTALL_CANONICAL_PORTABLE.ps1 -ResumeRollbackAuditPath <감사 파일> -ExpectedRollbackAuditSha256 <감사 SHA256> 를 실행하세요.'
        }
        $audit.rollback.steps = $Script:LabelRollbackSteps.ToArray()
        $audit.rollback.step_failures = $Script:LabelRollbackFailures.ToArray()
        if ($Script:LabelRollbackErrors.Count -gt 0) { throw $Script:LabelRollbackErrors[0] }
}

function Get-LabelInstallerCaller {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    try {
        $principal = [Security.Principal.WindowsPrincipal]::new($identity)
        return [pscustomobject]@{sid=$identity.User.Value;session_id=[Diagnostics.Process]::GetCurrentProcess().SessionId;
            elevated=$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
    } finally { $identity.Dispose() }
}

function Resolve-LabelWorkerSid([string]$Account) {
    if ($Account -match '^S-1-') { return ([Security.Principal.SecurityIdentifier]::new($Account)).Value }
    return ([Security.Principal.NTAccount]::new($Account)).Translate([Security.Principal.SecurityIdentifier]).Value
}

function Get-LabelWorkerProfileRoot([string]$Sid) {
    $key = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\' + $Sid)
    if ($null -eq $key) { throw 'Worker profile is absent.' }
    try { return [Environment]::ExpandEnvironmentVariables([string]$key.GetValue('ProfileImagePath')) }
    finally { $key.Dispose() }
}

function Assert-LabelMachineEvidencePath {
    if (-not $EvidencePath) { return }
    $programData = if ($testMode) { $env:PROGRAMDATA } else { [Environment]::GetFolderPath('CommonApplicationData') }
    $auditRoot = Join-Path (Full $programData 'machine ProgramData') 'KMTech\Label_Match\install-audit'
    $path = Full $EvidencePath 'EvidencePath'
    if (-not $path.StartsWith($auditRoot.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
        throw 'Machine evidence must stay in the machine install audit directory.'
    }
    for ($ancestor = $path; $ancestor; $ancestor = [IO.Path]::GetDirectoryName($ancestor)) {
        if (Test-Path -LiteralPath $ancestor) {
            $item = Get-Item -Force -LiteralPath $ancestor -ErrorAction Stop
            if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or
                ($ancestor -eq $path -and $item.PSIsContainer) -or
                ($ancestor -ne $path -and -not $item.PSIsContainer)) {
                throw 'Machine evidence is not an ordinary audit file.'
            }
        }
    }
}

function Get-LabelConsoleWorkerObservation {
    if (-not ('KMTechLabelConsoleWorker' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
public static class KMTechLabelConsoleWorker {
    [DllImport("kernel32.dll")] static extern uint WTSGetActiveConsoleSessionId();
    [DllImport("wtsapi32.dll", CharSet=CharSet.Unicode, ExactSpelling=true, SetLastError=true)]
    static extern bool WTSQuerySessionInformationW(IntPtr server, int session, int kind, out IntPtr data, out int bytes);
    [DllImport("wtsapi32.dll")] static extern void WTSFreeMemory(IntPtr data);
    static string Text(int session, int kind) {
        IntPtr data; int bytes;
        if (!WTSQuerySessionInformationW(IntPtr.Zero, session, kind, out data, out bytes))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        try { return Marshal.PtrToStringUni(data); } finally { WTSFreeMemory(data); }
    }
    public static string[] Observe() {
        uint active=WTSGetActiveConsoleSessionId();
        if (active==UInt32.MaxValue || active==0 || active>Int32.MaxValue)
            throw new InvalidOperationException("Active console worker is absent.");
        int session=(int)active; IntPtr data; int bytes;
        if (!WTSQuerySessionInformationW(IntPtr.Zero, session, 8, out data, out bytes))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        try {
            if (bytes<4 || Marshal.ReadInt32(data)!=0)
                throw new InvalidOperationException("Console worker is not active.");
        } finally { WTSFreeMemory(data); }
        string user=Text(session,5), domain=Text(session,7);
        if (String.IsNullOrWhiteSpace(user) || String.IsNullOrWhiteSpace(domain))
            throw new InvalidOperationException("Console worker identity is absent.");
        return new string[] {session.ToString(System.Globalization.CultureInfo.InvariantCulture), domain+"\\"+user};
    }
}
'@ -ErrorAction Stop
    }
    $observed = [KMTechLabelConsoleWorker]::Observe()
    return [pscustomobject]@{session_id=[int]$observed[0];account=[string]$observed[1]}
}

function Get-LabelConsoleWorker {
    $reason = 'CONSOLE_WORKER_ABSENT'
    try {
        $before = @(Get-LabelConsoleWorkerObservation)
        if ($before.Count -ne 1 -or $before[0].session_id -isnot [int] -or $before[0].session_id -le 0 -or
        $before[0].account -isnot [string] -or [string]::IsNullOrWhiteSpace($before[0].account)) { $reason = if ($before.Count -eq 0) { 'CONSOLE_WORKER_ABSENT' } else { 'CONSOLE_WORKER_AMBIGUOUS' }; throw 'Console worker is ambiguous.' }
        $reason = 'WORKER_ACCOUNT_UNRESOLVED'
        $sid = Resolve-LabelWorkerSid $before[0].account
        $reason = 'WORKER_PROFILE_ABSENT'
        $profile = Get-LabelWorkerProfileRoot $sid
        $reason = 'CONSOLE_WORKER_ABSENT'
        $after = @(Get-LabelConsoleWorkerObservation)
        if ($after.Count -ne 1 -or $after[0].session_id -cne $before[0].session_id -or
        $after[0].account -cne $before[0].account) { $reason = 'CONSOLE_WORKER_AMBIGUOUS'; throw 'Console worker changed during observation.' }
        return [pscustomobject]@{sid=$sid;profile_root=$profile;session_id=$before[0].session_id}
    } catch {
        $_.Exception.Data['worker_pending_reason'] = $reason
        throw
    }
}

function Resolve-LabelMachineWorker($Caller, [string]$Account, [string]$InventoryPath, [bool]$ArgumentsSupplied = $false) {
    $reason = 'UNCLASSIFIED'
    try {
        if (-not $testMode -and -not $Uninstall -and -not $PlanOnly -and
            [string]::IsNullOrWhiteSpace($Account)) {
            $reason = 'WORKER_ARGS_INCOMPLETE'
            throw '설치 인수 WorkerAccount에 실제 로컬 작업자 계정 하나를 명시하세요.'
        }
        if (-not $Caller.elevated -and $Caller.session_id -ne 0) {
            if ($ArgumentsSupplied -or $Account -or $InventoryPath) { $reason = 'WORKER_ARGS_REQUIRE_ADMIN'; throw 'Worker arguments require the administrator entry.' }
            return $null
        }
        if ($Caller.elevated -and -not $ArgumentsSupplied -and -not $Account -and -not $InventoryPath) {
            # Read-only planning and guarded legacy harnesses do not install a worker.
            if ($PlanOnly -or ($testMode -and $Caller.session_id -ne 0)) { return $null }
            $reason = 'CONSOLE_WORKER_ABSENT'
            $console = Get-LabelConsoleWorker
            if ($console.sid -isnot [string] -or $console.sid -cnotmatch '^S-1-5-21-\d+-\d+-\d+-\d+$' -or
                $console.profile_root -isnot [string] -or -not [IO.Path]::IsPathRooted($console.profile_root)) {
                $reason = 'WORKER_SID_UNSUPPORTED'
                if ($console.sid -is [string] -and $console.sid -cmatch '^S-1-5-21-(\d+-){3}\d+$') { $reason = 'WORKER_PROFILE_DIFFERS' }
                throw 'Console worker binding is invalid.'
            }
            $reason = 'WORKER_PROFILE_DIFFERS'
            $profile = [IO.Path]::GetFullPath($console.profile_root).TrimEnd('\')
            if ($profile -eq [IO.Path]::GetPathRoot($profile).TrimEnd('\')) { throw 'Console worker profile is invalid.' }
            if ($Caller.session_id -eq $console.session_id -and [string]$Caller.sid -ceq $console.sid) { return $null }
            $reason = 'EVIDENCE_PATH_INVALID'
            Assert-LabelMachineEvidencePath
            $reason = 'UNCLASSIFIED'
            $observation = [ordered]@{status='READY';target_sid=$console.sid;target_profile_root=$profile;
                console_session_id=$console.session_id;target_source='ACTIVE_CONSOLE'}
            $bytes = [Text.Encoding]::UTF8.GetBytes(($observation | ConvertTo-Json -Compress))
            return [pscustomobject]@{sid=$console.sid;profile_root=$profile;local_app_data=(Join-Path $profile 'AppData\Local');
                inventory_sha256=(ByteSha $bytes);caller_is_worker=([string]$Caller.sid -ceq $console.sid -and -not $Caller.elevated);target_source='ACTIVE_CONSOLE'}
        }
        if (-not $Caller.elevated -or [string]::IsNullOrWhiteSpace($Account) -or
            [string]::IsNullOrWhiteSpace($InventoryPath)) { $reason = if (-not $Caller.elevated) { 'WORKER_ARGS_REQUIRE_ADMIN' } else { 'WORKER_ARGS_INCOMPLETE' }; throw 'Worker target and inventory are required.' }
        $reason = 'WORKER_ACCOUNT_UNRESOLVED'
        $sid = Resolve-LabelWorkerSid $Account
        if ($sid -cnotmatch '^S-1-5-21-\d+-\d+-\d+-\d+$') { $reason = 'WORKER_SID_UNSUPPORTED'; throw 'Worker target is invalid.' }
        if (-not [IO.Path]::IsPathRooted($InventoryPath)) { $reason = 'INVENTORY_PATH_INVALID'; throw 'Inventory path must be absolute.' }
        $reason = 'INVENTORY_FILE_INVALID'
        $file = Get-Item -Force -LiteralPath $InventoryPath -ErrorAction Stop
        if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint) -or
            $file.Length -le 0 -or $file.Length -gt 1048576) { throw 'Inventory must be a bounded ordinary file.' }
        [byte[]]$bytes = [IO.File]::ReadAllBytes($file.FullName)
        if ($bytes.Length -gt 1048576) { throw 'Inventory is oversized.' }
        $reason = 'INVENTORY_DECODE_INVALID'
        $inventory = (([Text.UTF8Encoding]::new($false,$true)).GetString($bytes) -replace '^\uFEFF','') | ConvertFrom-Json
        $reason = 'INVENTORY_BINDING_DIFFERS'
        if ($inventory.status -isnot [string] -or $inventory.status -cne 'READY' -or
            $inventory.target_sid -isnot [string] -or $inventory.target_sid -cne $sid -or
            $inventory.target_profile_root -isnot [string] -or
            -not [IO.Path]::IsPathRooted($inventory.target_profile_root)) { throw 'Worker inventory binding differs.' }
        $reason = 'WORKER_PROFILE_ABSENT'
        $profile = Get-LabelWorkerProfileRoot $sid
        $reason = 'WORKER_PROFILE_DIFFERS'
        if ([string]::IsNullOrWhiteSpace($profile) -or -not [IO.Path]::IsPathRooted($profile)) { throw 'Worker profile is invalid.' }
        $profile = [IO.Path]::GetFullPath($profile).TrimEnd('\')
        if (-not [StringComparer]::OrdinalIgnoreCase.Equals($profile,
            [IO.Path]::GetFullPath($inventory.target_profile_root).TrimEnd('\')) -or
            $profile -eq [IO.Path]::GetPathRoot($profile).TrimEnd('\')) { throw 'Worker profile differs.' }
        $reason = 'EVIDENCE_PATH_INVALID'
        Assert-LabelMachineEvidencePath
        $reason = 'UNCLASSIFIED'
        return [pscustomobject]@{sid=$sid;profile_root=$profile;local_app_data=(Join-Path $profile 'AppData\Local');inventory_sha256=(ByteSha $bytes);caller_is_worker=($sid -ceq [string]$Caller.sid -and -not $Caller.elevated)}
    } catch {
        if ($_.Exception.Data.Contains('worker_pending_reason')) { $reason = [string]$_.Exception.Data['worker_pending_reason'] }
        $failure = [InvalidOperationException]::new('Worker pending installation input is invalid.')
        $failure.Data['worker_pending_failure'] = $true
        $failure.Data['worker_pending_reason'] = $reason
        throw $failure
    }
}

function Assert-LabelMachineWorkerReadScope($Worker) {
    if ($null -eq $Worker -or -not $Worker.caller_is_worker) { return }
    $local = [string]$env:LOCALAPPDATA
    if ([string]::IsNullOrWhiteSpace($local) -or -not [IO.Path]::IsPathRooted($local) -or
        -not [StringComparer]::OrdinalIgnoreCase.Equals(
            [IO.Path]::GetFullPath($local).TrimEnd('\'), [IO.Path]::GetFullPath($Worker.local_app_data).TrimEnd('\'))) {
        throw 'Current worker LOCALAPPDATA differs from the selected worker.'
    }
    if ($testMode) {
        $programs = Join-Path $Worker.profile_root 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs'
        $desktop = Join-Path $Worker.profile_root 'Desktop'
    } else {
        $knownLocal = [Environment]::GetFolderPath('LocalApplicationData', [Environment+SpecialFolderOption]::DoNotVerify)
        if ([string]::IsNullOrWhiteSpace($knownLocal) -or -not [StringComparer]::OrdinalIgnoreCase.Equals(
            [IO.Path]::GetFullPath($local).TrimEnd('\'), [IO.Path]::GetFullPath($knownLocal).TrimEnd('\'))) {
            throw 'Current worker profile LOCALAPPDATA differs from the process environment.'
        }
        $programs = [Environment]::GetFolderPath('Programs', [Environment+SpecialFolderOption]::DoNotVerify)
        $desktop = [Environment]::GetFolderPath('DesktopDirectory', [Environment+SpecialFolderOption]::DoNotVerify)
    }
    foreach ($path in @($local, $programs, $desktop)) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not [IO.Path]::IsPathRooted($path)) {
            throw 'Current worker folder scope is unavailable.'
        }
        for ($ancestor = [IO.Path]::GetFullPath($path); $ancestor; $ancestor = [IO.Path]::GetDirectoryName($ancestor)) {
            $attributes = $null
            try { $attributes = [IO.File]::GetAttributes($ancestor) }
            catch [IO.FileNotFoundException] { }
            catch [IO.DirectoryNotFoundException] { }
            if ($null -ne $attributes -and (-not ($attributes -band [IO.FileAttributes]::Directory) -or
                ($attributes -band [IO.FileAttributes]::ReparsePoint))) {
                throw 'Current worker folder scope is not an ordinary directory.'
            }
        }
    }
}

function Initialize-LabelMachineDiagnostics {
    # Only after target admission: child diagnostics must also avoid user profiles.
    $programData = if ($testMode) { $env:PROGRAMDATA } else { [Environment]::GetFolderPath('CommonApplicationData') }
    $root = Join-Path (Full $programData 'machine ProgramData') ('KMTech\Label_Match\install-audit\tmp-' + [Guid]::NewGuid().ToString('N'))
    for ($ancestor = $root; $ancestor; $ancestor = [IO.Path]::GetDirectoryName($ancestor)) {
        if (Test-Path -LiteralPath $ancestor) {
            $item = Get-Item -Force -LiteralPath $ancestor -ErrorAction Stop
            if (-not $item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
                throw 'Machine diagnostic parent is not an ordinary directory.'
            }
        }
    }
    [void](New-Item -ItemType Directory -Path $root -ErrorAction Stop)
    $acl = [Security.AccessControl.DirectorySecurity]::new()
    $acl.SetAccessRuleProtection($true,$false)
    foreach ($sid in @('S-1-5-18','S-1-5-32-544')) {
        $acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new(
            [Security.Principal.SecurityIdentifier]::new($sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow'))
    }
    Set-Acl -LiteralPath $root -AclObject $acl -ErrorAction Stop
    # This installer process exits after machine placement. Children inherit only
    # these process settings; no persistent environment or security setting changes.
    $env:TEMP = $root
    $env:TMP = $root
}

function Install-LabelMachineWorkerShortcut([string]$Install, [string]$Menu) {
    $path = Join-Path $Menu 'KMTech 포장.lnk'
    $target = Join-Path $Install 'runtime\pythonw.exe'
    $arguments = '-I -B "' + (Join-Path $Install 'app\main.py') + '"'
    if (Test-Path -LiteralPath $path) {
        $item = Get-Item -Force -LiteralPath $path -ErrorAction Stop
        if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Common shortcut is not an ordinary file.' }
    }
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut($path)
    if (Test-Path -LiteralPath $path) {
        if (-not (Same $shortcut.TargetPath $target) -or $shortcut.Arguments -cne $arguments) {
            throw 'Common shortcut belongs to another installation; preserve it for the kit.'
        }
    } else {
        $shortcut.TargetPath = $target; $shortcut.Arguments = $arguments
        $shortcut.WorkingDirectory = $Install
        $shortcut.Save()
    }
    $accepted = $shell.CreateShortcut($path)
    if (-not (Same $accepted.TargetPath $target) -or $accepted.Arguments -cne $arguments -or
        -not (Same $accepted.WorkingDirectory $Install)) { throw 'Machine shortcut readback differs.' }
    return [ordered]@{path=[string]$path;sha256=[string](Sha $path);published=@(Get-LabelPublishedShortcut 'start_menu' $path $target $arguments $Install)}
}

function Test-LabelWorkerFirstRunAllowed($Worker, $Caller) {
    return $null -ne $Worker -and $null -ne $Caller -and
        $Caller.session_id -is [int] -and $Caller.session_id -gt 0 -and
        $Caller.sid -is [string] -and $Worker.sid -is [string] -and
        $Caller.sid -ceq $Worker.sid
}

function Invoke-LabelWorkerFirstRun($Worker, [string]$Install) {
    if (-not (Test-LabelWorkerFirstRunAllowed $Worker (Get-LabelInstallerCaller))) {
        throw 'Worker first run requires its own interactive session.'
    }
    $code = RelayCodeRoot $Install
    $line = (Arg (Join-Path $code 'runtime\pythonw.exe')) + ' -I -B ' +
        (Arg (Join-Path $code 'app\label_match_relay_entry.py')) + ' --onboard-current-user --app-root ' +
        (Arg (Join-Path $Install 'app'))
    if ($serverBaseUrl) { $line += ' --server-base-url ' + (Arg $serverBaseUrl) }
    return StartRaw $line
}

function Assert-LabelReusedProofProtection([string]$Path) {
    for($part=$Path;$part;$part=[IO.Path]::GetDirectoryName($part)){
        if([IO.File]::GetAttributes($part) -band [IO.FileAttributes]::ReparsePoint){throw 'REUSED_PROOF_REPARSE'}
    }
    $acl=Get-Acl -LiteralPath $Path -ErrorAction Stop
    $owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
    if($owner -cnotin @('S-1-5-18','S-1-5-32-544','S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')){throw 'REUSED_PROOF_OWNER'}
    foreach($rule in $acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier])){
        if($rule.AccessControlType -eq [Security.AccessControl.AccessControlType]::Allow -and
            $rule.IdentityReference.Value -cnotin @('S-1-5-18','S-1-5-32-544') -and
            ([long]$rule.FileSystemRights -band 0x500D0156) -ne 0){throw 'REUSED_PROOF_MUTABLE'}
    }
}

function Read-LabelProtectedReusedProof($Frozen,$Parameters,$SourceManifest,$Receipt,[string]$InstalledRoot,$Session) {
    if($null -eq $Session -or -not $Session.PSObject.Properties['last_child_process_id'] -or
        -not $Session.PSObject.Properties['last_child_process_started_at_filetime']){throw 'REUSED_NATIVE_CHILD_UNPROVEN'}
    $path=Join-Path (Split-Path -Parent ([string]$Parameters.InstallRoot)) `
        ('.installer-reused-'+$Parameters.InstallerRunId+'-'+$Session.last_child_process_id+'.json')
    Assert-LabelReusedProofProtection $path
    $stream=[IO.File]::Open($path,'Open','Read','Read')
    try{
        if($stream.Length -lt 1 -or $stream.Length -gt 65536){throw 'REUSED_PROOF_SIZE'}
        [byte[]]$bytes=([IO.BinaryReader]::new($stream)).ReadBytes([int]$stream.Length)
        $record=([Text.UTF8Encoding]::new($false,$true)).GetString($bytes)|ConvertFrom-Json
        if($record.schema -cne 'label-match-protected-reused-v1' -or $record.status -cne 'PASS' -or
            $record.code_replaced -isnot [bool] -or $record.code_replaced -or
            $record.run_id -cne $Parameters.InstallerRunId -or
            ($record.helper_process_id -isnot [int] -and $record.helper_process_id -isnot [long]) -or
            $record.helper_process_id -ne $Session.last_child_process_id -or
            $record.helper_process_started_at_filetime -cne $Session.last_child_process_started_at_filetime -or
            $record.helper_sha256 -cne $Frozen.helper_sha256 -or $record.source_commit -cne $SourceManifest.source_commit -or
            -not (Same $record.source_root $Parameters.SourceRoot) -or -not(Same $record.installed_root $InstalledRoot) -or
            $record.source_manifest_sha256 -cne (Sha (Join-Path $Parameters.SourceRoot 'portable-manifest.json')) -or
            $record.installed_manifest_sha256 -cne $record.source_manifest_sha256 -or
            $record.installed_manifest_sha256 -cne (Sha (Join-Path $InstalledRoot 'portable-manifest.json')) -or
            $record.source_aggregate_sha256 -cne $Receipt.bootstrap_aggregate_sha256 -or
            $record.installed_aggregate_sha256 -cne $record.source_aggregate_sha256 -or
            $record.source_file_count -ne $Parameters.ExpectedSourceFileCount -or
            $record.source_byte_count -ne $Parameters.ExpectedSourceByteCount -or
            $record.startup_readback -cne 'VERIFIED_LIFECYCLE' -or
            $record.session_id -cne $Parameters.WriterFenceSessionId -or $record.attempt_id -cne $Parameters.WriterFenceAttemptId -or
            $record.replacement_transaction_id -cne $Parameters.WriterFenceReplacementTransactionId -or
            $record.writer_contract_sha256 -cne $Frozen.writer_fence_sha256 -or
            $record.orchestrator_sha256 -cne (Sha (Join-Path $Parameters.SourceRoot 'INSTALL_CANONICAL_PORTABLE.ps1')) -or
            $record.writer_inventory_sha256 -cne $Script:LabelWriterFenceInventorySha256){throw 'REUSED_PROOF_BINDING_DIFFERS'}
        if((PortableInventory $InstalledRoot).sha256 -cne $Receipt.sha256){throw 'REUSED_FINAL_INVENTORY_DIFFERS'}
        return [ordered]@{status='PASS';code_replaced=$false;proof_path=$path;proof_sha256=(ByteSha $bytes);
            helper_process_id=$record.helper_process_id;helper_process_started_at_filetime=$record.helper_process_started_at_filetime}
    }finally{$stream.Dispose()}
}

function Invoke-LabelMachinePlacementRollback {
    $audit.rollback.applied=$true
    $audit.rollback.fence_released=$false
    $audit.rollback.code_restored=$false;$audit.rollback.autostart_restored=$false
    $audit.rollback.runtime_restored=$false
    $audit.rollback.relay_readiness='NOT_APPLICABLE_MACHINE_WORKER_PENDING'
    if($null -ne $Script:LabelPlacementSession -and $Script:LabelPlacementSession.child_exit_unproven){throw 'MACHINE_ROLLBACK_CHILD_UNPROVEN'}
    if(-not $existing){
        # Preserve the existing fresh-machine deferred contract. Verified newly
        # placed code has no earlier worker/code runtime to claim as restored.
        $audit.rollback.applied=$false
        if($null -ne $workerPendingForPlacedCode -and (PortableInventory $Install).sha256 -ceq $receipt.sha256){
            $audit.rollback.code_preimage='ABSENT_NEW_CODE_RETAINED_PENDING'
            $audit.rollback.guidance='처음 설치: 지정 작업자 계정의 첫 일반 실행에서 준비를 마치세요.'
            $machineFenceReleaseProven=$true
            return
        }
        if(-not(Test-Path -LiteralPath $Install)){
            $audit.rollback.code_restored=$true;$audit.rollback.code_preimage='ABSENT'
            $machineFenceReleaseProven=$true
            return
        }
        throw 'MACHINE_FRESH_CODE_RECOVERY_UNPROVEN'
    }
    [void](Set-LabelWriterFenceDelegation -ControlRoot $control -Status 'RESTORING' -SessionId $session -AttemptId $attempt `
        -ReplacementTransactionId $transaction -DelegationToken $delegation -LifetimeSeconds 600 `
        -DelegatedSources @('canonical_placement','auto_update_task_mutation','auto_update_restore_preimage',
            'auto_update_supported_lifecycle_transition','auto_update_persist_switch','auto_update_write_json_durable','auto_update_fixed_helper'))
    $startupDirectory=Join-Path (Split-Path -Parent $Install) ('.startup-update-install.'+$attempt)
    $startupRecord=Join-Path $startupDirectory 'preimage.json'
    if(Test-Path -LiteralPath $startupRecord -PathType Leaf){
        $restore=$parameters.Clone()
        $restore.StartupUpdateRestorePreimage=$startupDirectory;$restore.StartupUpdateRestoreSha256=Sha $startupRecord
        $restoreExit=InvokeFrozenPlacementHelper $frozen $restore
        if($restoreExit -ne 0){throw 'MACHINE_STARTUP_PREIMAGE_RESTORE_FAILED'}
        $audit.rollback.startup_preimage=[ordered]@{path=$startupDirectory;sha256=$restore.StartupUpdateRestoreSha256}
    }
    if($existing){
        if($null -eq $Lifecycle -and (PortableInventory $Install).sha256 -cne $preimage.sha256){
            $backup=ReplacementPreimage $Install $preimage $backupsBefore
            $restoreSource=Join-Path $auditRoot ($run+'-rollback-source')
            if(Test-Path -LiteralPath $restoreSource){throw 'MACHINE_ROLLBACK_SOURCE_OCCUPIED'}
            [void][IO.Directory]::CreateDirectory($restoreSource)
            $robocopy=Join-Path ([Environment]::SystemDirectory) 'robocopy.exe'
            & $robocopy $backup $restoreSource /E /XJ /MT:16 /R:0 /W:0 /NFL /NDL /NJH /NJS /NP /XF (Join-Path $backup 'bootstrap-integrity.json')|Out-Null
            if($LASTEXITCODE -lt 0 -or $LASTEXITCODE -ge 8){throw 'MACHINE_ROLLBACK_SOURCE_COPY_FAILED'}
            $restore=$parameters.Clone();$restore.SourceRoot=$restoreSource
            $restore.ExpectedSourceAggregateSha256=$preimage.bootstrap_aggregate_sha256
            $restore.ExpectedSourceFileCount=[int]$preimage.file_count;$restore.ExpectedSourceByteCount=[uint64]$preimage.byte_count
            if((InvokeFrozenPlacementHelper $frozen $restore) -ne 0){throw 'MACHINE_CODE_PREIMAGE_RESTORE_FAILED'}
        }
        InvokeFrozenIntegrityProbe $frozen $priorRoot
        if((PortableInventory $priorRoot).sha256 -cne $preimage.sha256){throw 'MACHINE_CODE_PREIMAGE_READBACK_FAILED'}
        if($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED'){
            $ownerRecord=Join-Path (Split-Path -Parent $Install) ('.installer-owner-'+$session+'-'+($run -split '-')[-1]+'.json')
            $restored=Read-CanonicalStartupLifecycle $Source $Install $control $ownerRecord @($delegation,$session,$attempt,$transaction)
            if($restored.lifecycle_state -cne 'INSTALLED' -or $restored.from_commit -cne $Lifecycle.from_commit -or
                -not(Same $restored.active_code_root $priorRoot)){throw 'MACHINE_STARTUP_PREIMAGE_READBACK_FAILED'}
        }
    }
    $audit.rollback.code_restored=$true;$audit.rollback.autostart_restored=$true
    $workerPendingForPlacedCode=$null # Existing code recovered: restore its pending preimage too.
    $audit.rollback.guidance=if($existing){'같은 작업자 일반 세션에서 --remove-current-user-setup → --onboard-current-user 순서로 실행하세요.'}else{'처음 설치: 지정 작업자 계정의 첫 일반 실행에서 준비를 마치세요.'}
    $machineFenceReleaseProven=$true
}

function Invoke-LabelMachineWorkerInstall($Worker, [string]$Source, [string]$Install, $SourceManifest, $Lifecycle = $null, [bool]$SetupCurrentUser = $false) {
    # The existing pinned placement helper owns code, backups and startup state.
    # Only a non-elevated same-SID caller can prepare its own profile.
    Assert-LabelMachineEvidencePath
    if ($SourceManifest.startup_update_protocol -ne 1) { throw 'Machine worker installation requires managed portable code.' }
    if (@(UnquiescedProductWriters).Count) {
        Write-LabelInstallerRelayRecoveryGuidance -MachineWorker -Existing:(Test-Path -LiteralPath $Install -PathType Container)
        throw 'Canonical product writers must exit before machine placement.'
    }
    $receipt = PortableInventory $Source
    $existing = Test-Path -LiteralPath $Install -PathType Container
    $priorRoot = if ($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED') { [string]$Lifecycle.active_code_root } else { $Install }
    if ($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED') {
        $policy = Get-Content -LiteralPath (Join-Path (Split-Path -Parent $Install) 'update-control\policy.json') -Raw -Encoding UTF8 | ConvertFrom-Json
        if ([string]$policy.operator_sid -cne $Worker.sid -or -not (Same ([string]$policy.operator_local_app_data) $Worker.local_app_data)) {
            throw 'Supported machine update belongs to a different worker.'
        }
    }
    $preimage = if ($existing) { PortableInventory $priorRoot } else { $null }
    $transition = Assert-WriterTransition $Source $(if ($existing) { $priorRoot } else { $Source })
    $backupsBefore = @(Get-ChildItem -Force -LiteralPath (Split-Path -Parent $Install) -Directory -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like '.current.rollback.*' } | ForEach-Object { $_.FullName })
    $run = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ') + '-' + [Guid]::NewGuid().ToString('N')
    $programData = if ($testMode) { $env:PROGRAMDATA } else { [Environment]::GetFolderPath('CommonApplicationData') }
    $auditRoot = Join-Path (Full $programData 'machine ProgramData') 'KMTech\Label_Match\install-audit'
    $auditFile = Join-Path $auditRoot ('canonical-portable-' + $run + '.json')
    $frozen = FreezePlacementHelper $Source $auditRoot $run $receipt.critical_file_sha256
    [byte[]]$integrityBytes = PinnedFileBytes (Join-Path $frozen.root 'tools\bootstrap_integrity.ps1') $frozen.integrity_sha256
    . ([ScriptBlock]::Create((([Text.UTF8Encoding]::new($false,$true)).GetString($integrityBytes) -replace '^\uFEFF',''))) -SharedCodeRoot $frozen.root
    . $frozen.writer_fence_path
    $control = Join-Path $auditRoot ('machine-writer-' + $run)
    Initialize-LabelMachineWriterRoot $control
    $Script:LabelWriterFenceAdmissionProductionRoot = $control
    $session = [Guid]::NewGuid().ToString('N'); $attempt = [Guid]::NewGuid().ToString('N'); $transaction = [Guid]::NewGuid().ToString('N')
    $delegation = [Guid]::NewGuid().ToString('N') + [Guid]::NewGuid().ToString('N')
    $orchestrator = Sha (Join-Path $Source 'INSTALL_CANONICAL_PORTABLE.ps1')
    $contract = $frozen.writer_fence_sha256
    $ownerStartedAtFileTime = [Diagnostics.Process]::GetCurrentProcess().StartTime.ToUniversalTime().ToFileTimeUtc().ToString()
    $sessionStartedAt = [DateTime]::UtcNow.ToString('o')
    if ($transition.candidate_inventory_sha256 -cne $Script:LabelWriterFenceInventorySha256) { throw 'Machine writer inventory differs.' }
    $Script:LabelWriterFenceInstalledIdentity = [pscustomobject]@{session_id=$session;attempt_id=$attempt;replacement_transaction_id=$transaction;
        orchestrator_sha256=$orchestrator;writer_contract_sha256=$contract;inventory_sha256=$transition.installed_inventory_sha256}
    $audit = [ordered]@{schema='label-match-canonical-portable-install-v1';status='PREIMAGE_SAVED';run_id=$run;
        captured_at=[DateTime]::UtcNow.ToString('o');install_root=$Install;source_commit=$SourceManifest.source_commit;
        code_placement='PENDING';code_preimage=$(if($existing){'PRESENT'}else{'ABSENT'});worker_sid=$Worker.sid;worker_setup='PENDING';
        preimage=[ordered]@{scope='WORKER_DEFERRED';captured=$false};writer_transition=[ordered]@{compatibility=$transition.compatibility;
            installed_inventory_sha256=$transition.installed_inventory_sha256;candidate_inventory_sha256=$transition.candidate_inventory_sha256;
            installed_portable_inventory_sha256=$(if($existing){$preimage.sha256}else{''});candidate_portable_inventory_sha256=$receipt.sha256};
        rollback=[ordered]@{available=$true;applied=$false;runtime_restored=$false}}
    Save $auditFile $audit
    $authority = $null; $fenced = $false;$machineFenceReleaseProven=$false
    $parameters=$null
    $workerArtifacts = @(); $workerArtifactsCommitted = $false
    $workerPendingPath = Join-Path (Split-Path -Parent $Install) 'update-control\worker-pending.json'
    $workerPendingForPlacedCode = $null
    $Script:LabelPlacementSessionRequested=$true
    $Script:LabelPlacementSession=$null
    $Script:LabelPlacementSessionLaunchAttempted=$false
    try {
        $authority = Enter-LabelWriterSessionAuthority -SessionId $session -AttemptId $attempt -OrchestratorSha256 $orchestrator `
            -ReplacementTransactionId $transaction -WriterContractSha256 $contract
        $markers = @('KMTech\Label_Match\data\data-generation.json','KMTech\Label_Match\config\data-generation.json',
            'KMTech\Logistics\profiles\Label_Match\data-generation.json','KMTech\Bootstrap\Label_Match\data-generation.json',
            'KMTech\DirectSync\label_match\data-generation.json','KMTech\DirectSync\label_match\queue\data-generation.json',
            ('KMTech\DirectSync\label_match\control\writer-session\data-generation\' + $Worker.sid + '.json')) |
            ForEach-Object { Join-Path $Worker.local_app_data $_ }
        $parameters = @{SourceRoot=$Source;InstallRoot=$Install;ElevationLogPath=(Join-Path $auditRoot ($run+'-elevated.jsonl'));
            InstallerRunId=$run;InstallerOwnerProcessId=[int]$PID;InstallerOwnerProcessStartedAtFileTime=[Diagnostics.Process]::GetCurrentProcess().StartTime.ToUniversalTime().ToFileTimeUtc().ToString();
            ExpectedBootstrapScriptSha256=$frozen.helper_sha256;VerifiedBootstrapScriptPath=$frozen.helper_path;BootstrapIntegrityPreloaded=$true;
            ExpectedSourceAggregateSha256=$receipt.bootstrap_aggregate_sha256;ExpectedSourceFileCount=[int]$receipt.file_count;ExpectedSourceByteCount=[uint64]$receipt.byte_count;
            WriterFenceFunctionsPreloaded=$true;WriterFenceControlRoot=$control;WriterFenceSessionId=$session;WriterFenceAttemptId=$attempt;
            WriterFenceReplacementTransactionId=$transaction;WriterFenceDelegationToken=$delegation;DataGenerationSubjectSid=$Worker.sid;DataGenerationMarkerPaths=@($markers);
            WorkerSid=$Worker.sid;OperatorLocalAppDataRoot=$Worker.local_app_data;AllowNoncanonicalLayoutForTest=[bool]$testMode;ReplaceExistingVerifiedPortable=[bool]$existing;DryRun=$false}
        if ($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED') { $parameters.ExpectedActiveCommit=[string]$Lifecycle.from_commit }
        # 118 review: tuple + kind-only context are saved and the protected owner
        # record is published (elevated helper, read back) BEFORE the fence exists.
        . Save-LabelMachinePreFenceRecord
        Invoke-LabelPreFenceOwnerRecord $frozen $parameters @{writer_inventory_sha256=$Script:LabelWriterFenceInventorySha256
            orchestrator_sha256=$orchestrator;writer_contract_sha256=$contract;session_started_at_utc=$sessionStartedAt
            session_id=$session;attempt_id=$attempt;replacement_transaction_id=$transaction}
        [void](Start-LabelWriterFence -ControlRoot $control -Status 'INSTALLING' -SessionId $session -AttemptId $attempt `
            -ReplacementTransactionId $transaction -SessionStartedAtUtc $sessionStartedAt `
            -OrchestratorSha256 $orchestrator -WriterContractSha256 $contract -AuthorityOwnedByCaller)
        $fenced = $true
        $audit.writer_fence=[ordered]@{status='INSTALLING';control_root=[string]$control;owner_process_id=[int]$PID;owner_process_started_at_filetime=$ownerStartedAtFileTime;session_started_at_utc=$sessionStartedAt;session_id=$session;attempt_id=$attempt;
            replacement_transaction_id=$transaction;orchestrator_sha256=$orchestrator;writer_contract_sha256=$contract;
            writer_inventory_sha256=$Script:LabelWriterFenceInventorySha256;token_recorded=$false}
        [void](Set-LabelWriterFenceDelegation -ControlRoot $control -Status 'INSTALLING' -SessionId $session -AttemptId $attempt `
            -ReplacementTransactionId $transaction -DelegationToken $delegation -LifetimeSeconds 600 `
            -DelegatedSources @('canonical_placement','auto_update_task_mutation','auto_update_restore_preimage',
                'auto_update_supported_lifecycle_transition','auto_update_persist_switch','auto_update_write_json_durable','auto_update_fixed_helper'))
        # Already elevated: the same launcher omits RunAs, preserving its pins and delegation.
        $exit = InvokeFrozenPlacementHelper $frozen $parameters
        if ($exit -ne 0) {
            $failure = [InvalidOperationException]::new('Machine code placement failed.')
            $failure.Data['installation_preparation_exit_code'] = $exit
            $failure.Data['placement_child_failure'] = $Script:LabelPlacementChildFailure
            throw $failure
        }
        # The pinned helper has completed its placement/readback. Later census,
        # shortcut or profile failures must retain a marker for that release.
        $workerPendingForPlacedCode = New-LabelMachineWorkerPendingMarker $run $Worker $SourceManifest $serverBaseUrl
        $activeRoot = $Install
        if ($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED') {
            $ownerRecord=Join-Path (Split-Path -Parent $Install) ('.installer-owner-'+$session+'-'+($run -split '-')[-1]+'.json')
            $accepted = Read-CanonicalStartupLifecycle $Source $Install $control $ownerRecord @($delegation,$session,$attempt,$transaction)
            $activeRoot = [string]$accepted.active_code_root
        }
        $installed = PortableInventory $activeRoot
        if ($installed.sha256 -cne $receipt.sha256) { throw 'Machine placement inventory differs.' }
        if($null -ne $Lifecycle -and $Lifecycle.lifecycle_state -ceq 'INSTALLED' -and
            $Lifecycle.from_commit -ceq $SourceManifest.source_commit){
            $audit.reused_placement=Read-LabelProtectedReusedProof $frozen $parameters $SourceManifest $receipt $activeRoot $Script:LabelPlacementSession
            $audit.code_replaced=$false
        }else{$audit.code_replaced=($null -eq $preimage -or $preimage.sha256 -cne $receipt.sha256)}
        $audit.code_placement='PASS'; $audit.code_state='PRESENT'
        if ($existing -and $null -eq $Lifecycle -and $preimage.sha256 -cne $receipt.sha256) {
            $audit.replacement_rollback_root = [string](ReplacementPreimage $Install $preimage $backupsBefore)
        }
        $parent = Split-Path -Parent $Install
        $startupPreimage = Join-Path $parent ('.startup-update-install.'+$attempt)
        if (Test-Path -LiteralPath (Join-Path $startupPreimage 'preimage.json')) {
            $audit.startup_update_preimage=[ordered]@{path=[string]$startupPreimage;sha256=[string](Sha (Join-Path $startupPreimage 'preimage.json'))}
        }
        $menu = if ($testMode) { Join-Path $programData 'StartMenu' } else { [Environment]::GetFolderPath('CommonPrograms') }
        # Capture both original states before the first pending/shortcut mutation.
        foreach ($path in @($workerPendingPath, (Join-Path $menu 'KMTech 포장.lnk'))) {
            $present = Test-Path -LiteralPath $path
            if ($present) {
                $item = Get-Item -Force -LiteralPath $path -ErrorAction Stop
                if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Worker artifact is not an ordinary file.' }
            }
            $workerArtifacts += [pscustomobject]@{path=$path;present=$present;bytes=$(if ($present) { [IO.File]::ReadAllBytes($path) } else { $null })}
        }
        $audit.worker_pending=[ordered]@{install_id=$run;path=[string](Join-Path $parent 'update-control\worker-pending.json');
            inventory_sha256=$Worker.inventory_sha256}
        Save-LabelMachineMetadata $audit.worker_pending.path $workerPendingForPlacedCode
        $audit.machine_shortcut = Install-LabelMachineWorkerShortcut $Install $menu
        if (-not $audit.Contains('shortcuts')) { $audit.shortcuts = [ordered]@{} }
        $audit.shortcuts.published = @($audit.machine_shortcut.published) + @(Get-LabelManagedEmergencyPublished $Install)
        if ($null -ne $Script:LabelPlacementSession) {
            if ((Invoke-LabelPlacementSessionCommand $Script:LabelPlacementSession '' -Verify) -ne 0) { throw 'PLACEMENT_WAIT_EXPIRED' }
        }
        [void](Stop-LabelWriterFence -ControlRoot $control -SessionId $session -AttemptId $attempt -ReplacementTransactionId $transaction)
        $fenced=$false
        $audit.writer_fence.status='RELEASED_MACHINE_WORKER_PENDING'
        if ($null -ne $Script:LabelPlacementSession) { Close-LabelPlacementSession $Script:LabelPlacementSession 'CONFIRMED' }
        $audit.status='PASS_MACHINE_WORKER_PENDING';$audit.completed_at=[DateTime]::UtcNow.ToString('o')
        Save $auditFile $audit
        if ($EvidencePath) { Save (Full $EvidencePath 'EvidencePath') $audit }
        $workerArtifactsCommitted = $true
        'install_status=PASS_MACHINE_WORKER_PENDING'
        '작업자 준비 대기 — 작업자 계정에서 처음 실행한 뒤 설치 완료를 확인하세요.'
    } catch {
        $originalFailure=$_
        try {
            $startupPreimage=Join-Path (Split-Path -Parent $Install) ('.startup-update-install.'+$attempt)
            if (Test-Path -LiteralPath (Join-Path $startupPreimage 'preimage.json')) {
                $audit.startup_update_preimage=[ordered]@{path=[string]$startupPreimage;sha256=[string](Sha (Join-Path $startupPreimage 'preimage.json'))}
            }
            if ($existing -and $null -eq $Lifecycle -and $preimage.sha256 -cne $receipt.sha256 -and
                @(Get-ChildItem -Force -LiteralPath (Split-Path -Parent $Install) -Directory -ErrorAction SilentlyContinue |
                    Where-Object { $_.Name -like '.current.rollback.*' -and $_.FullName -notin $backupsBefore }).Count) {
                $audit.replacement_rollback_root=[string](ReplacementPreimage $Install $preimage $backupsBefore)
            }
        } catch { $audit.preimage_capture_failure=Get-LabelLaunchFailure $_ 'machine_preimage_capture' }
        $audit.status='RECOVERY_REQUIRED';$audit.failure=Get-LabelLaunchFailure $originalFailure 'machine_placement'
        Write-LabelInstallerRelayRecoveryGuidance -MachineWorker -Existing:$existing
        try{
            if($fenced -and $null -ne $parameters){
                . Invoke-LabelMachinePlacementRollback
                if($null -ne $Script:LabelPlacementSession){Close-LabelPlacementSession $Script:LabelPlacementSession 'REVERTED'}
            }
        }catch{
            $audit.status='ROLLBACK_FAILED';$audit.rollback.failure=Get-LabelLaunchFailure $_ 'machine_rollback'
        }
        if ($originalFailure.Exception.Data.Contains('placement_child_failure')) {
            $audit.placement_child_failure=$originalFailure.Exception.Data['placement_child_failure']
        }
        if ($null -ne $Script:LabelPlacementSession -and $Script:LabelPlacementSession.child_exit_unproven) { $audit.code_state='UNKNOWN' }
        try {
            Save $auditFile $audit
            if ($EvidencePath) { Save (Full $EvidencePath 'EvidencePath') $audit }
        } catch { }
        throw $originalFailure
    } finally {
        try {
            if (-not $workerArtifactsCommitted) {
                # Reporting failures must never skip either restoration attempt.
                foreach ($artifact in $workerArtifacts) {
                    if ($null -ne $workerPendingForPlacedCode -and
                        [StringComparer]::OrdinalIgnoreCase.Equals($artifact.path, $workerPendingPath)) { continue }
                    try {
                        if (Test-Path -LiteralPath $artifact.path) {
                            $item = Get-Item -Force -LiteralPath $artifact.path -ErrorAction Stop
                            if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Worker artifact restore path changed.' }
                        }
                        if ($artifact.present) {
                            $restoreTemp=$artifact.path+'.restore.'+[Guid]::NewGuid().ToString('N')
                            [IO.File]::WriteAllBytes($restoreTemp,[byte[]]$artifact.bytes)
                            if([IO.File]::Exists($artifact.path)){Invoke-LabelPinnedAtomicReplace $restoreTemp $artifact.path -Mode Replace}
                            else{Invoke-LabelPinnedAtomicReplace $restoreTemp $artifact.path -Mode Move}
                        }
                        elseif (Test-Path -LiteralPath $artifact.path) { Remove-Item -LiteralPath $artifact.path -ErrorAction Stop }
                    } catch {
                        $machineFenceReleaseProven=$false;$audit.status='ROLLBACK_FAILED'
                        $audit.worker_artifact_restore_failure=Get-LabelLaunchFailure $_ 'worker_artifact_restore'
                        try { Save $auditFile $audit } catch { }
                    }
                }
                if ($null -ne $workerPendingForPlacedCode) {
                    try {
                        if (Test-Path -LiteralPath $workerPendingPath) {
                            $item = Get-Item -Force -LiteralPath $workerPendingPath -ErrorAction Stop
                            if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Worker pending path changed.' }
                        }
                        Save-LabelMachineMetadata $workerPendingPath $workerPendingForPlacedCode
                        $audit.worker_pending_preservation='RETAINED_FOR_VERIFIED_CODE'
                        try { Save $auditFile $audit } catch { }
                    } catch {
                        $machineFenceReleaseProven=$false;$audit.status='ROLLBACK_FAILED'
                        $audit.worker_pending_preservation_failure=Get-LabelLaunchFailure $_ 'worker_pending_preservation'
                        try { Save $auditFile $audit } catch { }
                    }
                }
            }
            if ($null -ne $Script:LabelPlacementSession -and -not $Script:LabelPlacementSession.closed) {
                try { Close-LabelPlacementSession $Script:LabelPlacementSession 'ATTENTION' }
                catch {
                    $audit.guardian_failure=Get-LabelLaunchFailure $_ 'guardian_close'
                    try { Save $auditFile $audit } catch { }
                }
            }
        } finally {
            $Script:LabelPlacementSessionRequested=$false
            # An unproven child keeps the orphan fence; never race it with a writer.
            try {
                if ($fenced -and ($workerArtifactsCommitted -or $machineFenceReleaseProven) -and ($null -eq $Script:LabelPlacementSession -or -not $Script:LabelPlacementSession.child_exit_unproven)) {
                    try {
                        [void](Stop-LabelWriterFence -ControlRoot $control -SessionId $session -AttemptId $attempt -ReplacementTransactionId $transaction)
                        $fenced=$false;$audit.rollback.fence_released=$true
                        $audit.writer_fence.status='RELEASED_AFTER_MACHINE_ROLLBACK'
                    } catch {
                        $audit.status='ROLLBACK_FAILED';$audit.rollback.fence_released=$false
                        $audit.writer_fence.status='RELEASE_UNPROVEN'
                        $audit.rollback.fence_release_failure=Get-LabelLaunchFailure $_ 'machine_fence_release'
                    }
                } elseif($fenced -and -not $workerArtifactsCommitted) {
                    $audit.rollback.fence_released=$false
                    $audit.writer_fence.status='RETAINED_UNPROVEN_MACHINE_ROLLBACK'
                }
                if(-not $workerArtifactsCommitted){
                    try{Save $auditFile $audit;if($EvidencePath){Save (Full $EvidencePath 'EvidencePath') $audit}}catch{}
                }
            } finally {
                if ($null -ne $authority) {
                    try{Exit-LabelWriterSessionAuthority $authority}
                    catch{
                        $audit.status='ROLLBACK_FAILED'
                        $audit.rollback.authority_release_failure=Get-LabelLaunchFailure $_ 'machine_authority_release'
                        try{Save $auditFile $audit}catch{}
                        if($workerArtifactsCommitted){throw}
                    }
                }
                $Script:LabelWriterFenceInstalledIdentity=$null
            }
        }
    }
}

if (-not $SourceRoot) { $SourceRoot = $PSScriptRoot }
# Resolve the administrator target before imports, evidence allocation or profile access.
$machineWorker = $null
$workerArgumentsSupplied = $PSBoundParameters.ContainsKey('WorkerAccount') -or $PSBoundParameters.ContainsKey('WorkerSurveyInventory')
if ($ResumeRollbackAuditPath) {
    if ($workerArgumentsSupplied) { throw 'Rollback resume cannot be combined with worker installation.' }
} else { $machineWorker = Resolve-LabelMachineWorker (Get-LabelInstallerCaller) $WorkerAccount $WorkerSurveyInventory $workerArgumentsSupplied }
Assert-LabelMachineWorkerReadScope $machineWorker
