function Invoke-LabelLifecycleContextProcess([string]$Python,[string[]]$Arguments,[hashtable]$DelegationEnvironment) {
    Initialize-LabelChildOutputReader
    $startInfo=[Diagnostics.ProcessStartInfo]::new()
    $startInfo.FileName=$Python;$startInfo.Arguments=($Arguments|ForEach-Object{Arg ([string]$_)}) -join ' '
    $startInfo.UseShellExecute=$false;$startInfo.CreateNoWindow=$true
    $startInfo.RedirectStandardOutput=$true;$startInfo.RedirectStandardError=$true
    $before=@{};$process=$null
    try {
        foreach($name in $DelegationEnvironment.Keys){
            $before[$name]=$startInfo.EnvironmentVariables[$name]
            $startInfo.EnvironmentVariables[$name]=[string]$DelegationEnvironment[$name]
        }
        $process=[Diagnostics.Process]::Start($startInfo)
        $stdout=[LabelChildOutputReader]::Capture($process.StandardOutput)
        $stderr=[LabelChildOutputReader]::Capture($process.StandardError)
        $process.WaitForExit()
        [void]$stdout.Completion.Wait(1000);[void]$stderr.Completion.Wait(1000)
        return @{exit_code=[int]$process.ExitCode;
            stdout=(ConvertTo-LabelFailureOutput ([LabelChildOutputReader]::Snapshot($stdout)));
            stderr=(ConvertTo-LabelFailureOutput ([LabelChildOutputReader]::Snapshot($stderr)))}
    } finally {
        foreach($name in $before.Keys){
            if($null -eq $before[$name]){$startInfo.EnvironmentVariables.Remove($name)}
            else{$startInfo.EnvironmentVariables[$name]=[string]$before[$name]}
        }
        if($null -ne $process){$process.Dispose()}
    }
}

function Read-CanonicalStartupLifecycle([string]$HostRoot, [string]$Root,[string]$AuthorityRoot='', [string]$OwnerRecord='',[string[]]$DelegationValues=@()) {
    $parent = Split-Path -Parent $Root
    if (-not (Test-Path -LiteralPath (Join-Path $parent 'update-control')) -and
        -not (Test-Path -LiteralPath (Join-Path $parent 'removed.json'))) { return $null }
    $authorityArguments=@()
    $environment=@{}
    if($AuthorityRoot){
        if($DelegationValues.Count -ne 4){throw 'INSTALLER_AUTHORITY_INVALID'}
        $names=@('KMTECH_LABEL_WRITER_DELEGATION_TOKEN','KMTECH_LABEL_WRITER_DELEGATION_SESSION_ID',
            'KMTECH_LABEL_WRITER_DELEGATION_ATTEMPT_ID','KMTECH_LABEL_WRITER_DELEGATION_TRANSACTION_ID')
        for($index=0;$index -lt $names.Count;$index++){$environment[$names[$index]]=$DelegationValues[$index]}
        $authorityArguments=@('--machine-installer-authority','--installer-authority-root',$AuthorityRoot,'--installer-owner-record',$OwnerRecord)
    }
    $arguments=@('-I','-B',(Join-Path $HostRoot 'app\main.py'),'--label-match-lifecycle-context','--install-root',$parent,'--operation','install')+$authorityArguments
    $result=Invoke-LabelLifecycleContextProcess (Join-Path $HostRoot 'runtime\python.exe') $arguments $environment
    if($result.exit_code -ne 0){
        $failure=[InvalidOperationException]::new('SUPPORTED_REMOVAL_REQUIRED')
        $failure.Data['lifecycle_child_failure']=$result
        throw $failure
    }
    $context = $result.stdout.text | ConvertFrom-Json
    if ([string]$context.status -cne 'PASS') { throw 'SUPPORTED_REMOVAL_REQUIRED' }
    return $context
}
